window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0189", [{"word":"protectionist","ipa_uk":"/prəˈtekʃənɪst/","ipa_us":"/prəˈtekʃənɪst/","definition_zh":"保护主义者；主张用关税等措施保护本国产业的人；保护主义的；主张设限排外的","definition_en":"a person who wants domestic industry shielded from foreign competition, usually by tariffs or quotas; also the adjective describing such a policy","core_image":"一道高墙立在港口，墙内的作坊照旧开工，墙外的货柜停在检查线外等着开箱","scene":"议会听证会上，一位业界代表反复强调本国工厂被低价进口货压垮，要求加征关税。The protectionist insisted that tariffs were the only way to keep the domestic mills open.","sceneCN":"这里指「主张用关税等措施保护本国产业的人」，对应第 1 个义项：以贸易壁垒挡住外来竞争的支持者；句意为这位保护主义者坚称，征收关税是让本国工厂继续开工的唯一办法。画面要点：听证席、成排货柜、工厂烟囱。","pos":[{"tag":"n.","zh":"保护主义者；主张保护本国产业的人（可指个人、团体或政党）"},{"tag":"adj.","zh":"保护主义的；主张设限保护本国产业的"}],"collocations":[{"phrase":"protectionist measures","zh":"保护主义措施"},{"phrase":"protectionist policies","zh":"保护主义政策"},{"phrase":"protectionist sentiment","zh":"保护主义情绪"},{"phrase":"a staunch protectionist","zh":"坚定的保护主义者"},{"phrase":"protectionist lobby","zh":"保护主义游说团体"},{"phrase":"turn protectionist","zh":"转向保护主义"}],"forms":[{"label":"复数","form":"protectionists"},{"label":"比较级（形容词用法，更多用 more 构成）","form":"more protectionist"},{"label":"最高级（形容词用法，更多用 most 构成）","form":"most protectionist"},{"label":"名词（保护主义）","form":"protectionism"},{"label":"名词（保护；保护措施）","form":"protection"},{"label":"形容词（保护性的）","form":"protective"},{"label":"动词（保护）","form":"protect"}],"derivatives":[{"word":"protectionism","pos":"n.","zh":"保护主义（以关税与配额挡住外来竞争的政策主张）"},{"word":"protection","pos":"n.","zh":"保护；保护措施；庇护"},{"word":"protective","pos":"adj.","zh":"保护的；防护的；有呵护之意的"},{"word":"protectively","pos":"adv.","zh":"以保护的方式"},{"word":"protector","pos":"n.","zh":"保护者；防护装置"},{"word":"unprotected","pos":"adj.","zh":"未受保护的；无防护的"}],"senses":[{"no":"01","title":"A backer of tariff walls","titleCN":"主张以关税筑墙的人","definition":"a person who wants duties placed on imported goods so that home producers can compete","definitionCN":"主张对进口货物征税、使本国生产者能够竞争的人","example":"The protectionist argued that a duty on steel would save the mills.","exampleCN":"这位保护主义者主张，对钢材征税才能救活那些工厂。","why":"the Latin verb behind protect means to cover something in front, and -ist marks the person who wants that cover put up.","whyCN":"protect 背后的拉丁动词意为「在前面遮住」，而表人后缀标记的正是想要架起这层遮挡的人。"},{"no":"02","title":"A supporter of quotas and licences","titleCN":"主张配额与许可证限制的人","definition":"a person who prefers limits on the quantity of imports rather than duties alone","definitionCN":"主张用进口数量限制或许可证制度、而不只靠征税的人","example":"Quota protectionists blocked the shipment at the border for a month.","exampleCN":"主张配额限制的人让这批货在边境压了整整一个月。","why":"a tariff raises the price of imports while a quota caps their number, and both are ways of putting the same cover in place.","whyCN":"关税抬高进口货的价格，配额限制进口货的数量，两者都是在架同一道遮挡，只是手段不同。"},{"no":"03","title":"The adjective for such a policy","titleCN":"形容词：保护主义的","definition":"describing a measure, government or era that shields domestic producers from imports","definitionCN":"形容某项措施、某届政府或某个时期以壁垒挡住进口、护住本国生产者","example":"A protectionist turn in the 1930s deepened the slump.","exampleCN":"二十世纪三十年代的保护主义转向加深了那场衰退。","why":"English lets the person-noun double as an adjective, so the label of the advocate becomes the label of the policy he wants.","whyCN":"英语允许表人的名词直接用作形容词，于是主张者的标签也就成了他所要的政策的标签。"},{"no":"04","title":"A single sector's shield","titleCN":"某一行业单独立起的屏障","definition":"a person or group seeking protection for one branch of production, such as farming or steel","definitionCN":"为某一生产部门（如农业或钢铁）单独争取保护的人或团体","example":"Dairy protectionists won a price floor at the expense of consumers.","exampleCN":"乳业保护主义者争到了价格下限，代价由消费者承担。","why":"the general label is regularly narrowed by a sector word in front of it, because duties are almost always written for one product line.","whyCN":"这个总称常被前面的行业词收窄，因为关税几乎总是针对某一类产品来写的。"},{"no":"05","title":"A member of a shielding bloc","titleCN":"保护主义阵营中的一员","definition":"a politician or party aligned with others who vote for import barriers","definitionCN":"与其他主张进口壁垒者站在一起投票的政客或政党","example":"The protectionists in the upper house formed a bloc with the farm lobby.","exampleCN":"上院的保护主义者与农业游说团体结成了一个阵营。","why":"once the word names a stance, people who share it can be counted as a bloc, and the noun shifts from a person to a voting group.","whyCN":"一旦这个词指一种立场，持同一立场的人便可被数成一个阵营，名词也就从个人转为投票集团。"},{"no":"06","title":"A defender of home jobs","titleCN":"以保住本国就业为由设限的人","definition":"a person who frames import limits as a way of saving local employment","definitionCN":"把限制进口说成保住本地就业手段的人","example":"The union leader ran as a protectionist and promised to keep the plant open.","exampleCN":"这位工会领袖以保护主义者的姿态参选，承诺让工厂继续开工。","why":"the argument for the cover is usually jobs, so the label is often claimed by those who speak for workers rather than for owners.","whyCN":"架起遮挡的理由通常是就业，因此这个标签常被替工人说话的人认领，而不是替业主说话的人。"},{"no":"07","title":"A cultural or technological blocker","titleCN":"在文化或技术领域设防的人","definition":"a person who wants foreign media, platforms or firms kept out in the name of national identity or security","definitionCN":"以国家认同或安全为名，要求把外国媒体、平台或企业挡在门外的人","example":"Cultural protectionists pressed for a quota on imported films.","exampleCN":"文化保护主义者力推对进口影片设配额。","why":"the same logic of a wall in front of something valuable is easily moved from steel to screens, so the word now covers non-trade barriers too.","whyCN":"「在贵重之物前面立墙」这套逻辑很容易从钢铁搬到屏幕上，因此这个词如今也覆盖非贸易壁垒。"},{"no":"08","title":"Anyone who walls a system off","titleCN":"抽象义：把某个系统与外部隔开的人","definition":"in general use, a person who prefers closing a system to opening it to outside competition or influence","definitionCN":"泛指宁可封闭一个系统、也不愿让它向外部竞争或影响开放的人","example":"In the debate over open science, he played the protectionist, guarding the old review system.","exampleCN":"在关于开放科学的争论中，他扮演了保护主义者的角色，守护旧的评审制度。","why":"the abstract sense drops the tariff and keeps only the gesture: keep the inside safe by keeping the outside out.","whyCN":"抽象义丢掉了关税，只留下那个动作：把外面挡在门外，里面就安全了。"}],"etymology":{"intro":{"en":"Protectionist is an English coinage from protection plus the person suffix -ist, and protection reached English through French from Latin protegere 'to cover in front'. Dates are approximate.","cn":"protectionist 是英语用 protection 加表人后缀构成的词，而 protection 经法语上溯到拉丁语，本义是「在前面遮住」。年代均为约数。"},"items":[{"era":"LATIN TEGERE","en":"Tegere meant 'to cover' and was a common Latin verb for roofing, clothing and hiding; its pre-Latin origin is not established, so any older root proposed for it is a reconstruction.","cn":"tegere 意为「遮盖」，是拉丁语中用于盖屋顶、穿衣与掩藏的常用动词；它在拉丁语之前的来源未得到证明，凡为其提出的更早词根均属重构形式。"},{"era":"LATIN PROTEGERE","en":"Pro- 'in front' plus tegere gave protegere 'to cover in front, defend, shelter', the verb behind all the English protection words.","cn":"表示「在前」的拉丁前缀加 tegere 构成 protegere「在前面遮住、护卫、庇护」，这就是英语中一整族 protection 词汇的源头动词。"},{"era":"FRENCH PROTECTION","en":"Middle French protection entered English in the fourteenth century with the general sense of shielding a person or a right from harm.","cn":"中古法语 protection 在十四世纪进入英语，泛指使人或权利免受侵害。"},{"era":"POLITICAL ECONOMY","en":"From the early nineteenth century protection was applied to a national policy of shielding home producers with duties, and protectionism named that policy while protectionist named its supporter.","cn":"从十九世纪初起，protection 被用于指以关税护住本国生产者的国家政策，protectionism 指这套政策，protectionist 则指支持它的人。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin root of tegere is disputed, and the first written use of the political sense is not pinned to a single dated source.","cn":"来源不确定（更深词源）：tegere 在拉丁语之前的词根存在争议，政治义的最早书证也无法系于某一个确切年代。"}]},"similar":{"note":{"en":"Group one holds words built on the same protective stock that are easily mistaken for the person-noun; group two holds rivals that share the idea of shutting imports out.","cn":"第一组是同出「遮挡」词干、容易被误当成这个表人名词的词；第二组是同样含「把进口挡在外面」之意的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"protection","ipa":"/prəˈtekʃən/","tag":"the act, not the person","definition":"The noun for the act or system of shielding; a protection is a measure, whereas a protectionist is the person who wants it.","definitionCN":"指遮挡的动作或制度本身；一项 protection 是措施，而 protectionist 是想要这项措施的人。"},{"word":"protectionism","ipa":"/prəˈtekʃənɪzəm/","tag":"the doctrine","definition":"The policy doctrine rather than its adherent, formed with the suffix that names systems of thought.","definitionCN":"指政策主张本身而非其拥护者，由表示「主义、体系」的后缀构成。"},{"word":"protective","ipa":"/prəˈtektɪv/","tag":"an adjective of care","definition":"Describes something that shields, often in a personal or safety sense, as protective clothing; it carries no trade meaning.","definitionCN":"形容起遮挡作用之物，多用于人身或安全语境，如防护服；不含贸易含义。"},{"word":"protectorate","ipa":"/prəˈtektərət/","tag":"a territory, not a person","definition":"A state under the control of a stronger power that claims to shelter it; the word names the land, not the advocate.","definitionCN":"指受强国控制、由该国声称予以庇护的地区；这个词指土地，不指主张者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tariff backer","ipa":"/ˈtærɪf ˈbækə/","tag":"one instrument only","definition":"A descriptive phrase for someone who pushes duties specifically; a protectionist may also use quotas and licences.","definitionCN":"专指推动征收关税者的描述性说法；保护主义者也可能使用配额与许可证。"},{"word":"isolationist","ipa":"/ˌaɪsəˈleɪʃənɪst/","tag":"wider withdrawal","definition":"Someone who wants a country to stay out of foreign entanglements altogether; the focus is political and military as well as economic.","definitionCN":"主张国家整体上不卷入对外纠葛的人；其关注点除经济外还包括政治与军事。"},{"word":"mercantilist","ipa":"/ˈmɜːkəntɪlɪst/","tag":"trade surplus first","definition":"A backer of the old doctrine that exports should exceed imports; protection is one tool of that doctrine, not its whole content.","definitionCN":"支持「出口应多于进口」这一旧学说的人；保护只是该学说的工具之一，而非全部内容。"},{"word":"nationalist","ipa":"/ˈnæʃənəlɪst/","tag":"identity, not duties","definition":"Someone who puts national interests first in general; a protectionist makes that preference concrete in trade rules.","definitionCN":"泛指把本国利益置于首位的人；保护主义者则把这种偏好落实到贸易规则上。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base verb means to cover something in front, and the person suffix marks the one who wants that cover erected.","cn":"基础动词意为「在前面遮住」，表人后缀标记的正是想架起这层遮挡的人。"},{"en":"The family runs protect, protection, protectionism, protective, protector and unprotected.","cn":"同族词包括保护、保护措施、保护主义、防护的、保护者与未受保护的。"},{"en":"Fixed phrases mark the trade sense: protectionist measures, protectionist policies, protectionist sentiment.","cn":"固定搭配标出贸易义：保护主义措施、保护主义政策、保护主义情绪。"},{"en":"The word pairs with a sector in front of it: dairy, steel and film protectionists.","cn":"这个词前面常加行业名：乳业、钢铁与电影的保护主义者。"},{"en":"Its opposite number is the free-trader, who wants the wall taken down.","cn":"它的对立角色是自由贸易派，那一方想把墙拆掉。"}],"abstract":[{"en":"Picture a wall built at a harbour, with workshops busy inside and containers waiting outside.","cn":"想象港口砌起一道墙，墙内作坊忙个不停，墙外货柜排队等候。"},{"en":"Picture a greenhouse whose glass lets light in but keeps cold air out.","cn":"想象一间温室，玻璃让光进来，却把冷空气挡在外面。"},{"en":"Picture a hand closing a lid whenever something new is about to fall in.","cn":"想象一只手，每当有新东西要落进来时就盖上盖子。"}]},"examples":[{"en":"Protectionists blocked the free-trade agreement in the Senate.","cn":"保护主义者在参议院阻挠了这项自由贸易协定。"},{"en":"The party turned protectionist after losing three industrial seats.","cn":"该党在丢掉三个工业选区后转向保护主义。"},{"en":"Economists warned that protectionist habits raise prices for everyone.","cn":"经济学家警告说，保护主义的做法会推高所有人的物价。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「在前遮住 + 主张者」——主张把外来货挡在门外的人 → 保护主义者","word":"protectionist"},"root":"英语 protection 加表示「从事者」的表人后缀；protection 经法语出自拉丁 protegere「在前面遮住」，由表示「在前」的前缀与 tegere「遮盖」构成。tegere 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one gesture: a cover is raised in front of something valuable, and the word then moves from the person who raises it, to the policy, to the sector, the bloc, the jobs argument, the cultural wall and finally to any closed system.","cn":"八个义项沿同一个动作展开：在贵重之物前面架起遮挡；这个词再从架墙的人，依次移到政策、行业、阵营、就业理由、文化壁垒，最后落到任何封闭的系统上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wall at the harbour, workshops busy inside, containers held outside.","cn":"核心意象：港口的一道墙，墙内作坊照常开工，墙外货柜被拦住。"},"chain":["RAISE A COVER","SHIELD PRODUCERS","LIMIT THE INFLOW","NAME THE POLICY","NAME THE ADVOCATE","CLOSE THE SYSTEM"],"branches":[{"senses":"01","en":"BASE FIGURE: the person who wants the cover raised, which is the literal reading of the label.","cn":"基础形象：想要架起遮挡的人，这是该标签最本初的读法。"},{"senses":"02 · 03","en":"INSTRUMENT AND LABEL: whether the tool is a duty or a quota, the same stance can be named as a person or as a policy.","cn":"手段与标签：无论工具是关税还是配额，同一种立场既可用人来表示，也可用政策来表示。"},{"senses":"04 · 05","en":"ONE SECTOR, MANY VOTES: the shield is drawn for a single product line, and those who want it gather into a bloc.","cn":"一个行业、多张选票：屏障是为单一产品线画的，想要它的人则聚成一个阵营。"},{"senses":"06 · 07","en":"WHY AND WHERE: the justification is local jobs, and the wall is later moved to films, platforms and firms.","cn":"理由与场所：理由是本地就业，墙后来又被搬到影片、平台与企业上。"},{"senses":"08","en":"CLOSED SYSTEM: the tariff drops away and only the preference for closure remains.","cn":"封闭系统：关税消失了，只剩下对封闭的偏好。"}]},"affixes":{"intro":{"en":"Protectionist is built from an English noun plus a person suffix, while the noun itself rests on a Latin prefix and root that also build other English words.","cn":"protectionist 由英语名词加表人后缀构成，而这个名词本身又立在一个拉丁前缀与词根上，这两部分还构成其他英语词。"},"latinIntro":{"en":"Latin tegere 'to cover' yields protegere, protectio and protector; the prefix pro- adds the sense of placing something in front.","cn":"拉丁 tegere「遮盖」衍生出 protegere、protectio 与 protector；那个表示「在前」的拉丁前缀增添了「置于前方」的意思。"},"items":[{"word":"pro-","structure":"pro- (Latin prefix, 'in front, before')","meaning":"in front; before","meaningCN":"在前；预先","example":"The prefix places the covering between the thing and the danger.","exampleCN":"这个前缀把遮挡物放在事物与危险之间。"},{"word":"tegere","structure":"tegere (Latin verb, third conjugation)","meaning":"to cover, roof over","meaningCN":"遮盖；盖顶","example":"The root supplies the image of a roof over something.","exampleCN":"这个词根提供「在事物上方加顶」的意象。"},{"word":"protegere","structure":"pro- + tegere","meaning":"to cover in front, defend","meaningCN":"在前面遮住；护卫","example":"The soldiers protected the bridge.","exampleCN":"士兵们护住了那座桥。"},{"word":"protection","structure":"protect + -ion (act or state)","meaning":"the act of shielding","meaningCN":"遮挡的行为或状态","example":"The law offers protection to whistle-blowers.","exampleCN":"这条法律为举报人提供保护。"},{"word":"-ist","structure":"-ist (person suffix, from Greek -istes)","meaning":"a person who practices or supports something","meaningCN":"从事或支持某事的人","example":"The suffix turns a doctrine into its adherent.","exampleCN":"这个后缀把一种主张变成它的拥护者。"},{"word":"protectionism","structure":"protection + -ism (system or doctrine)","meaning":"the doctrine of shielding home industry","meaningCN":"护住本国产业的政策主张","example":"Protectionism raised the price of imported grain.","exampleCN":"保护主义抬高了进口谷物的价格。"},{"word":"protective","structure":"protect + -ive (tending to)","meaning":"tending to shield","meaningCN":"起防护作用的","example":"Workers wore protective gloves.","exampleCN":"工人戴着防护手套。"},{"word":"protector","structure":"protect + -or (one who acts)","meaning":"one who shields another","meaningCN":"保护他人者","example":"He acted as her protector for years.","exampleCN":"他多年来充当她的保护人。"},{"word":"unprotected","structure":"un- (not) + protected","meaning":"not shielded","meaningCN":"未受保护的","example":"Unprotected workers bore the first layoffs.","exampleCN":"没有保护措施的工人最先被裁员。"}],"latinEntries":[{"word":"tegere","structure":"tegere, texi, tectum (verb, third conjugation)","meaning":"to cover, roof, hide","meaningCN":"遮盖；盖顶；掩藏"},{"word":"protegere","structure":"protegere, protexi, protectum (verb, third conjugation)","meaning":"to cover in front, defend","meaningCN":"在前面遮住；护卫"},{"word":"protectio","structure":"protectio, protectionis (f., third declension)","meaning":"a covering, a defence","meaningCN":"遮挡；防护"},{"word":"protector","structure":"protector, protectoris (m., third declension)","meaning":"a defender, protector","meaningCN":"护卫者；保护人"}]}},{"word":"economic integration","ipa_uk":"/ˌiːkəˈnɒmɪk ˌɪntɪˈɡreɪʃən/","ipa_us":"/ˌekəˈnɑːmɪk ˌɪntɪˈɡreɪʃən/","definition_zh":"经济一体化；消除国与国之间的经济壁垒、使市场合为一体的过程与状态","definition_en":"the process by which separate national economies are linked into one market by removing barriers and aligning rules","core_image":"地图上相邻几国的边境线被虚线连起，货物、资金与人沿着虚线来回流动","scene":"谈判桌上，几国代表逐项划掉关税表上的条目，地图上的边境线被一条条虚线接了起来。Decades of negotiation produced deep economic integration among the member states.","sceneCN":"这里指「消除国家间经济壁垒、使市场合为一体的过程」，对应第 1 个义项：把分立的国民经济连接成一体；句意为数十年的谈判使成员国之间形成了深度的经济一体化。画面要点：谈判长桌、关税清单、被虚线连接的国界。","pos":[{"tag":"n.","zh":"经济一体化；经济整合（指过程，也指整合后的状态）"}],"collocations":[{"phrase":"deepen economic integration","zh":"深化经济一体化"},{"phrase":"regional economic integration","zh":"区域经济一体化"},{"phrase":"economic integration agreement","zh":"经济一体化协定"},{"phrase":"the degree of economic integration","zh":"经济一体化的程度"},{"phrase":"deeper economic integration with neighbours","zh":"与邻国更紧密的经济一体化"},{"phrase":"a driver of economic integration","zh":"经济一体化的推动因素"}],"forms":[{"label":"名词短语（本词）","form":"economic integration"},{"label":"复数（少见，指多轮或多类整合）","form":"economic integrations"},{"label":"动词（整合）","form":"integrate"},{"label":"名词（整合；一体化）","form":"integration"},{"label":"形容词（已整合的）","form":"integrated"},{"label":"形容词（起整合作用的）","form":"integrative"},{"label":"名词（经济）","form":"economy"},{"label":"形容词（经济的）","form":"economic"}],"derivatives":[{"word":"integrate","pos":"v.","zh":"使合为一体；整合；融入"},{"word":"integrated","pos":"adj.","zh":"已整合的；各部分协调运转的"},{"word":"integrative","pos":"adj.","zh":"起整合作用的；把部分纳入整体的"},{"word":"integrator","pos":"n.","zh":"整合者；把各部分合成系统的一方"},{"word":"disintegrate","pos":"v.","zh":"解体；分裂成部分"},{"word":"economist","pos":"n.","zh":"经济学家"}],"senses":[{"no":"01","title":"Removing barriers between economies","titleCN":"消除国民经济之间的壁垒","definition":"the process of taking down tariffs, quotas and other obstacles that separate national markets","definitionCN":"拆除把各国市场隔开的关税、配额与其他障碍的过程","example":"Tariff cuts were the first step in economic integration.","exampleCN":"削减关税是经济一体化的第一步。","why":"the Latin root of integration means 'made whole', so the phrase describes separate economies being put back into one piece.","whyCN":"integration 的拉丁词根意为「使成为完整的一体」，因此这个短语说的是把分立的国民经济重新拼成一块。"},{"no":"02","title":"The resulting single market","titleCN":"由此形成的统一市场","definition":"the merged market that appears once goods, services and capital can move freely across borders","definitionCN":"当货物、服务与资本可以跨境自由流动后形成的合并市场","example":"A customs union is an early stage of economic integration.","exampleCN":"关税同盟是经济一体化的早期阶段。","why":"the same noun names both the work and its outcome, so one phrase covers the process and the arrangement it produces.","whyCN":"同一个名词既指工作又指成果，因此一个短语同时涵盖过程与过程造成的安排。"},{"no":"03","title":"A regional bloc of neighbours","titleCN":"邻国结成的区域集团","definition":"the grouping of nearby countries that coordinate trade rules and often share institutions","definitionCN":"邻近国家组成的集团，它们协调贸易规则，往往还共享机构","example":"Economic integration in Europe began with coal and steel.","exampleCN":"欧洲的经济一体化最初从煤与钢开始。","why":"proximity lowers transport costs, so integration is usually regional before it becomes global, and the phrase names that grouping.","whyCN":"距离近则运输成本低，因此一体化通常先区域后全球，这个短语便用来指那样的集团。"},{"no":"04","title":"Linking financial markets","titleCN":"金融市场的相互接通","definition":"the merging of banking, bond and equity markets so that capital moves across borders with little friction","definitionCN":"银行、债券与股票市场的合并，使资本能低摩擦地跨境流动","example":"Economic integration of capital markets narrowed interest-rate gaps.","exampleCN":"资本市场的一体化缩小了利率差距。","why":"integration of goods invites integration of payments and credit, so finance follows trade into the same phrase.","whyCN":"货物的一体化会带出支付与信贷的一体化，金融便跟着贸易一起进入同一个说法。"},{"no":"05","title":"An objective written into treaties","titleCN":"写进条约的目标条款","definition":"a stated goal that governments commit to in agreements and schedules of reform","definitionCN":"政府在协定与改革日程中承诺实现的目标","example":"The treaty lists economic integration as its central aim.","exampleCN":"该条约把经济一体化列为核心目标。","why":"a process that can be promised becomes a policy objective, so the phrase moves from description to commitment.","whyCN":"能被承诺的过程就成了政策目标，于是这个短语从描述转为承诺。"},{"no":"06","title":"A measurable degree of linkage","titleCN":"可测量的联系程度","definition":"the extent to which prices, trade shares and business cycles move together across countries","definitionCN":"各国价格、贸易占比与商业周期同步变动的程度","example":"Researchers rank countries by their degree of economic integration.","exampleCN":"研究者按经济一体化程度给各国排序。","why":"once integration is a process it can be measured, so the phrase also serves as a variable in empirical work.","whyCN":"一体化既然是一个过程，就可以被测量，因此这个短语也成了实证研究中的一个变量。"},{"no":"07","title":"Joining up one network or sector","titleCN":"某一网络或部门之间的对接","definition":"the cross-border linking of a single system, such as power grids, rail links or data rules","definitionCN":"单一系统（如电网、铁路线或数据规则）的跨境对接","example":"Grid interconnection is a quiet form of economic integration.","exampleCN":"电网互联是一种不声张的经济一体化。","why":"markets are made of concrete networks, so the phrase narrows to one sector whenever a single system is joined across a border.","whyCN":"市场由具体的网络构成，因此只要某个系统跨境接通，这个短语就收窄到那一个部门。"},{"no":"08","title":"Abstract: making parts into a whole","titleCN":"抽象义：把部分合成整体","definition":"in general use, the act of combining separate elements into a coherent unit, applied to economies by metaphor","definitionCN":"泛指把分离的要素合成协调的整体，用在经济上属于比喻延伸","example":"The same logic of integration can be seen in a merged university system.","exampleCN":"同样的整合逻辑也能在一套合并后的大学体系里看到。","why":"the abstract sense keeps only the arithmetic of parts and whole and lets the economic content drop away.","whyCN":"抽象义只留下「部分与整体」的算式，经济内容则被去掉。"}],"etymology":{"intro":{"en":"Economic integration joins a Greek word for household management with a Latin word for making whole. Both halves came into English through French. Dates are approximate.","cn":"economic integration 把希腊语中表示「家务管理」的词与拉丁语中表示「使完整」的词合在一起，两部分都经法语进入英语。年代均为约数。"},"items":[{"era":"GREEK OIKONOMIA","en":"Oikos 'house' plus nomos 'management, rule' gave oikonomia, the running of a household; nomos is generally connected to nemein 'to distribute, allot'.","cn":"oikos「家宅」加 nomos「管理、规则」构成 oikonomia，即管理家务；nomos 一般被认为与 nemein「分配、分给」相关。"},{"era":"GREEK OIKONOMIKOS","en":"The adjective oikonomikos meant 'skilled in household management' and widened in early modern usage, through French, to the wealth and resources of a state.","cn":"形容词 oikonomikos 意为「善于治家的」，到近代经法语扩用到国家的财富与资源上。"},{"era":"LATIN INTEGER","en":"In- 'not' plus tangere 'to touch' gave integer 'untouched, whole', the source of the idea that integration is a restoration of a whole rather than a fresh construction.","cn":"表示否定的拉丁前缀加 tangere「触碰」构成 integer「未被触动的、完整的」，这正是「一体化是复原整体而非新建」这一想法的来源。"},{"era":"LATIN INTEGRARE","en":"Integrare 'to make whole, renew' produced integratio 'a renewing', which English took as integration in the seventeenth century.","cn":"integrare「使完整、更新」产生 integratio「更新」，英语在十七世纪以 integration 的形式借入。"},{"era":"POSTWAR ECONOMICS","en":"The phrase economic integration became standard in the study of European reconstruction after the Second World War, when customs unions and common markets were designed on paper.","cn":"第二次世界大战后研究欧洲重建时，economic integration 成为标准说法，当时关税同盟与共同市场都先在纸面上设计。"}]},"similar":{"note":{"en":"Group one holds words that look like relatives of integration but carry different meanings; group two holds phrases for arrangements that sit close to the idea without being it.","cn":"第一组是形似 integration 但含义不同的词；第二组是接近这一概念、却并不等同的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"integral","ipa":"/ˈɪntɪɡrəl/","tag":"essential, not joined","definition":"An adjective meaning necessary to a whole, as in an integral part; it describes a role rather than a process of joining.","definitionCN":"形容词，意为「整体中不可缺少的」，如不可或缺的组成部分；它描述角色，而非合并的过程。"},{"word":"integrity","ipa":"/ɪnˈteɡrəti/","tag":"wholeness of character","definition":"The state of being whole and uncorrupted, used of data and of persons; it shares the root but not the market sense.","definitionCN":"指完整而未受破坏的状态，可用于数据，也可用于人的品格；同根但不含市场义。"},{"word":"integrated","ipa":"/ˈɪntɪɡreɪtɪd/","tag":"the resulting state","definition":"An adjective for something already joined into one system, as an integrated grid; the phrase names the process that produced it.","definitionCN":"形容已经并入一个系统的事物，如互联电网；而本词短语指造成这一状态的过程。"},{"word":"integrationist","ipa":"/ˌɪntɪˈɡreɪʃənɪst/","tag":"person, often social","definition":"A person who favours bringing groups together, most often in racial or social policy; it is not the trade term.","definitionCN":"主张把不同群体合为一体的人，多用于种族或社会政策；不是贸易术语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"economic union","ipa":"/ˌiːkəˈnɒmɪk ˈjuːniən/","tag":"a stage, not the process","definition":"A specific arrangement in which members align policies as well as trade; integration is the movement that may lead to such a union.","definitionCN":"一种具体安排，成员除贸易外还统一政策；一体化则是可能导致这种安排的运动。"},{"word":"single market","ipa":"/ˈsɪŋɡəl ˈmɑːkɪt/","tag":"the outcome","definition":"The finished space in which goods, services, capital and people circulate freely; it is the product of integration, not the activity.","definitionCN":"货物、服务、资本与人自由流动的成品空间；它是一体化的产物，而非活动本身。"},{"word":"globalization","ipa":"/ˌɡləʊbəlaɪˈzeɪʃən/","tag":"worldwide reach","definition":"The widening of linkages across the whole world; economic integration can stay regional and need not cover the globe.","definitionCN":"联系扩展到全世界的加宽过程；经济一体化可以是区域性的，未必覆盖全球。"},{"word":"convergence","ipa":"/kənˈvɜːdʒəns/","tag":"one symptom","definition":"The narrowing of gaps in income or prices between countries; convergence is often evidence of integration rather than the whole of it.","definitionCN":"国家间收入或价格差距的缩小；趋同往往是一体化的证据，而不是一体化本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The second element comes from a Latin word meaning untouched and whole, so integration is a return to one piece.","cn":"后半部分出自拉丁语中表示「未被触动、完整」的词，因此一体化是回到完整的一整块。"},{"en":"The first element goes back to Greek words for house and management, so economics began as housekeeping.","cn":"前半部分上溯到希腊语中表示「家宅」与「管理」的词，可见经济学最初就是管家。"},{"en":"Fixed phrases mark the process: deepen economic integration, regional economic integration, economic integration agreement.","cn":"固定搭配标出这一过程：深化经济一体化、区域经济一体化、经济一体化协定。"},{"en":"The ladder runs from free-trade area to customs union to common market to economic union.","cn":"阶梯从自由贸易区到关税同盟，再到共同市场，最后到经济联盟。"},{"en":"Its natural opposite is fragmentation or disintegration, when links are cut.","cn":"它的天然反面是碎片化或解体，即联系被切断。"}],"abstract":[{"en":"Picture several ponds joined by canals until the water level is the same everywhere.","cn":"想象几个水塘被水渠接通，直到各处水位一致。"},{"en":"Picture a torn map taped back together so no border line is left dangling.","cn":"想象一张撕破的地图被重新粘合，没有一条国界线再悬着。"},{"en":"Picture clocks in different rooms being set to the same hour.","cn":"想象不同房间里的钟都被拨到同一个时刻。"}]},"examples":[{"en":"Economic integration lowered the cost of shipping parts across the border.","cn":"经济一体化降低了零部件跨境运输的成本。"},{"en":"Small states often seek economic integration to reach larger markets.","cn":"小国常寻求经济一体化，以进入更大的市场。"},{"en":"Without common rules, economic integration stalls at the first dispute.","cn":"缺少共同规则时，经济一体化往往在第一场争端上就停住。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「家政管理 + 使成完整」——把一国家家户户的经济合成完整的一块 → 经济一体化","word":"economic integration"},"root":"economic 出自希腊 oikonomia「家务管理」，由 oikos「家宅」与 nomos「管理」构成；integration 出自拉丁 integrare「使完整」，其源头 integer 由表示否定的前缀与 tangere「触碰」构成，本义「未被触动的」。两部分均经法语进入英语。","sensesIntro":{"en":"Eight senses follow one movement: barriers come down, markets merge, neighbours form a bloc, capital joins in, treaties promise it, researchers measure it, single networks are hooked up, and finally any set of parts is made whole.","cn":"八个义项沿同一个动作展开：壁垒倒下，市场合并，邻国结成集团，资本随之接通，条约把它写成承诺，研究者把它变成可测之量，单个网络被接上，最后任何一组部分都被合成整体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a border line replaced by a dotted line along which goods and money travel.","cn":"核心意象：国界线被一条虚线取代，货物与资金沿虚线往来。"},"chain":["TAKE BARRIERS DOWN","MERGE THE MARKETS","BIND NEIGHBOURS","LINK CAPITAL","WRITE IT INTO TREATIES","RESTORE ONE WHOLE"],"branches":[{"senses":"01 · 02","en":"WORK AND RESULT: taking the barriers down and the merged market that appears are the same phrase seen from two ends.","cn":"工作与结果：拆掉壁垒与由此出现的合并市场，是同一短语的首尾两面。"},{"senses":"03 · 04","en":"WHO AND WHAT: neighbours group first because distance is cheap to cross, and capital follows goods across the same line.","cn":"谁与什么：邻国先成集团，因为距离容易跨越；资本则跟着货物沿同一条线流动。"},{"senses":"05","en":"PROMISE: a process that can be scheduled becomes a clause governments sign.","cn":"承诺：能被排进日程的过程，变成政府签署的条款。"},{"senses":"06 · 07","en":"MEASURE AND NETWORK: linkage can be counted in price gaps and also built as a grid or a rail link.","cn":"测量与网络：联系既可用价格差来计数，也可建成电网或铁路线。"},{"senses":"08","en":"ONE WHOLE: the economic content drops out and only the joining of parts remains.","cn":"完整一体：经济内容退出，只剩下部分的拼接。"}]},"affixes":{"intro":{"en":"The phrase is made of two learned borrowings, each readable morpheme by morpheme: a Greek compound for the first word and a Latin prefix plus root for the second.","cn":"这个短语由两个学术借词组成，都可按语素读出：前者是希腊语复合词，后者是拉丁前缀加词根。"},"latinIntro":{"en":"Latin integer and integrare supply integrate, integral, integrity and disintegrate; the Greek compound behind economic supplied economy and economist.","cn":"拉丁 integer 与 integrare 衍生出整合、必需的、完整性与解体等词；economic 背后的希腊复合词则衍生出经济与经济学者。"},"items":[{"word":"oikos","structure":"oikos (Greek noun, 'house, household')","meaning":"house; household","meaningCN":"家宅；家户","example":"The root names the household as the first unit of management.","exampleCN":"这个词根把家户当作管理的最初单位。"},{"word":"nomos","structure":"nomos (Greek noun, 'management, rule, law')","meaning":"management; rule","meaningCN":"管理；规则","example":"The second element supplies the idea of orderly running.","exampleCN":"第二个成分带来「有序运转」的意思。"},{"word":"integer","structure":"integer (Latin adjective, 'untouched, whole')","meaning":"whole; intact","meaningCN":"完整的；未受损的","example":"The adjective supplies the picture of a whole not yet broken.","exampleCN":"这个形容词带来「尚未破碎的整块」这一意象。"},{"word":"in-","structure":"in- (Latin negative prefix, 'not')","meaning":"not","meaningCN":"不","example":"The negative prefix is what makes the whole word mean untouched.","exampleCN":"这个否定前缀正是全词表示「未被触动」的原因。"},{"word":"tangere","structure":"tangere (Latin verb, 'to touch')","meaning":"to touch","meaningCN":"触碰","example":"The root adds the image of a hand reaching in.","exampleCN":"这个词根添上「手伸进来触碰」的意象。"},{"word":"integrate","structure":"integer + -are (verb forming)","meaning":"to make whole","meaningCN":"使成为完整的一体","example":"Firms integrate their supply chains.","exampleCN":"企业把供应链整合起来。"},{"word":"integration","structure":"integrate + -ion (action noun)","meaning":"the making of a whole","meaningCN":"整合这件事","example":"Integration of the two systems took years.","exampleCN":"两套系统的整合用了多年。"},{"word":"integral","structure":"integer + -al (adjective forming)","meaning":"necessary to a whole","meaningCN":"整体中必需的","example":"Practice is an integral part of the training.","exampleCN":"练习是训练中不可缺少的一部分。"},{"word":"integrity","structure":"integer + -itas (state noun)","meaning":"the state of being whole","meaningCN":"完整无损的状态","example":"The archive kept the integrity of every file.","exampleCN":"档案馆保住了每个文件的完整性。"},{"word":"disintegrate","structure":"dis- (apart) + integrate","meaning":"to fall into parts","meaningCN":"分裂成部分","example":"The alliance disintegrated within a year.","exampleCN":"这个联盟在一年之内解体。"}],"latinEntries":[{"word":"integer","structure":"integer, integra, integrum (adjective, first and second declension)","meaning":"untouched, whole","meaningCN":"未被触动的；完整的"},{"word":"integrare","structure":"integrare, integravi, integratum (verb, first conjugation)","meaning":"to make whole, renew","meaningCN":"使完整；更新"},{"word":"integratio","structure":"integratio, integrationis (f., third declension)","meaning":"a renewing, a making whole","meaningCN":"更新；使完整"},{"word":"oeconomia","structure":"oeconomia, oeconomiae (f., first declension; borrowed from Greek)","meaning":"household management","meaningCN":"家务管理"}]}},{"word":"trade liberalization","ipa_uk":"/ˌtreɪd ˌlɪbərəlaɪˈzeɪʃən/","ipa_us":"/ˌtreɪd ˌlɪbərələˈzeɪʃən/","definition_zh":"贸易自由化；削减关税与贸易壁垒、让商品与服务更自由跨境流动的政策过程","definition_en":"the policy process of lowering tariffs and removing other barriers so that goods and services can cross borders more freely","core_image":"海关大厅里，一整页税目被逐行划掉，闸口抬起，货车不再停车受检","scene":"海关大厅里，官员把一整页税目表逐行划掉，闸口抬起，排队的货车直接通过。Years of trade liberalization cut the average tariff from forty percent to under five.","sceneCN":"这里指「削减关税与壁垒、让商品更自由跨境流动的政策过程」，对应第 1 个义项：以降低关税为主线的开放过程；句意为多年的贸易自由化把平均关税从四成降到不足五个百分点。画面要点：海关柜台、税目表、抬起的闸杆。","pos":[{"tag":"n.","zh":"贸易自由化（指政策过程，也可指某一轮具体的开放举措）"}],"collocations":[{"phrase":"trade liberalization talks","zh":"贸易自由化谈判"},{"phrase":"multilateral trade liberalization","zh":"多边贸易自由化"},{"phrase":"unilateral trade liberalization","zh":"单边贸易自由化"},{"phrase":"the pace of trade liberalization","zh":"贸易自由化的速度"},{"phrase":"deepen trade liberalization","zh":"深化贸易自由化"},{"phrase":"a round of trade liberalization","zh":"一轮贸易自由化"}],"forms":[{"label":"名词短语（本词）","form":"trade liberalization"},{"label":"复数（指多轮或多国举措）","form":"trade liberalizations"},{"label":"动词（使自由化）","form":"liberalize"},{"label":"过去分词（已放开的）","form":"liberalized"},{"label":"现在分词（放开的过程）","form":"liberalizing"},{"label":"形容词（开放的；自由派的）","form":"liberal"},{"label":"名词（自由）","form":"liberty"}],"derivatives":[{"word":"liberalize","pos":"v.","zh":"使自由化；放开限制"},{"word":"liberalized","pos":"adj.","zh":"已放开限制的"},{"word":"liberalization","pos":"n.","zh":"自由化（单独使用时多指经济领域的放开）"},{"word":"liberal","pos":"adj./n.","zh":"开放的；自由派的 / 自由派人士"},{"word":"liberality","pos":"n.","zh":"开明；慷慨"},{"word":"liberty","pos":"n.","zh":"自由；自由权"}],"senses":[{"no":"01","title":"Cutting tariffs","titleCN":"削减关税","definition":"the reduction of duties charged on imported goods, usually in scheduled steps","definitionCN":"降低对进口货物征收的税，通常按预定步骤分阶段进行","example":"Trade liberalization halved the duty on machine tools.","exampleCN":"贸易自由化把机床的关税降了一半。","why":"liberal here carries its oldest political meaning of 'free', so the phrase names the removal of a charge that restricts entry.","whyCN":"liberal 在这里取它最古老的政治含义「自由的」，因此这个短语指的是取消那道限制进入的收费。"},{"no":"02","title":"Taking non-tariff barriers down","titleCN":"拆除非关税壁垒","definition":"the removal of quotas, licensing rules and discriminatory standards that block imports without a duty","definitionCN":"取消配额、许可证规则与歧视性标准，这些手段不征税却同样挡住进口","example":"The talks moved from tariffs to trade liberalization of licensing rules.","exampleCN":"谈判从关税推进到许可证规则层面的贸易自由化。","why":"once duties fall, the remaining obstacles are administrative, and the same phrase extends to them because the goal is unchanged.","whyCN":"关税降下之后，剩下的障碍是行政性的；目标未变，所以同一个短语也扩用到这些障碍上。"},{"no":"03","title":"A multilateral negotiating round","titleCN":"多边谈判中的一轮开放","definition":"a package of reciprocal concessions agreed by many countries at once","definitionCN":"许多国家同时达成的一揽子互惠让步","example":"The Uruguay Round was the broadest trade liberalization of its decade.","exampleCN":"乌拉圭回合是那个十年里范围最广的一次贸易自由化。","why":"concessions are traded rather than given, so the word regularly names a round in which each country pays with its own barriers.","whyCN":"让步是交换来的而不是白给的，因此这个词常指一轮谈判，各国都用自己的壁垒来付账。"},{"no":"04","title":"One country opening alone","titleCN":"一国单方面开放","definition":"the lowering of a country's own barriers without waiting for partners to match it","definitionCN":"本国先降低壁垒，不等贸易伙伴作出对等回应","example":"Unilateral trade liberalization surprised its trading partners.","exampleCN":"单边贸易自由化让它的贸易伙伴感到意外。","why":"the phrase needs an adjective to say whether the opening was bargained or done alone, and unilateral marks the second case.","whyCN":"这个短语需要形容词来说明开放是换来的还是单做的，而「单边」正标记后一种情况。"},{"no":"05","title":"Extending it to services and investment","titleCN":"把开放扩展到服务与投资","definition":"the application of the same logic to banking, transport, telecoms and foreign direct investment","definitionCN":"把同一套逻辑用于银行、运输、电信与外国直接投资","example":"Modern trade liberalization covers services as much as goods.","exampleCN":"当代的贸易自由化对服务的覆盖不亚于货物。","why":"goods were only the first frontier; the same reasoning about entry barriers applies to a foreign bank or a foreign investor.","whyCN":"货物只是第一道前沿；关于进入壁垒的同一套推理，同样适用于一家外国银行或一位外国投资者。"},{"no":"06","title":"A package with adjustment costs","titleCN":"带着调整代价的政策组合","definition":"an opening programme that also involves compensation, retraining or phased timetables for affected firms","definitionCN":"在开放的同时安排补偿、再培训或分阶段时间表，以照顾受影响的行业","example":"The agreement paired trade liberalization with aid for displaced workers.","exampleCN":"该协定把贸易自由化与对失业工人的援助配在一起。","why":"opening creates losers as well as winners, so in policy speech the word often carries the price tag attached to it.","whyCN":"开放既造赢家也造输家，因此在政策话语中这个词常连带标出它要付的代价。"},{"no":"07","title":"The measured result: a rising trade share","titleCN":"可测量的结果：贸易占比上升","definition":"the observable rise in imports and exports relative to national income after barriers fall","definitionCN":"壁垒下降后，进出口相对于国民收入可观察到的上升","example":"Trade liberalization showed up in the data as a jump in exports.","exampleCN":"贸易自由化在数据上表现为出口的跃升。","why":"a policy is judged by its trace in statistics, so the same noun can denote the outcome as well as the decision.","whyCN":"政策要靠统计留下的痕迹来评判，因此同一个名词既能指决定，也能指结果。"},{"no":"08","title":"Abstract: freeing exchange from restriction","titleCN":"抽象义：让交换摆脱限制","definition":"in general use, the loosening of any rules that restrict the exchange of goods, ideas or people","definitionCN":"泛指放松限制货物、观念或人员交换的规则","example":"The same argument for liberalization appears in debates about academic exchange.","exampleCN":"支持自由化的同一套论证也出现在关于学术交流的讨论里。","why":"the abstract sense keeps only the movement from restriction to openness and lets the trade content fall away.","whyCN":"抽象义只保留「从限制走向开放」这一动向，贸易内容则被抽走。"}],"etymology":{"intro":{"en":"Trade liberalization joins an English commercial noun of Low German origin to a Latin adjective for freedom, with a noun suffix that came through French from Greek. Dates are approximate.","cn":"trade liberalization 把一个源自低地德语的英语商业名词，与一个表示自由的拉丁形容词连在一起，再加一个经法语来自希腊语的抽象名词后缀。年代均为约数。"},"items":[{"era":"MIDDLE LOW GERMAN TRADE","en":"Trade first meant 'track, course' and entered English in the fourteenth century as a word for a path or a habitual way; the commercial sense 'exchange of goods' is recorded from the sixteenth century.","cn":"trade 最初意为「路径、走向」，十四世纪进入英语时指道路或惯常做法；表示「货物交换」的商业义从十六世纪起有书证。"},{"era":"LATIN LIBER","en":"Liber meant 'free, not enslaved' and also 'unrestricted'; its deeper origin is not settled, so any Indo-European form proposed for it is a reconstruction.","cn":"liber 意为「自由的、非奴役的」，也指「不受限制的」；它更深的来源没有定论，凡为其提出的印欧语形式均属重构形式。"},{"era":"LATIN LIBERALIS","en":"Liberalis meant 'of a free man, generous', and English took it as liberal in the fourteenth century with the sense of giving freely.","cn":"liberalis 意为「自由人的、慷慨的」，英语在十四世纪以 liberal 借入，带「慷慨给予」的意思。"},{"era":"ECONOMIC LIBERAL","en":"By the nineteenth century liberal had shifted in economic writing to mean free of state restriction, and the verb liberalize and the noun liberalization were coined on that sense.","cn":"到十九世纪，liberal 在经济文献中已转为「不受国家限制的」，动词 liberalize 与名词 liberalization 就按这个义项造出。"},{"era":"POSTWAR TRADE POLICY","en":"The full phrase became standard after 1945 in negotiations over tariffs, where each round was described as a step of trade liberalization.","cn":"这一完整说法在 1945 年之后的关税谈判中成为标准用语，每一轮都被称为贸易自由化的一步。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin root of liber is disputed, and the earliest use of the full phrase is dated only approximately.","cn":"来源不确定（更深词源）：liber 在拉丁语之前的词根存在争议，这一完整短语的最早用例只能给出约略年代。"}]},"similar":{"note":{"en":"Group one holds words that look like liberalization but mean something else; group two holds policies and outcomes that are often mentioned in the same sentence.","cn":"第一组是形似 liberalization 而含义不同的词；第二组是常与它出现在同一句话里的政策与结果。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"liberation","ipa":"/ˌlɪbəˈreɪʃən/","tag":"people, not prices","definition":"The freeing of a person or a territory from control; it shares the root of freedom but not the economic subject.","definitionCN":"指人或领土摆脱控制而获自由；同出「自由」词根，但对象不是经济。"},{"word":"liberalism","ipa":"/ˈlɪbərəlɪzəm/","tag":"the doctrine","definition":"A political philosophy stressing individual rights and limited government; trade policy is only one application of it.","definitionCN":"强调个人权利与有限政府的政治哲学；贸易政策只是它的一个应用。"},{"word":"liberality","ipa":"/ˌlɪbəˈræləti/","tag":"generosity","definition":"The quality of giving freely or thinking broadly; it is a personal trait, not a programme of tariff cuts.","definitionCN":"指慷慨给予或心胸开阔的品质；属个人特质，不是削减关税的方案。"},{"word":"liberalized","ipa":"/ˈlɪbərəlaɪzd/","tag":"the state after the act","definition":"An adjective for a market or rule that has already been freed; the phrase names the act of freeing it.","definitionCN":"形容已经放开的行业或规则；而本词短语指放开这一动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"free trade","ipa":"/ˌfriː ˈtreɪd/","tag":"the ideal, not the step","definition":"Exchange with no barriers at all; liberalization is the movement toward that state and may stop short of it.","definitionCN":"完全没有壁垒的交换；自由化是朝这一状态走的过程，未必走到终点。"},{"word":"deregulation","ipa":"/ˌdiːreɡjəˈleɪʃən/","tag":"domestic rules","definition":"The removal of internal rules on prices or entry; it concerns a home market rather than border measures.","definitionCN":"取消国内关于价格或准入的规则；针对本国市场，而非边境措施。"},{"word":"market access","ipa":"/ˈmɑːkɪt ˈækses/","tag":"the permission","definition":"The right for foreign suppliers to sell into a market; access is what liberalization is meant to deliver.","definitionCN":"外国供应商进入某市场销售的权利；准入正是自由化要交付的东西。"},{"word":"opening up","ipa":"/ˈəʊpənɪŋ ʌp/","tag":"everyday phrase","definition":"The plain-language term for letting outsiders in; it is vaguer and can cover investment, culture and information too.","definitionCN":"让外部进入的通俗说法；含义更宽泛，也可涵盖投资、文化与信息。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The adjective inside the phrase meant 'of a free man', so liberalizing trade is treating exchange as something not chained.","cn":"短语中的形容词本义是「自由人的」，因此放开贸易就是把交换当成不被锁住的事。"},{"en":"The family runs liberal, liberalize, liberalized, liberalization, liberality and liberty.","cn":"同族词包括开放的、使自由化、已放开的、自由化、开明与自由。"},{"en":"Fixed phrases mark the negotiating sense: talks, a round, multilateral and unilateral.","cn":"固定搭配标出谈判义：谈判、一轮、多边与单边。"},{"en":"The opposite phrase is protectionism, and the two are constantly weighed against each other.","cn":"反面的说法是保护主义，两者常被拿来互相权衡。"},{"en":"The old sense of trade is a track or a course, which is why trade is something that runs along a route.","cn":"trade 的旧义是路径或走向，所以贸易被想成沿某条路线运行的事。"}],"abstract":[{"en":"Picture a locked gate at a border, then the lock being taken off and the gate pushed open.","cn":"想象边境上一道锁着的门，锁被取下，门被推开。"},{"en":"Picture a long list of charges at a customs desk, each line struck through with a pen.","cn":"想象海关柜台上的一长串收费条目，被笔一行行划掉。"},{"en":"Picture a knot loosening strand by strand until the rope lies straight.","cn":"想象一个结被一根根松开，直到绳子完全伸直。"}]},"examples":[{"en":"Trade liberalization brought cheaper parts but also factory closures.","cn":"贸易自由化带来了更便宜的零部件，也带来了工厂关停。"},{"en":"The report urged faster trade liberalization in services.","cn":"该报告呼吁在服务领域加快贸易自由化。"},{"en":"Farm lobbies resisted further trade liberalization on grain.","cn":"农业游说团体抵制在谷物上进一步贸易自由化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「贸易 + 使自由」——把跨境买卖的锁一道道解开 → 贸易自由化","word":"trade liberalization"},"root":"trade 出自中古低地德语，本义「路径、走向」，十六世纪起指货物交换；liberal 出自拉丁 liberalis「自由人的、慷慨的」，源头 liber「自由的」，更深来源不确定；抽象后缀经法语出自拉丁与希腊。","sensesIntro":{"en":"Eight senses follow one loosening: a duty comes off, then the licence rules, then a whole negotiating round, then a country acts alone, then services and investors are let in, then the price of adjustment is paid, then the statistic moves, and finally any exchange is freed.","cn":"八个义项沿同一个松开动作展开：先是关税取下，再是许可证规则，接着是一整轮谈判，然后一国单做，服务与投资者被放进来，调整的代价被付清，统计数字随之变动，最后任何交换都被解开。"},"semanticMap":{"core":{"en":"CORE IMAGE: a customs gate lifted, a page of duty lines struck through.","cn":"核心意象：海关闸杆抬起，一整页税目被划掉。"},"chain":["LOWER THE DUTY","REMOVE THE PERMIT","TRADE CONCESSIONS","OPEN ALONE","LET SERVICES IN","FREE THE EXCHANGE"],"branches":[{"senses":"01 · 02","en":"PRICE AND PERMISSION: first the charge is cut, then the paperwork that also stops goods is cut away.","cn":"价钱与许可：先削掉收费，再削掉同样能挡住货物的那叠文件。"},{"senses":"03 · 04","en":"BARGAINED OR ALONE: the same opening can be traded with partners round a table or done by one government first.","cn":"换来或单做：同一种开放，既可在桌边与伙伴交换，也可由一国政府先行做出。"},{"senses":"05","en":"BEYOND GOODS: a foreign bank and a foreign investor meet the same entry barrier as a crate does.","cn":"货物之外：一家外国银行与一位外国投资者，面对的进入壁垒与一只货箱相同。"},{"senses":"06 · 07","en":"COST AND COUNT: the losers are compensated, and the effect is then read off in trade statistics.","cn":"代价与计数：受损者得到补偿，效果则从贸易统计里读出来。"},{"senses":"08","en":"GENERAL FREEDOM: the tariff disappears and only the loosening of a restriction is left.","cn":"一般意义上的放开：关税消失，只剩下限制被松开这件事。"}]},"affixes":{"intro":{"en":"The phrase combines a Germanic commercial noun, a Latin adjective of freedom and a borrowed noun suffix, so each part can be read on its own.","cn":"这个短语把日耳曼语系的商业名词、表示自由的拉丁形容词与一个借入的名词后缀合在一起，各部分都可单独读出。"},"latinIntro":{"en":"Latin liber and liberalis supply liberty, liberal, liberality and liberate; the suffix chain from Greek through Latin and French supplies the abstract noun ending in -ization.","cn":"拉丁 liber 与 liberalis 衍生出自由、开放的、开明与解放；从希腊语经拉丁语与法语传下的后缀链，则提供表示「过程」的抽象名词。"},"items":[{"word":"trade","structure":"trade (English noun, from Middle Low German)","meaning":"course, track; then commerce","meaningCN":"路径、走向；后指商贸","example":"The noun first named a path, then the goods moving along it.","exampleCN":"这个名词先指道路，后指沿路流动的货物。"},{"word":"liber","structure":"liber (Latin adjective, 'free')","meaning":"free, unrestricted","meaningCN":"自由的；不受限制的","example":"The root supplies the idea of a person not bound.","exampleCN":"这个词根带来「人不受束缚」的意思。"},{"word":"-alis","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix turns the noun of freedom into an adjective.","exampleCN":"这个后缀把「自由」这一名词变成形容词。"},{"word":"liberalis","structure":"liber + -alis","meaning":"of a free man; generous","meaningCN":"自由人的；慷慨的","example":"The adjective first described the giving of a free man.","exampleCN":"这个形容词最初描述自由人的给予。"},{"word":"liberalize","structure":"liberal + -ize (to make)","meaning":"to make free of restriction","meaningCN":"使摆脱限制","example":"The government liberalized the grain trade.","exampleCN":"政府放开了谷物贸易。"},{"word":"-ization","structure":"-ization (noun suffix, through French from Latin and Greek)","meaning":"the process of making","meaningCN":"使……的过程","example":"The suffix names the process rather than the act of one day.","exampleCN":"这个后缀指过程，而非某一天的一次行动。"},{"word":"liberalization","structure":"liberalize + -ation","meaning":"the process of freeing","meaningCN":"放开的过程","example":"Liberalization of the phone market cut prices.","exampleCN":"电话市场的放开压低了价格。"},{"word":"liberate","structure":"liber + -ate (verb forming)","meaning":"to set free","meaningCN":"使获自由；解放","example":"The word is used of people and places, not of tariffs.","exampleCN":"这个词用于人与地方，不用于关税。"},{"word":"liberty","structure":"liber + -tas (state noun)","meaning":"the state of being free","meaningCN":"自由的状态","example":"Liberty of movement was restored.","exampleCN":"行动自由得以恢复。"}],"latinEntries":[{"word":"liber","structure":"liber, libera, liberum (adjective, first and second declension)","meaning":"free, unrestricted","meaningCN":"自由的；不受限制的"},{"word":"liberalis","structure":"liberalis, liberale (adjective, third declension)","meaning":"of a free man, generous","meaningCN":"自由人的；慷慨的"},{"word":"liberare","structure":"liberare, liberavi, liberatum (verb, first conjugation)","meaning":"to set free","meaningCN":"使获自由"},{"word":"liberalitas","structure":"liberalitas, liberalitatis (f., third declension)","meaning":"generosity, liberality","meaningCN":"慷慨；开明"}]}},{"word":"politics","ipa_uk":"/ˈpɒlətɪks/","ipa_us":"/ˈpɑːlətɪks/","definition_zh":"政治；政治活动；政治见解；政界；政治学；组织内部的权术运作","definition_en":"the activity by which people govern, compete for office and settle collective decisions, also used for a person's views, the profession, the academic subject and internal manoeuvring","core_image":"旱季的村口，两派人围在水渠分水口争论，最后按人头重新排定用水次序","scene":"旱季的村口，两派人围在水渠的分水口争论，最后按人头重新排定用水次序。Politics in the valley had always been about who controlled the water.","sceneCN":"这里指「治理与争夺权力的活动」，对应第 1 个义项：围绕公共资源由谁决定而展开的争夺；句意为这条山谷里的政治历来就是围绕谁掌握水源展开的。画面要点：分水口、两排站立的人、记名的木板。","pos":[{"tag":"n.","zh":"政治；政治活动（不可数，作主语时视为单数）"},{"tag":"n.","zh":"政治见解；政治立场（作此义时可用作复数）"}],"collocations":[{"phrase":"go into politics","zh":"进入政界"},{"phrase":"office politics","zh":"办公室里的权术运作"},{"phrase":"party politics","zh":"党派政治"},{"phrase":"international politics","zh":"国际政治"},{"phrase":"the politics of reform","zh":"改革的政治角力"},{"phrase":"engage in politics","zh":"参与政治活动"},{"phrase":"local politics","zh":"地方政治"}],"forms":[{"label":"本词（以复数词尾结尾，作学科或活动时视为单数）","form":"politics"},{"label":"相关形容词","form":"political"},{"label":"相关副词","form":"politically"},{"label":"相关名词（从政者）","form":"politician"},{"label":"相关名词（政策）","form":"policy"},{"label":"相关名词（政体）","form":"polity"},{"label":"相关动词（使政治化）","form":"politicize"}],"derivatives":[{"word":"political","pos":"adj.","zh":"政治的；政党的"},{"word":"politically","pos":"adv.","zh":"在政治方面；从政治角度"},{"word":"politician","pos":"n.","zh":"政治家；政客"},{"word":"politicize","pos":"v.","zh":"使政治化；把……变成政治议题"},{"word":"politicization","pos":"n.","zh":"政治化"},{"word":"polity","pos":"n.","zh":"政体；政治共同体"}],"senses":[{"no":"01","title":"The activity of governing and competing for power","titleCN":"治理与争夺权力的活动","definition":"the activity by which groups decide who holds public authority and how it is used","definitionCN":"各群体决定公共权力归谁掌握、如何使用的活动","example":"Politics decides who gets the water and who waits.","exampleCN":"政治决定谁能先得水、谁只能等。","why":"the Greek root names the city and its citizens, so the word began as the business of the civic body rather than of private life.","whyCN":"这个词的希腊词根指城邦及其公民，因此它最初指公民集体的事务，而非私人生活。"},{"no":"02","title":"A person's views or affiliation","titleCN":"个人的政治见解或党派立场","definition":"the set of beliefs a person holds about how society and government should be run","definitionCN":"一个人对社会与政府应如何运转所持的一整套信念","example":"Her politics are greener than her party's platform.","exampleCN":"她的政治立场比本党纲领更偏环保。","why":"beliefs about governing are held by individuals, so the plural noun came to mean one person's stance and can take a plural verb in this sense.","whyCN":"关于治理的信念由个人持有，因此这个以复数形式收尾的名词转指个人的立场，作此义时可用复数动词。"},{"no":"03","title":"The profession and world of politicians","titleCN":"政界；以政治为业","definition":"the career, workplace and daily life of those who hold or seek public office","definitionCN":"担任或谋求公职者的职业、职场与日常处境","example":"He went into politics after running the city hospital.","exampleCN":"他管过市立医院之后进入了政界。","why":"an activity that occupies a career becomes a place one enters, hence phrases about going into or leaving politics.","whyCN":"一项活动一旦占据一份职业，就变成可以走进去的场所，于是有了进入政界、退出政界这类说法。"},{"no":"04","title":"The academic subject","titleCN":"政治学（学科名，英式常用）","definition":"the study of government and political behaviour as a university discipline","definitionCN":"在大学里把政府与政治行为作为研究对象的学科","example":"She read politics before turning to law.","exampleCN":"她先读政治学，之后转行学法。","why":"the Greek title of a book on civic affairs became the name of the school subject that studies them.","whyCN":"一本论城邦事务的希腊书名，后来成了研究这些事务的学科名称。"},{"no":"05","title":"Manoeuvring inside an organization","titleCN":"组织内部的权术运作","definition":"the informal struggle for influence and favour within a workplace, club or family","definitionCN":"在工作场所、团体或家庭内部为影响力与青睐而进行的非正式争夺","example":"Office politics kept the best engineer off the project.","exampleCN":"办公室里的权术让最好的工程师进不了这个项目。","why":"the patterns of alliance and rivalry repeat at any scale, so the word is borrowed wherever a small group allocates scarce goods.","whyCN":"结盟与对立的方式在任何规模上都会重演，因此只要小群体分配稀缺之物，这个词就会被借去用。"},{"no":"06","title":"Public contest over policy and office","titleCN":"围绕政策与职位的公共竞争","definition":"the open competition of parties, campaigns and interest groups over what government should do","definitionCN":"政党、竞选活动与利益团体围绕政府应当做什么而展开的公开竞争","example":"The politics of the budget turned on two marginal seats.","exampleCN":"预算的政治角力集中在两个边缘选区上。","why":"when conflict is public and organised, the word names the contest itself rather than the general activity.","whyCN":"当冲突公开且有组织时，这个词指的是竞争本身，而不是笼统的活动。"},{"no":"07","title":"The arena or system as a whole","titleCN":"政治舞台与制度环境的总称","definition":"the whole institutional setting in which authority is won, used and lost","definitionCN":"权力被赢得、使用与失去的整套制度环境","example":"Trust in politics fell after the expenses scandal.","exampleCN":"报销丑闻之后，人们对政治这一套制度的信任下降了。","why":"the activity and the setting are named by one word, so the noun can stand for the entire arena in which the activity happens.","whyCN":"活动与场所用同一个词表示，因此这个名词也能指活动发生的整个场域。"},{"no":"08","title":"Abstract: the negotiation of collective interests","titleCN":"抽象义：集体利益的协商过程","definition":"in general use, any process by which a group with diverging interests reaches a workable decision","definitionCN":"泛指利益分歧的群体达成可行决定的任何过程","example":"There is politics in every committee that must divide a budget.","exampleCN":"凡是要分预算的委员会，都有政治。","why":"the abstract sense keeps only the settling of divergent interests and lets the state and the ballot drop away.","whyCN":"抽象义只留下「摆平分歧利益」这层意思，国家与选票则退出了画面。"}],"etymology":{"intro":{"en":"Politics goes back through French and Latin to the Greek title of Aristotle's book on civic affairs, built on the Greek word for a city. Dates are approximate.","cn":"politics 经法语与拉丁语上溯到亚里士多德论城邦事务那本书的希腊书名，其词根是希腊语中表示「城邦」的词。年代均为约数。"},"items":[{"era":"GREEK POLIS","en":"Polis meant a city-state and the citizen body that made it; its deeper origin is not established, and the suggestion of a pre-Greek source is a hypothesis rather than a demonstrated derivation.","cn":"polis 指城邦以及构成城邦的公民总体；它更深的来源未得到证明，关于其源自前希腊语层的说法只是假说，并非已证实的派生。"},{"era":"GREEK POLITES","en":"Polites meant a citizen, one who belongs to the polis and shares in its decisions, and from it came the adjective politikos 'of citizens, civic'.","cn":"politēs 指公民，即属于城邦并参与其决定的人；由它产生形容词 politikos「公民的、城邦的」。"},{"era":"GREEK TA POLITIKA","en":"Ta politika meant 'the things concerning the city', the title of Aristotle's treatise on the government of states, and it named civic affairs rather than party strife.","cn":"ta politika 意为「与城邦有关的事务」，是亚里士多德论国家治理那部书的书名，所指为公民事务，而非党派争斗。"},{"era":"LATIN POLITICA","en":"Medieval Latin politica was coined from the Greek title to name the study of the state, and it passed through French into English in the late fifteenth century.","cn":"中世纪拉丁语 politica 依那个希腊书名造出，用来指对国家的研究，并在十五世纪晚期经法语进入英语。"},{"era":"MODERN WIDENING","en":"From the nineteenth century the word spread to party competition, then to the internal manoeuvring of any institution, and finally to 'the politics of' almost any activity.","cn":"从十九世纪起，这个词先扩展到党派竞争，再指任何机构内部的权术，最后出现「某事背后的政治」这种几乎可用于一切活动的说法。"}]},"similar":{"note":{"en":"Group one holds words built on the same Greek city root that are easily confused with politics; group two holds terms for governing that do not carry the competitive sense.","cn":"第一组是同出希腊「城邦」词根、容易与 politics 混淆的词；第二组是表示治理、但不含竞争意味的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"policy","ipa":"/ˈpɒləsi/","tag":"a plan, not the contest","definition":"A settled course of action adopted by a government or firm; politics is the struggle that produces or blocks a policy.","definitionCN":"政府或机构采用的既定行动方案；政治则是产生或阻挠某项政策的那场争夺。"},{"word":"polity","ipa":"/ˈpɒləti/","tag":"the organised community","definition":"A politically organised society viewed as a unit, as in a federal polity; it names the body, not its activity.","definitionCN":"被视作一个单位的有政治组织的社会，如联邦政体；它指共同体本身，而非其活动。"},{"word":"politic","ipa":"/ˈpɒlətɪk/","tag":"prudent, not political","definition":"An older adjective meaning shrewd and tactful, as in a politic silence; it describes judgement, not government.","definitionCN":"较旧的形容词，意为精明得体的，如得体的沉默；它描述判断力，而非政府事务。"},{"word":"politician","ipa":"/ˌpɒləˈtɪʃən/","tag":"the person","definition":"A person who holds or seeks office; the practice they live by is politics, and the two are constantly used together.","definitionCN":"担任或谋求公职的人；他们以此谋生的活动就是政治，两者常连用。"}]},{"heading":"NEAR MEANING","entries":[{"word":"government","ipa":"/ˈɡʌvənmənt/","tag":"the institution","definition":"The body that exercises authority in a state; government is the machine, while politics is the contest that drives it.","definitionCN":"在国家中行使权力的机构；政府是机器，政治则是驱动机器的那场竞争。"},{"word":"governance","ipa":"/ˈɡʌvənəns/","tag":"how decisions are made","definition":"The processes and rules by which decisions are taken, often used of firms and agencies; it is quieter and more technical than politics.","definitionCN":"作出决定所依的流程与规则，常用于企业与机构；它比政治更平实、更技术化。"},{"word":"statecraft","ipa":"/ˈsteɪtkrɑːft/","tag":"skill in managing a state","definition":"The art of conducting state affairs, especially foreign policy; it stresses skill and is used of leaders rather than of voters.","definitionCN":"处理国家事务、尤其外交事务的技艺；强调技巧，多用于领导人而非选民。"},{"word":"public affairs","ipa":"/ˌpʌblɪk əˈfeəz/","tag":"neutral umbrella","definition":"A neutral term for matters of common concern and the work of dealing with them; it avoids the combative tone of politics.","definitionCN":"对公共事务及其处理工作的中性说法；避开了政治一词的争斗意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root is the Greek word for a city-state, so politics is literally the business of the city.","cn":"词根是希腊语中表示城邦的词，所以政治字面上就是城邦的事务。"},{"en":"The family runs political, politically, politician, policy, polity and politicize.","cn":"同族词包括政治的、在政治上、政治家、政策、政体与使政治化。"},{"en":"Fixed phrases sort the senses: go into politics, office politics, party politics, the politics of reform.","cn":"固定搭配给各义项分类：进入政界、办公室权术、党派政治、改革的政治角力。"},{"en":"The word ends in -s but takes a singular verb when it names the activity or the subject.","cn":"这个词虽以表示复数的词尾结尾，但指活动或学科时作单数用。"},{"en":"A politician lives by politics; a policy is what the struggle produces.","cn":"政治家靠政治为生；政策则是这场争夺的产物。"}],"abstract":[{"en":"Picture a crowd at a water channel, each faction counting heads before the gate is opened.","cn":"想象一群人围在水渠边，各派在开闸前清点人数。"},{"en":"Picture a table where five people must split one loaf and nobody wants the smallest piece.","cn":"想象五个人要分一只面包，谁都不愿拿最小的一块。"},{"en":"Picture a corridor where two groups whisper before entering the same voting hall.","cn":"想象走廊里两群人在进同一个投票厅之前低声商量。"}]},"examples":[{"en":"Politics in the region has long followed family lines.","cn":"这个地区的政治长期沿家族脉络运行。"},{"en":"She left politics to run a research institute.","cn":"她退出政界，去主持一家研究所。"},{"en":"He never discusses his politics at work.","cn":"他在工作时从不谈自己的政治立场。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「城邦的事务」——城里人一起商量谁说了算 → 政治","word":"politics"},"root":"politics 经法语与拉丁语出自希腊 ta politika「与城邦有关的事务」，源头是 polis「城邦」与 politēs「公民」；polis 更深来源不确定，前希腊语来源仅为假说。","sensesIntro":{"en":"Eight senses widen from one root: the business of the city becomes a career, then a set of personal beliefs, a university subject, the manoeuvring of any small group, an open electoral contest, the whole arena, and finally any settlement of divergent interests.","cn":"八个义项由同一个词根向外扩：城邦的事务先成为一门职业，再成为个人的一整套信念、一门大学学科、任何小团体内部的权术、公开的选举竞争、整个政治场域，最后是任何摆平分歧利益的过程。"},"semanticMap":{"core":{"en":"CORE IMAGE: neighbours arguing at a water gate until a rule is agreed.","cn":"核心意象：邻人在分水口争论，直到商定一条规则。"},"chain":["CIVIC BUSINESS","WHO DECIDES","A CAREER","A BELIEF","A SUBJECT","SETTLING INTERESTS"],"branches":[{"senses":"01","en":"ROOT ACTIVITY: deciding who holds public authority, the oldest and widest reading.","cn":"根本活动：决定公共权力归谁，这是最古老也最宽的读法。"},{"senses":"02 · 03","en":"PERSONAL AND PROFESSIONAL: the same word covers what a private person believes and the trade a public person lives by.","cn":"个人与职业：同一个词既指私人的信念，也指公开人物赖以谋生的行业。"},{"senses":"04","en":"SUBJECT: the civic business turned into a course of study with its own methods.","cn":"学科：城邦事务被变成一门有自身方法的研究。"},{"senses":"05 · 06","en":"SCALE OF CONFLICT: quiet manoeuvring in an office and open contest at an election are the same pattern at different sizes.","cn":"冲突的规模：办公室里无声的权术与选举中公开的竞争，是同一种格局的不同尺寸。"},{"senses":"07 · 08","en":"ARENA AND GENERAL FORM: the whole stage where authority changes hands, then any group dividing what it needs.","cn":"场域与一般形态：先是权力易手的整个舞台，后是任何分配所需之物的群体。"}]},"affixes":{"intro":{"en":"Politics rests on a Greek noun for the city and its citizen body, a stem that also builds policy, polity and politician in English.","cn":"politics 立在一个表示城邦及其公民总体的希腊名词上，同一词干在英语里还造出政策、政体与政治家。"},"latinIntro":{"en":"Latin borrowed the Greek stem as politicus and politica, the forms through which the word family reached English.","cn":"拉丁语把这个希腊词干借作 politicus 与 politica，这个词族正是经这两种形式进入英语的。"},"items":[{"word":"polis","structure":"polis (Greek noun, 'city-state')","meaning":"city-state; citizen community","meaningCN":"城邦；公民共同体","example":"The root names the unit within which decisions were made.","exampleCN":"这个词根指出作出决定的那个单位。"},{"word":"polites","structure":"polites (Greek noun, 'citizen')","meaning":"citizen","meaningCN":"公民","example":"The citizen, not the subject, is the base of the word.","exampleCN":"这个词的基础是公民，而非臣民。"},{"word":"politikos","structure":"polites + -ikos (adjective suffix)","meaning":"of citizens, civic","meaningCN":"公民的；城邦的","example":"The adjective described matters that concerned the citizen body.","exampleCN":"这个形容词描述与公民总体相关的事务。"},{"word":"-ics","structure":"-ics (Greek suffix naming an art or study)","meaning":"the field of","meaningCN":"……之学","example":"The suffix turns civic affairs into a named field.","exampleCN":"这个后缀把城邦事务变成一个有名称的领域。"},{"word":"politician","structure":"politic + -ian (person suffix)","meaning":"one who practices politics","meaningCN":"从事政治的人","example":"The suffix marks the practitioner.","exampleCN":"这个后缀标记从业者。"},{"word":"policy","structure":"Old French policie, from Latin politica","meaning":"a course of action","meaningCN":"行动方针","example":"Policy is the settled plan, not the contest.","exampleCN":"政策是定下来的方案，而非争夺本身。"},{"word":"polity","structure":"Latin politia + -y (noun forming)","meaning":"an organised political community","meaningCN":"有组织的政治共同体","example":"A polity can be a city, a state or a federation.","exampleCN":"政体可以是一座城、一个国家或一个联邦。"},{"word":"politicize","structure":"political + -ize (to make)","meaning":"to make political","meaningCN":"使成为政治议题","example":"The budget dispute politicized the school board.","exampleCN":"预算争执把校董会政治化了。"},{"word":"political","structure":"politic + -al (adjective suffix)","meaning":"relating to government","meaningCN":"与政府相关的","example":"The decision was political rather than technical.","exampleCN":"这个决定是政治性的，而非技术性的。"}],"latinEntries":[{"word":"politicus","structure":"politicus, politica, politicum (adjective, borrowed from Greek)","meaning":"civic, of the state","meaningCN":"城邦的；国家的"},{"word":"politica","structure":"politica, politicae (f., first declension; from Greek ta politika)","meaning":"the study of the state","meaningCN":"对国家的研究"},{"word":"politia","structure":"politia, politiae (f., first declension; from Greek politeia)","meaning":"the constitution of a state","meaningCN":"城邦的政制"}]}},{"word":"political","ipa_uk":"/pəˈlɪtɪkəl/","ipa_us":"/pəˈlɪtɪkəl/","definition_zh":"政治的；政党的；政治性的；涉及权力关系的；关心并参与政治的","definition_en":"relating to government, parties or public power, and also used of anything shaped by the struggle for influence","core_image":"竞选办公室的墙上一层层贴着海报，志愿者守着电话名单逐个催票","scene":"选举前夜，竞选办公室的墙上贴满海报，志愿者守着电话名单逐个催票。The rally was a political event from the first speech to the last handshake.","sceneCN":"这里指「与政党及选举有关的」，对应第 2 个义项：属于党派竞争与投票活动范畴的；句意为这场造势集会从第一场演讲到最后一次握手都是政治活动。画面要点：海报墙、电话名单、成排折叠椅。","pos":[{"tag":"adj.","zh":"政治的；与政府、政党或公共权力有关的"},{"tag":"adj.","zh":"政治性的；出于权力考量的（含贬义时指为利益而非为原则）"}],"collocations":[{"phrase":"political party","zh":"政党"},{"phrase":"political system","zh":"政治制度"},{"phrase":"political power","zh":"政治权力"},{"phrase":"political issue","zh":"政治议题"},{"phrase":"a political decision","zh":"政治性决定"},{"phrase":"political will","zh":"政治意愿"},{"phrase":"political debate","zh":"政治辩论"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more political"},{"label":"最高级（更多用 most 构成）","form":"most political"},{"label":"副词","form":"politically"},{"label":"名词（政治）","form":"politics"},{"label":"名词（从政者）","form":"politician"},{"label":"动词（使政治化）","form":"politicize"}],"derivatives":[{"word":"politically","pos":"adv.","zh":"在政治方面；从政治角度"},{"word":"politicize","pos":"v.","zh":"使政治化；使带上党派色彩"},{"word":"politicization","pos":"n.","zh":"政治化"},{"word":"depoliticize","pos":"v.","zh":"使去政治化；把争议移出政治领域"},{"word":"apolitical","pos":"adj.","zh":"不问政治的；与政治无关的"}],"senses":[{"no":"01","title":"Relating to government and public affairs","titleCN":"与政府及公共事务有关","definition":"concerned with the state, its institutions and the making of public decisions","definitionCN":"涉及国家、其机构以及公共决定的作出","example":"The constitution sets the political institutions of the country.","exampleCN":"宪法确立了这个国家的政治机构。","why":"the Greek adjective meant 'of citizens, civic', so political first described what belongs to the organised community.","whyCN":"这个希腊形容词意为「公民的、城邦的」，因此 political 最初描述属于有组织共同体的事物。"},{"no":"02","title":"Relating to parties and elections","titleCN":"与政党及选举有关","definition":"belonging to the competition of parties, campaigns and votes","definitionCN":"属于政党竞争、竞选活动与投票的范畴","example":"The rally was a political event from start to finish.","exampleCN":"这场集会从头到尾都是政治活动。","why":"when civic business organised itself into parties, the adjective followed the contest rather than the institution.","whyCN":"当城邦事务组织成党派之后，这个形容词就跟着竞争走，而不只指机构。"},{"no":"03","title":"Moved by power rather than by merit","titleCN":"出于权力考量而非事理本身","definition":"describing a choice made to protect influence or advantage rather than because it is right or efficient","definitionCN":"形容某项选择是为保住影响力或优势而作，而非因为它正确或高效","example":"The appointment was political, not technical.","exampleCN":"这项任命是政治性的，不是技术性的。","why":"once the adjective can mean 'of the contest', it can also mean 'shaped by the contest', and that reading carries the criticism.","whyCN":"一旦这个形容词能表示「属于竞争」，也就能表示「被竞争左右」，后一种读法自带批评意味。"},{"no":"04","title":"Sensitive or contested in public terms","titleCN":"在公共层面敏感、容易引发争执","definition":"describing a topic that arouses strong public disagreement and is therefore hard to handle openly","definitionCN":"形容会激起强烈公共分歧、因而难以公开处理的话题","example":"Water rights are a political subject in every dry province.","exampleCN":"在每个干旱省份，水权都是敏感的政治话题。","why":"topics become political when they enter the space where groups must take sides, so the adjective marks that entry.","whyCN":"话题一旦进入群体必须站队的那个空间，就变得政治化，这个形容词标记的正是这一进入。"},{"no":"05","title":"Power relations inside an organization","titleCN":"组织内部的权力关系","definition":"describing the informal side of an institution where influence, alliance and status are at stake","definitionCN":"形容机构中影响力、结盟与地位暗中较劲的那一面","example":"A political reading of the memo explained why the plan died.","exampleCN":"从权力关系的角度读这份备忘录，就能解释这个方案为何夭折。","why":"the pattern of alliance and rivalry repeats in firms and faculties, so the adjective travels wherever scarce goods are allocated.","whyCN":"结盟与对立的格局在企业与院系里都会重演，因此只要稀缺之物需要分配，这个形容词就会跟过去。"},{"no":"06","title":"Engaged or aware as a person","titleCN":"形容关心并参与政治的人","definition":"describing a person who follows public affairs and acts on them, as in a very political family","definitionCN":"形容关注公共事务并付诸行动的人，如一个政治气氛浓厚的家庭","example":"She came from a political family and knew the ward maps by heart.","exampleCN":"她出身于政治家庭，把选区地图记得滚瓜烂熟。","why":"the adjective applies to people as well as things, and then it means absorbed in the activity rather than belonging to it.","whyCN":"这个形容词也可用于人，此时指沉浸在政治活动中，而不是属于某个机构。"},{"no":"07","title":"Belonging to the state sphere","titleCN":"属于国家领域而非民间或宗教领域","definition":"marking the boundary between matters of the state and matters of faith, market or private life","definitionCN":"标出国家事务与信仰、市场或私人生活之间的界线","example":"The dispute was religious in form and political in effect.","exampleCN":"这场争端形式上属宗教，实际效果上属政治。","why":"a society divides its spheres, and the adjective names the one that ends in enforceable collective decisions.","whyCN":"社会把领域划分开来，这个形容词所指的正是最终以可强制执行的集体决定收尾的那一个领域。"},{"no":"08","title":"Abstract: concerning who decides collectively","titleCN":"抽象义：关乎集体由谁决定","definition":"in general use, touching on the question of who has the right to make a binding choice for a group","definitionCN":"泛指触及「谁有权为一个群体作出有约束力的选择」这一问题","example":"Even the choice of a chairman became political.","exampleCN":"连选谁当主席都变成了政治问题。","why":"the abstract sense reduces the word to one question, namely who may decide for the group.","whyCN":"抽象义把这个词压缩成一个问题，即为群体作决定的权利归谁。"}],"etymology":{"intro":{"en":"Political is the English form of a Greek adjective meaning 'of citizens', built on the word for a city-state. Dates are approximate.","cn":"political 是希腊语中意为「公民的」这一形容词在英语里的形式，其词根是表示城邦的词。年代均为约数。"},"items":[{"era":"GREEK POLIS","en":"Polis named a city-state and its citizen body; its deeper origin is not settled, and a pre-Greek source is a hypothesis rather than an established fact.","cn":"polis 指城邦及其公民总体；它更深的来源未有定论，前希腊语来源只是假说，并非已确认的事实。"},{"era":"GREEK POLITIKOS","en":"Politikos meant 'of a citizen, civic, fit for governing', and it described affairs that concerned the community rather than the household.","cn":"politikos 意为「公民的、城邦的、适于治理的」，描述与共同体相关、而非与家户相关的事务。"},{"era":"LATIN POLITICUS","en":"Latin borrowed the adjective as politicus and used it for civil and state affairs, especially in translations of Greek political works.","cn":"拉丁语把这个形容词借作 politicus，用于民政与国家事务，尤其在翻译希腊政治著作时使用。"},{"era":"FRENCH POLITIQUE","en":"Middle French politique took the word into English in the fifteenth century, first as a noun for the study of the state and soon after as an adjective.","cn":"中古法语 politique 在十五世纪把这个词带入英语，先作名词指对国家的研究，随后不久用作形容词。"},{"era":"MODERN EXTENSION","en":"From the nineteenth century the adjective was extended to party competition and then to any sphere where influence is contested, including offices and universities.","cn":"从十九世纪起，这个形容词先扩用到党派竞争，再扩用到任何影响力受争夺的领域，包括办公室与大学。"}]},"similar":{"note":{"en":"Group one holds words from the same civic stem that are easily mistaken for this adjective; group two holds adjectives that overlap in meaning.","cn":"第一组是同出「城邦」词干、容易被误当作本词的词；第二组是含义部分重叠的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"politic","ipa":"/ˈpɒlətɪk/","tag":"prudent, not governmental","definition":"A shorter adjective meaning shrewd and tactful; a politic move is a wise one, not necessarily a governmental one.","definitionCN":"更短的同源形容词，意为精明得体的；得体的举动是明智之举，未必与国家有关。"},{"word":"politically","ipa":"/pəˈlɪtɪkli/","tag":"the adverb","definition":"The adverb form, used for the standpoint or the consequences in power terms, as in politically impossible.","definitionCN":"副词形式，用于表示政治角度或权力层面的后果，如政治上不可行。"},{"word":"apolitical","ipa":"/ˌeɪpəˈlɪtɪkəl/","tag":"the negation","definition":"Built with a negative prefix, it means indifferent to or outside politics, and is the direct opposite of one sense of this word.","definitionCN":"由否定前缀构成，意为不问政治的或与政治无关的，与本词的某一义项正好相反。"},{"word":"politics","ipa":"/ˈpɒlətɪks/","tag":"the noun","definition":"The activity itself; the adjective describes what belongs to it or resembles it.","definitionCN":"指活动本身；本词形容词则描述属于该活动或与之相似的事物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"governmental","ipa":"/ˌɡʌvənˈmentəl/","tag":"state bodies only","definition":"Relating to government as an institution; it does not extend to party contests or office manoeuvring.","definitionCN":"与作为机构的政府有关；不延伸到党派竞争或办公室权术。"},{"word":"partisan","ipa":"/ˌpɑːtɪˈzæn/","tag":"taking one side","definition":"Loyal to a party or cause; political can be neutral, while partisan always implies taking sides.","definitionCN":"忠于某党或某项主张；political 可以是中性的，而 partisan 总意味着站队。"},{"word":"civic","ipa":"/ˈsɪvɪk/","tag":"duties of citizens","definition":"Relating to the duties and rights of citizens in a town; it is about membership rather than about power struggle.","definitionCN":"与市民的义务和权利有关；侧重成员身份，而非权力争夺。"},{"word":"public","ipa":"/ˈpʌblɪk/","tag":"open to all","definition":"Concerning the community as a whole or open to view; it lacks the connotation of contest for authority.","definitionCN":"涉及整个共同体或对外公开；不含争夺权威的意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The stem is the Greek word for a city-state, so the adjective originally means 'belonging to the citizen body'.","cn":"词干是希腊语中表示城邦的词，所以这个形容词本义是「属于公民总体的」。"},{"en":"The family runs political, politically, politics, politician, politicize and apolitical.","cn":"同族词包括政治的、在政治上、政治、从政者、使政治化与不问政治的。"},{"en":"Fixed phrases mark the institutional sense: political party, political system, political will, political debate.","cn":"固定搭配标出制度义：政党、政治制度、政治意愿、政治辩论。"},{"en":"Saying a decision was political is a criticism; saying a map is political is a description.","cn":"说某个决定是政治性的，是批评；说某张地图是政治的，是描述。"},{"en":"The pair to remember is politic for prudent and political for governmental.","cn":"要记住的对照是：较短的 politic 指精明得体，political 指与国家相关。"}],"abstract":[{"en":"Picture a room where every chair is placed to show who outranks whom.","cn":"想象一间屋子，每把椅子的位置都在显示谁的位次更高。"},{"en":"Picture a line drawn across a table, with faith on one side and enforceable rules on the other.","cn":"想象桌上画一条线，一边是信仰，另一边是可强制执行的规则。"},{"en":"Picture a hand raised in a hall, asking not what is true but who may decide.","cn":"想象大厅里举起一只手，问的不是何为真，而是谁有权决定。"}]},"examples":[{"en":"The reforms were blocked for purely political reasons.","cn":"这些改革因纯粹的政治原因被搁置。"},{"en":"She kept her political views out of the classroom.","cn":"她不让自己的政治观点进入课堂。"},{"en":"A political solution is needed before the water can be shared.","cn":"在分配水源之前，需要一个政治层面的解决方案。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「城邦公民的」——凡涉及谁掌权、谁站队的事 → 政治的","word":"political"},"root":"political 出自希腊 politikos「公民的、城邦的」，源头为 polis「城邦」与 politēs「公民」，经拉丁 politicus 与中古法语 politique 进入英语；polis 更深来源不确定。","sensesIntro":{"en":"Eight senses branch from one adjective: what belongs to the citizen body, then to parties, to power-driven choices, to sensitive topics, to office rivalries, to engaged persons, to the state sphere, and finally to any question of who decides.","cn":"八个义项由同一个形容词分出：先属公民总体，再属党派、属出于权力的选择、属敏感话题、属办公室里的对立、属积极参与的人、属国家领域，最后属任何「谁来决定」的问题。"},"semanticMap":{"core":{"en":"CORE IMAGE: a campaign office wall layered with posters, a list of names to call.","cn":"核心意象：竞选办公室的墙上一层叠一层的海报，以及一列待拨的姓名。"},"chain":["OF THE CITIZENS","OF THE STATE","OF THE PARTIES","OF POWER INTERESTS","OF THE WHOLE ARENA","WHO DECIDES"],"branches":[{"senses":"01","en":"CIVIC BASE: the adjective first marks what belongs to the organised citizen body and its institutions.","cn":"公民基础：这个形容词最初标记属于有组织公民总体及其机构的事物。"},{"senses":"02","en":"PARTY CONTEST: once civic business is organised in parties, the adjective follows the campaign.","cn":"党派竞争：城邦事务一旦组织成党派，这个形容词就跟着竞选活动走。"},{"senses":"03 · 04","en":"MOTIVE AND SENSITIVITY: a choice can be driven by advantage, and a topic can be explosive, and one adjective covers both warnings.","cn":"动机与敏感：选择可能被利益驱动，话题可能一触即发，同一个形容词兼具这两种提醒。"},{"senses":"05 · 06","en":"SMALL SCALE AND PERSONAL: office rivalries repeat the pattern, and a person can be absorbed in it.","cn":"小规模与个人：办公室的对立重演这一格局，而个人也可以沉浸其中。"},{"senses":"07 · 08","en":"SPHERE AND QUESTION: the state sphere is marked off from faith and market, and behind it lies the bare question of who decides.","cn":"领域与问题：国家领域与信仰、市场被划开，而其后正是「谁来决定」这个赤裸的问题。"}]},"affixes":{"intro":{"en":"Political is a Greek adjective stem plus an English adjective ending, and the stem also builds politics, politician and policy.","cn":"political 是希腊形容词词干加英语形容词词尾，同一词干还造出政治、从政者与政策。"},"latinIntro":{"en":"Latin politicus carried the Greek adjective into learned use, and its feminine noun politica stands behind policy and polity.","cn":"拉丁 politicus 把这个希腊形容词带入学术用法，其阴性名词 politica 则是政策与政体两词的来源。"},"items":[{"word":"polis","structure":"polis (Greek noun, 'city-state')","meaning":"city-state","meaningCN":"城邦","example":"The root supplies the civic frame of the word.","exampleCN":"这个词根提供这个词的城邦框架。"},{"word":"polites","structure":"polites (Greek noun, 'citizen')","meaning":"citizen","meaningCN":"公民","example":"The citizen is the reference point of the adjective.","exampleCN":"公民是这个形容词的参照点。"},{"word":"-ikos","structure":"-ikos (Greek adjective suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix turns the citizen into an adjective of belonging.","exampleCN":"这个后缀把「公民」变成表示归属的形容词。"},{"word":"politikos","structure":"polites + -ikos","meaning":"civic, fit to govern","meaningCN":"城邦的；适于治理的","example":"The adjective was used of matters of the community.","exampleCN":"这个形容词用于共同体的事务。"},{"word":"politicus","structure":"politicus (Latin adjective, borrowed from Greek)","meaning":"civil, of the state","meaningCN":"民政的；国家的","example":"Latin kept the adjective for civil affairs.","exampleCN":"拉丁语把这个形容词保留给民政事务。"},{"word":"-al","structure":"-al (Latin and English adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending makes the borrowed stem into an English adjective.","exampleCN":"这个词尾把借来的词干变成英语形容词。"},{"word":"-ly","structure":"-ly (English adverb suffix)","meaning":"in the manner of","meaningCN":"以……的方式","example":"The adverb marks the standpoint rather than the thing.","exampleCN":"副词标记的是角度，而非事物本身。"},{"word":"politicize","structure":"political + -ize (to make)","meaning":"to bring into politics","meaningCN":"使进入政治领域","example":"A budget cut politicized the whole faculty.","exampleCN":"一次预算削减把整个院系政治化了。"},{"word":"apolitical","structure":"a- (without) + political","meaning":"outside politics","meaningCN":"政治之外的","example":"The survey was designed to look apolitical.","exampleCN":"这项调查被设计得看似不问政治。"}],"latinEntries":[{"word":"politicus","structure":"politicus, politica, politicum (adjective, borrowed from Greek)","meaning":"civic, of the state","meaningCN":"城邦的；国家的"},{"word":"politica","structure":"politica, politicae (f., first declension; from Greek ta politika)","meaning":"the study of the state","meaningCN":"对国家的研究"},{"word":"politice","structure":"politice (adverb, borrowed from Greek politikos)","meaning":"in a civic manner","meaningCN":"以公民事务的方式"}]}},{"word":"politically","ipa_uk":"/pəˈlɪtɪkli/","ipa_us":"/pəˈlɪtɪkli/","definition_zh":"在政治上；从政治角度；以政治方式；在权力得失层面","definition_en":"in political terms, from the standpoint of power, or in a way that has political causes or effects","core_image":"记者会上，评论员把一份技术方案按选票得失重新掂量，笔尖停在「选前」两个字旁边","scene":"记者会上，评论员把一份技术方案按选票得失重新掂量，说它在投票前根本推不动。The reform was politically impossible before the election.","sceneCN":"这里指「在政治可行性层面」，对应第 6 个义项：从权力与选票的可行性来判断；句意为这项改革在选举之前政治上根本行不通。画面要点：记者会讲台、写满标注的方案、录音笔。","pos":[{"tag":"adv.","zh":"在政治上；从政治角度（修饰整个判断或某个动作）"}],"collocations":[{"phrase":"politically motivated","zh":"出于政治动机的"},{"phrase":"politically sensitive","zh":"政治上敏感的"},{"phrase":"politically impossible","zh":"政治上行不通的"},{"phrase":"politically speaking","zh":"从政治角度来说"},{"phrase":"politically aware","zh":"有政治意识的"},{"phrase":"politically charged","zh":"带强烈政治色彩的"}],"forms":[{"label":"副词（本词）","form":"politically"},{"label":"形容词","form":"political"},{"label":"名词（政治）","form":"politics"},{"label":"名词（从政者）","form":"politician"},{"label":"动词（使政治化）","form":"politicize"},{"label":"名词（政治化）","form":"politicization"},{"label":"反义副词（较少用）","form":"apolitically"}],"derivatives":[{"word":"political","pos":"adj.","zh":"政治的；政党的"},{"word":"politics","pos":"n.","zh":"政治；政治活动"},{"word":"politician","pos":"n.","zh":"政治家；政客"},{"word":"politicize","pos":"v.","zh":"使政治化"},{"word":"politicization","pos":"n.","zh":"政治化"},{"word":"apolitical","pos":"adj.","zh":"不问政治的"}],"senses":[{"no":"01","title":"In political terms","titleCN":"从政治角度来说","definition":"when a matter is judged by how power, authority and public conflict are involved","definitionCN":"指从权力、权威与公共冲突如何牵涉其中的角度来判断一件事","example":"Politically speaking, the two proposals are identical.","exampleCN":"从政治角度来说，这两项提案并无区别。","why":"the adverb is the adjective plus the English adverbial ending, so it turns the whole judgement into a standpoint.","whyCN":"这个副词是形容词加英语副词词尾构成，因此它把整个判断变成一个观察角度。"},{"no":"02","title":"Out of political motive","titleCN":"出于政治动机","definition":"done because of party advantage or ideological aims rather than for the stated reason","definitionCN":"因党派利益或意识形态目的而做，而非出于所声称的理由","example":"The prosecution was politically motivated, the report concluded.","exampleCN":"报告结论认为，这次起诉是出于政治动机。","why":"once the adverb follows a word like motivated or driven, it names the hidden cause of an act.","whyCN":"当这个副词跟在「驱动、促使」这类词后面时，它指出的是一项行为隐藏的动因。"},{"no":"03","title":"With political consequences","titleCN":"在权力得失上造成后果","definition":"in a way that helps or damages a party's standing, whatever the merits of the act","definitionCN":"不论事情本身对错，都会增强或损害某一方的地位","example":"The apology was politically damaging and morally right.","exampleCN":"这次道歉在政治上受损，在道义上却是对的。","why":"the adverb can measure effects as well as causes, so it marks the ledger of advantage rather than the intention.","whyCN":"这个副词既能衡量原因，也能衡量结果，此处标记的是利益账本，而非动机。"},{"no":"04","title":"In party alignment","titleCN":"在党派归属上","definition":"describing where a person, paper or union stands relative to parties","definitionCN":"描述一个人、一份报纸或一个工会相对于各党派的位置","example":"The journal is politically independent but financially fragile.","exampleCN":"这份期刊在党派上独立，财政上却脆弱。","why":"a field divided into parties makes alignment a property, and the adverb names that property.","whyCN":"一个分成党派的场域会把「归属」变成一种属性，这个副词指的就是这种属性。"},{"no":"05","title":"With political awareness","titleCN":"带有政治意识","definition":"describing a person or group that notices and acts on questions of power","definitionCN":"形容注意权力问题并据此行动的个人或群体","example":"The students were politically aware long before they could vote.","exampleCN":"这些学生在能投票之前很久就有了政治意识。","why":"awareness is a state of mind, so the adverb modifies the person's condition rather than the act.","whyCN":"意识是一种心理状态，因此这个副词修饰的是人的状态，而不是行为。"},{"no":"06","title":"In terms of feasibility","titleCN":"在可行性层面","definition":"judging whether a plan can actually be carried through the institutions that must approve it","definitionCN":"判断一项方案能否真的通过那些必须批准它的机构","example":"A carbon tax may be sound economics and politically impossible.","exampleCN":"碳税在经济学上可能站得住，在政治上却行不通。","why":"a good plan still needs votes, so the adverb measures the distance between merit and passage.","whyCN":"好方案也得有票才能过，因此这个副词衡量的是「有理」与「通过」之间的距离。"},{"no":"07","title":"By state rather than private means","titleCN":"以国家而非私人的方式","definition":"describing an appointment or decision made through state authority instead of professional or market criteria","definitionCN":"形容任命或决定是经国家权威作出，而非按专业或市场标准","example":"The post was filled politically, not by open competition.","exampleCN":"这个职位是按政治方式补上的，没有公开竞争。","why":"the adverb marks whose logic is at work, and here the logic is that of state authority rather than of a profession.","whyCN":"这个副词标记的是哪一种逻辑在起作用，此处起作用的是国家权威的逻辑，而非专业逻辑。"},{"no":"08","title":"Abstract: measured by who decides","titleCN":"抽象义：按「谁来决定」来衡量","definition":"in general use, judged by the distribution of decision-making power rather than by technical merit","definitionCN":"泛指按决策权的分布、而非技术优劣来评判","example":"Even the seating plan was politically loaded.","exampleCN":"连座位安排都带着政治分量。","why":"the abstract sense reduces every use to one yardstick, namely who gains or loses the power to decide.","whyCN":"抽象义把全部用法归结为一把尺子，即谁因此得到或失去了决定权。"}],"etymology":{"intro":{"en":"Politically is the adjective political with the English adverbial ending -ly, and political goes back through French and Latin to a Greek adjective for civic matters. Dates are approximate.","cn":"politically 是形容词 political 加英语副词词尾构成，而 political 经法语与拉丁语上溯到希腊语中表示城邦事务的形容词。年代均为约数。"},"items":[{"era":"GREEK POLITIKOS","en":"Politikos meant 'of a citizen, civic', built on polis 'city-state' and polites 'citizen'; the deeper origin of polis is not settled and a pre-Greek source is only a hypothesis.","cn":"politikos 意为「公民的、城邦的」，由 polis「城邦」与 politēs「公民」构成；polis 更深的来源未有定论，前希腊语来源只是假说。"},{"era":"LATIN POLITICUS","en":"Latin borrowed the adjective as politicus for civil and state affairs, and the related adverb politice was used for 'in a civic manner'.","cn":"拉丁语把这一形容词借作 politicus，用于民政与国家事务，相关副词 politice 表示「以公民事务的方式」。"},{"era":"FRENCH POLITIQUE","en":"Middle French politique carried the stem into English in the fifteenth century, where it became the adjective political.","cn":"中古法语 politique 在十五世纪把这一词干带入英语，在那里成为形容词 political。"},{"era":"OLD ENGLISH -LICE","en":"The adverbial ending came from Old English -lice, which turned adjectives into adverbs of manner; after the loss of inflection it settled as -ly.","cn":"副词词尾出自古英语中表示「以……方式」的形式，把形容词变成表示方式或角度的副词；屈折消失后固定为现代拼写。"},{"era":"MODERN ADVERBIAL USE","en":"Phrases such as politically motivated and politically impossible became common in the twentieth century, when the adverb began to judge causes, effects and feasibility in one word.","cn":"到二十世纪，「出于政治动机」「政治上行不通」这类说法普及，这个副词开始用一个词同时评判原因、后果与可行性。"}]},"similar":{"note":{"en":"Group one holds forms of the same stem that are easily confused with this adverb; group two holds adverbs that answer a similar question from a different angle.","cn":"第一组是同词干、容易与本副词混淆的形式；第二组是从不同角度回答类似问题的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"political","ipa":"/pəˈlɪtɪkəl/","tag":"the adjective","definition":"The adjective describing what belongs to government or power; it modifies a noun, whereas the adverb modifies a judgement.","definitionCN":"形容词，描述属于政府或权力的事物；它修饰名词，而本词副词修饰判断。"},{"word":"politic","ipa":"/ˈpɒlətɪk/","tag":"prudent","definition":"A separate adjective meaning shrewd or tactful; it has nothing to do with the adverb's meaning of power calculation.","definitionCN":"另一个形容词，意为精明得体的；与本副词表示权力算计的含义无关。"},{"word":"politics","ipa":"/ˈpɒlətɪks/","tag":"the noun","definition":"The activity or the field itself; the adverb describes how something relates to that activity.","definitionCN":"指活动或领域本身；本词副词描述某事物与该活动的关系。"},{"word":"apolitically","ipa":"/ˌeɪpəˈlɪtɪkli/","tag":"the negation","definition":"A rare opposite meaning 'without political involvement'; it negates exactly the standpoint this adverb supplies.","definitionCN":"较少见的反义说法，意为「不带政治介入地」；它正好否定了本副词所提供的那种角度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"strategically","ipa":"/strəˈtiːdʒɪkli/","tag":"calculated advantage","definition":"Judged by long-term advantage; it stresses planning for gain and need not involve parties or the state.","definitionCN":"按长期利益来评判；强调为获益而谋划，未必涉及党派或国家。"},{"word":"diplomatically","ipa":"/ˌdɪpləˈmætɪkli/","tag":"handled with tact","definition":"In a way that avoids giving offence; political can be blunt about power, while this word is about tact.","definitionCN":"以不得罪人的方式；政治一词对权力可以直白，而这个词讲的是圆融。"},{"word":"electorally","ipa":"/ɪˈlektərəli/","tag":"votes only","definition":"Judged by effect on elections; it is narrower than the political standpoint because it counts only votes.","definitionCN":"按对选举的影响判断；只计选票，因此比政治角度窄。"},{"word":"constitutionally","ipa":"/kənˌstɪtjuːˈʃənəli/","tag":"legal limits","definition":"Judged by whether the law of the state permits it; political feasibility may differ from legal permissibility.","definitionCN":"按国家法律是否允许来判断；政治可行性与法律许可并不等同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Adjective plus the English adverbial ending: the standpoint of power is applied to the whole sentence.","cn":"形容词加英语副词词尾：把权力的角度加在整句话上。"},{"en":"The stem is the Greek word for a city-state, so the standpoint is that of the citizen body.","cn":"词干是希腊语中表示城邦的词，因此这个角度是公民总体的角度。"},{"en":"Fixed phrases show the main uses: politically motivated, politically sensitive, politically impossible.","cn":"固定搭配显示主要用法：出于政治动机、政治上敏感、政治上行不通。"},{"en":"One adverb can judge cause, effect and feasibility, which is why it is so common in news analysis.","cn":"一个副词能同时评判原因、后果与可行性，所以它在新闻分析里极为常见。"},{"en":"Its opposite is the apolitical stance, which claims to stand outside power altogether.","cn":"它的反面是不问政治的立场，那种立场声称完全站在权力之外。"}],"abstract":[{"en":"Picture a pair of glasses that turns everything red or green according to who wins.","cn":"想象一副眼镜，把一切按谁输谁赢染成红色或绿色。"},{"en":"Picture a ledger with two columns, gain and loss, and every act entered in one of them.","cn":"想象一本账簿只有两栏，得与失，每个行为都被记进其中一栏。"},{"en":"Picture a door that will not open unless the right votes are counted first.","cn":"想象一扇门，不先数够票就打不开。"}]},"examples":[{"en":"The decision was politically costly but legally sound.","cn":"这个决定在政治上代价很高，在法律上却站得住。"},{"en":"Politically, the two regions have drifted apart since the split.","cn":"从政治上说，分裂之后这两个地区渐行渐远。"},{"en":"She is politically engaged but refuses to join a party.","cn":"她积极参与政治，却拒绝加入任何政党。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「政治的 + 地」——凡事都放到权力得失这杆秤上量一量 → 在政治上","word":"politically"},"root":"politically 由 political 加古英语来源的副词词尾构成；political 出自希腊 politikos「公民的、城邦的」，源头 polis「城邦」，经拉丁 politicus 与法语进入英语。","sensesIntro":{"en":"Eight readings of one adverb: it can name the standpoint, the motive, the consequence, the party alignment, the awareness, the feasibility, the state logic, and finally the bare measure of who decides.","cn":"同一个副词有八种读法：它可指观察角度、动机、后果、党派归属、意识状态、可行性、国家逻辑，最后是「谁来决定」这把最简的尺子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a technical plan weighed on a scale marked with votes.","cn":"核心意象：一份技术方案被放到标着选票刻度的秤上称量。"},"chain":["FROM WHAT ANGLE","BECAUSE OF WHAT","AT WHAT COST","ON WHICH SIDE","HOW FAR IT CAN GO","WHO DECIDES"],"branches":[{"senses":"01","en":"STANDPOINT: the adverb first says which lens the sentence is being read through.","cn":"角度：这个副词首先说明整句话是通过哪一副镜片来读的。"},{"senses":"02 · 03","en":"CAUSE AND COST: the same word can point to a hidden motive or to the damage an act does.","cn":"原因与代价：同一个词既能指隐藏的动机，也能指行为造成的损失。"},{"senses":"04 · 05","en":"ALIGNMENT AND AWARENESS: a paper can stand somewhere on the party map, and a person can be awake to power.","cn":"归属与意识：一份报刊可在党派地图上有其位置，一个人也可对权力保持清醒。"},{"senses":"06 · 07","en":"FEASIBILITY AND STATE LOGIC: merit is weighed against votes, and an appointment is weighed against professional standards.","cn":"可行性与国家逻辑：道理被拿去和选票比，任命被拿去和专业标准比。"},{"senses":"08","en":"MEASURE: everything reduces to one question, who gains or loses the power to decide.","cn":"尺子：一切都归结为一个问题，谁因此得到或失去了决定权。"}]},"affixes":{"intro":{"en":"The adverb is a Greek-derived adjective plus an English ending, and the stem itself carries a Greek noun for the city.","cn":"这个副词是希腊来源的形容词加英语词尾，而词干本身还带着一个表示城邦的希腊名词。"},"latinIntro":{"en":"Latin politicus and the adverb politice carried the Greek civic adjective into learned prose, where English later found it.","cn":"拉丁 politicus 与副词 politice 把这个希腊形容词带入学术散文，英语后来正是从那里取得它。"},"items":[{"word":"polis","structure":"polis (Greek noun, 'city-state')","meaning":"city-state","meaningCN":"城邦","example":"The root supplies the civic frame.","exampleCN":"这个词根提供城邦的框架。"},{"word":"politikos","structure":"polites + -ikos (adjective)","meaning":"civic, of citizens","meaningCN":"公民的；城邦的","example":"The adjective describes matters of the citizen body.","exampleCN":"这个形容词描述公民总体的事务。"},{"word":"politicus","structure":"politicus (Latin adjective, borrowed)","meaning":"civil, of the state","meaningCN":"民政的；国家的","example":"Latin used it for affairs of state.","exampleCN":"拉丁语用它指国家事务。"},{"word":"politice","structure":"politice (Latin adverb, borrowed)","meaning":"in a civic manner","meaningCN":"以城邦事务的方式","example":"The Latin adverb already marked a standpoint.","exampleCN":"这个拉丁副词已经在标记一种角度。"},{"word":"-al","structure":"-al (adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending makes an English adjective from the stem.","exampleCN":"这个词尾把词干变成英语形容词。"},{"word":"-ly","structure":"-ly (English adverb suffix, from Old English -lice)","meaning":"in the manner of","meaningCN":"以……的方式","example":"The ending turns the adjective into a modifier of judgements.","exampleCN":"这个词尾把形容词变成修饰判断的词。"},{"word":"politicize","structure":"political + -ize (to make)","meaning":"to make political","meaningCN":"使政治化","example":"The hearing politicized a routine appointment.","exampleCN":"这场听证把一次例行任命政治化了。"},{"word":"apolitical","structure":"a- (without) + political","meaning":"outside politics","meaningCN":"政治之外的","example":"A technical standard can look apolitical.","exampleCN":"技术标准可以显得与政治无关。"},{"word":"politics","structure":"politic + -ics (field of study or activity)","meaning":"the activity of governing","meaningCN":"治理的活动","example":"Politics decides the timetable.","exampleCN":"政治决定时间表。"}],"latinEntries":[{"word":"politicus","structure":"politicus, politica, politicum (adjective, borrowed from Greek)","meaning":"civic, of the state","meaningCN":"城邦的；国家的"},{"word":"politice","structure":"politice (adverb, borrowed from Greek politikos)","meaning":"in a civic manner","meaningCN":"以公民事务的方式"},{"word":"politica","structure":"politica, politicae (f., first declension)","meaning":"the study of the state","meaningCN":"对国家的研究"}]}},{"word":"politician","ipa_uk":"/ˌpɒləˈtɪʃən/","ipa_us":"/ˌpɑːləˈtɪʃən/","definition_zh":"政治家；从政者；政客（含贬义时指善于权术、重许诺轻原则的人）","definition_en":"a person who holds or seeks public office and lives by political activity, sometimes with the implication of manoeuvring rather than principle","core_image":"集市广场上，竞选者站在木箱上讲话，向每个伸出手的人逐一握过去","scene":"集市广场上，竞选者站在木箱上讲完承诺，又向每个伸出手的人逐一握过去。The politician promised to fix the drains before the winter rains came.","sceneCN":"这里指「担任或谋求公职的从政者」，对应第 1 个义项：以公职身份参与政治的人；句意为这位从政者承诺在冬雨到来之前修好排水。画面要点：木箱讲台、人群、握手动作。","pos":[{"tag":"n.","zh":"政治家；从政者（中性，指以政治为业的人）"},{"tag":"n.","zh":"政客（含贬义，指工于权术、重私利者）"}],"collocations":[{"phrase":"a career politician","zh":"职业从政者"},{"phrase":"a local politician","zh":"地方从政者"},{"phrase":"a seasoned politician","zh":"老练的从政者"},{"phrase":"a corrupt politician","zh":"腐败的政客"},{"phrase":"a politician's promise","zh":"政客的承诺"},{"phrase":"a prominent politician","zh":"知名政治人物"}],"forms":[{"label":"复数","form":"politicians"},{"label":"形容词（政治的）","form":"political"},{"label":"副词（在政治上）","form":"politically"},{"label":"名词（政治）","form":"politics"},{"label":"名词（政体）","form":"polity"},{"label":"动词（使政治化）","form":"politicize"}],"derivatives":[{"word":"political","pos":"adj.","zh":"政治的；政党的"},{"word":"politically","pos":"adv.","zh":"在政治上；从政治角度"},{"word":"politics","pos":"n.","zh":"政治；政治活动"},{"word":"politicize","pos":"v.","zh":"使政治化"},{"word":"politicization","pos":"n.","zh":"政治化"}],"senses":[{"no":"01","title":"A holder or seeker of public office","titleCN":"担任或谋求公职的人","definition":"a person who occupies an elected or appointed office in government or is running for one","definitionCN":"在政府中担任经选举或任命产生的职位、正在竞选这类职位的人","example":"The politician promised to fix the drains before winter.","exampleCN":"这位从政者承诺在入冬前修好排水。","why":"the suffix marks the practitioner of the activity named by the stem, so the word literally means one who does civic politics.","whyCN":"后缀标记的是词干所指活动的从业者，因此这个词字面上就是一个做城邦政治的人。"},{"no":"02","title":"One who lives by politics as a trade","titleCN":"以政治为职业的人","definition":"a person whose income, identity and daily work come from political activity rather than from another profession","definitionCN":"收入、身份与日常工作都来自政治活动、而非另一门职业的人","example":"He had been a politician for thirty years and had never held another job.","exampleCN":"他做了三十年从政者，从未干过别的工作。","why":"an activity becomes a trade when it supports a life, and the word then carries the neutral sense of a profession.","whyCN":"一项活动一旦能养活一个人，就成了职业，这个词也就带上中性的职业含义。"},{"no":"03","title":"The pejorative reading: a dealer in promises","titleCN":"贬义：只会许诺与算计的人","definition":"a person seen as caring more about advantage and image than about doing what is right","definitionCN":"被认为更在意利益与形象、而非把事情做对的人","example":"They called him a politician to his face, meaning it as an insult.","exampleCN":"他们当面称他为政客，这词是当侮辱用的。","why":"because the trade depends on winning consent, the same word easily slides into a charge of insincerity.","whyCN":"由于这一行依赖赢得同意，同一个词很容易滑向「不真诚」的指责。"},{"no":"04","title":"A local officeholder","titleCN":"地方层面的从政者","definition":"a person active in municipal or county government, closer to ward business than to national debate","definitionCN":"活跃于市镇或县级政府的人，离选区事务比离全国辩论更近","example":"A local politician opened the new clinic and stayed for every photograph.","exampleCN":"一位地方从政者为新诊所剪彩，每张合影都不缺席。","why":"the scale of office is supplied by an adjective, and local names the rung nearest to voters.","whyCN":"职位层级由形容词补出，而「地方的」正指离选民最近的那一级。"},{"no":"05","title":"A party figure who brokers support","titleCN":"在党内撮合支持的人","definition":"a person whose standing rests on organising votes and alliances within a party rather than on public speaking","definitionCN":"地位靠组织党内票源与结盟、而非靠公开演讲的人","example":"The party politician settled the nomination in a back room.","exampleCN":"这位党务人物在后台一间屋子里敲定了提名。","why":"inside a party the work is counting and trading support, so the word shifts from office to organization.","whyCN":"在政党内部，工作是数票与换取支持，于是这个词从「职位」转向「组织」。"},{"no":"06","title":"A skilled operator in any institution","titleCN":"任何机构里善于运作的人","definition":"in extended use, a colleague who wins by alliance and timing inside a firm, school or association","definitionCN":"引申用法：在企业、学校或团体内部靠结盟与时点取胜的同事","example":"The department head was a politician long before he held a title.","exampleCN":"这位系主任在拿到头衔之前很久就是个政治人物了。","why":"the pattern of allies and rivals repeats at any scale, so the label is borrowed wherever influence is scarce.","whyCN":"盟友与对手的格局在任何规模上都会重演，因此只要影响力稀缺，这个标签就会被借去用。"},{"no":"07","title":"The older reading: one versed in statecraft","titleCN":"旧义：精通治国之术的人","definition":"in earlier usage, a person learned in the theory and practice of governing, close to what we now call a statesman","definitionCN":"较早的用法中指通晓治国理论与实务的人，接近今天所说的政治家","example":"Sixteenth-century writers praised the politician who could hold a restless city.","exampleCN":"十六世纪的作者称赞那种能稳住躁动城邦的治国者。","why":"when the word entered English it named knowledge of civic affairs, and the pejorative tone came later with mass electoral politics.","whyCN":"这个词进入英语时指通晓城邦事务的学问，贬义色彩是后来随大众选举政治才出现的。"},{"no":"08","title":"Abstract: one who turns influence into office","titleCN":"抽象义：把影响力换成职位的人","definition":"in general use, anyone who converts personal influence into formal authority over a group","definitionCN":"泛指把个人影响力换成对某个群体的正式权威的人","example":"In any club, the politician is the member who knows when to call the vote.","exampleCN":"在任何社团里，政治人物都是那个知道何时该提请表决的成员。","why":"the abstract sense keeps only the exchange of influence for authority and lets the state and the ballot box fall away.","whyCN":"抽象义只留下「以影响力换权威」这一交换，国家与票箱都退出了画面。"}],"etymology":{"intro":{"en":"Politician is an English noun built on the Greek-derived stem of political with the person suffix -ian, and its meaning has shifted from learned statecraft to electoral profession. Dates are approximate.","cn":"politician 是英语用 political 的希腊来源词干加表人后缀构成的名词，其含义从「治国之学」演变为「选举职业」。年代均为约数。"},"items":[{"era":"GREEK POLIS","en":"Polis meant a city-state and its citizen body; its deeper origin is not established, and the pre-Greek suggestion is only a hypothesis.","cn":"polis 指城邦及其公民总体；它更深的来源未得到证明，前希腊语来源的说法只是假说。"},{"era":"GREEK POLITIKOS","en":"Politikos meant 'of citizens, civic, fit for governing', and the derived art of civic management was called politike.","cn":"politikos 意为「公民的、城邦的、适于治理的」，由它派生的治城之术称为 politike。"},{"era":"LATIN POLITICUS","en":"Latin borrowed politicus for civil and state affairs, and medieval writers used politica for the study of the state.","cn":"拉丁语借入 politicus 用于民政与国家事务，中世纪作者用 politica 指对国家的研究。"},{"era":"SIXTEENTH-CENTURY ENGLISH","en":"The English noun first meant a person skilled in the science of government, often in a neutral or approving tone.","cn":"这个英语名词最初指精通治国之学的人，语气常为中性甚至赞许。"},{"era":"MASS ELECTORAL POLITICS","en":"As parties and mass electorates grew in the nineteenth century, the word settled into its modern sense of a person who lives by winning office, and the disparaging tone followed.","cn":"十九世纪政党与大众选民兴起后，这个词固定为「以赢得职位为业的人」这一现代义，贬义语气也随之而来。"}]},"similar":{"note":{"en":"Group one holds words from the same stem that are easily mistaken for the person; group two holds labels for people in public life with different shades of approval.","cn":"第一组是同词干、容易被误当成本词的词；第二组是评价色彩不同的公共人物称谓。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"politics","ipa":"/ˈpɒlətɪks/","tag":"the activity","definition":"The activity or field itself; a politician is the person who practices it.","definitionCN":"指活动或领域本身；politician 则是从事这一活动的人。"},{"word":"political","ipa":"/pəˈlɪtɪkəl/","tag":"the adjective","definition":"Describing what belongs to government or power; it cannot stand for the person.","definitionCN":"描述属于政府或权力的事物；不能用来指人。"},{"word":"politic","ipa":"/ˈpɒlətɪk/","tag":"prudent","definition":"An adjective meaning shrewd and tactful, not a noun for an officeholder.","definitionCN":"形容词，意为精明得体的，不是指公职人员的名词。"},{"word":"policy","ipa":"/ˈpɒləsi/","tag":"a plan","definition":"A course of action adopted by a body; it sounds close but names a document or a rule, not a person.","definitionCN":"机构采用的行动方针；读音相近，但指的是文件或规则，不是人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"statesman","ipa":"/ˈsteɪtsmən/","tag":"approving","definition":"A senior figure respected for judgement in public affairs; the word is almost always a compliment, unlike politician.","definitionCN":"因公共事务上的判断力而受尊敬的人物；这个词几乎总是褒义，与 politician 不同。"},{"word":"officeholder","ipa":"/ˈɒfɪsˌhəʊldə/","tag":"neutral and formal","definition":"A neutral term for anyone currently holding a post; it says nothing about how the post was won or used.","definitionCN":"对现任职位者的中性说法；不涉及职位如何得到或如何使用。"},{"word":"legislator","ipa":"/ˈleɡɪsleɪtə/","tag":"one function","definition":"A person who makes laws in a parliament; a politician may serve in an executive post and never vote on a bill.","definitionCN":"在议会中制定法律的人；政治人物也可能担任行政职务，从不参与法案表决。"},{"word":"demagogue","ipa":"/ˈdiːməɡɒɡ/","tag":"strongly negative","definition":"A leader who wins support by playing on fear and prejudice; it is far harsher than the pejorative use of politician.","definitionCN":"靠煽动恐惧与偏见来赢得支持的领袖；比 politician 的贬义用法严厉得多。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The stem means civic, and the person suffix marks the one who practices civic business for a living.","cn":"词干意为「城邦的」，表人后缀标记的正是以城邦事务为业的人。"},{"en":"The family runs political, politically, politics, polity and politicize.","cn":"同族词包括政治的、在政治上、政治、政体与使政治化。"},{"en":"Fixed phrases show the tone: a seasoned politician is neutral, a corrupt politician is a charge.","cn":"固定搭配显示语气：老练的从政者是中性的，腐败的政客则是控诉。"},{"en":"The word entered English meaning a student of statecraft and only later became the electoral professional.","cn":"这个词进入英语时指治国之学的研习者，后来才变成选举职业者。"},{"en":"The approving counterpart is statesman, which is almost never used as an insult.","cn":"褒义对应词是 statesman，那个词几乎从不被当作侮辱使用。"}],"abstract":[{"en":"Picture a wooden crate used as a platform, with hands reaching up from the crowd.","cn":"想象一只木箱被当作讲台，人群中有手不断伸上来。"},{"en":"Picture a notebook of names, each marked with a promise and a date.","cn":"想象一本写满姓名的册子，每个名字旁都记着一句承诺和一个日期。"},{"en":"Picture a back room where two people count votes on their fingers before a public vote.","cn":"想象后台一间屋子里，两个人在公开表决前掰着手指清点票数。"}]},"examples":[{"en":"The politician spent the morning at three different factory gates.","cn":"这位从政者一上午跑了三个工厂门口。"},{"en":"Voters said they trusted the engineer more than the politician.","cn":"选民说他们更信任那位工程师，而不是那位政客。"},{"en":"Every politician in the county knew the bridge budget by heart.","cn":"县里每一位从政者都把桥梁预算记得滚瓜烂熟。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「城邦事务 + 做事的人」——以摆平众人之事为职业的人 → 从政者","word":"politician"},"root":"politician 由 political 的希腊来源词干加表示「从事者」的表人后缀构成；词干出自希腊 politikos「公民的、城邦的」，源头 polis「城邦」，经拉丁 politicus 与法语进入英语。","sensesIntro":{"en":"Eight senses slide along one career: the officeholder, the professional, the promise-dealer, the local figure, the party broker, the institutional operator, the old student of statecraft, and finally anyone trading influence for authority.","cn":"八个义项沿同一条职业线滑动：任职者、以此为业者、兜售承诺者、地方人物、党内撮合者、机构里的运作人、旧义中的治国学者，最后是把影响力换成权威的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a speaker on a crate, shaking every hand within reach.","cn":"核心意象：站在木箱上的讲话者，把够得到的手都握一遍。"},"chain":["HOLD AN OFFICE","LIVE BY POLITICS","SELL PROMISES","WORK THE PARTY","TRADE INFLUENCE","CONVERT TO AUTHORITY"],"branches":[{"senses":"01","en":"OFFICE: the plain reading, a person who holds or seeks a public post.","cn":"职位：最朴素的读法，即担任或谋求公职的人。"},{"senses":"02 · 03","en":"TRADE AND SCEPTICISM: once politics is a livelihood, the same word can be neutral about the job or doubtful about the person.","cn":"职业与怀疑：政治一旦成为生计，同一个词既可就职业作中性描述，也可就人品表示怀疑。"},{"senses":"04 · 05","en":"SCALE AND PARTY: the rung nearest the voter and the back-room broker are two ends of the same ladder.","cn":"层级与党派：离选民最近的那一级与后台的撮合者，是同一条梯子的两端。"},{"senses":"06 · 07","en":"ANYWHERE AND EARLIER: the operator appears in any institution, and the older reading still honours the student of statecraft.","cn":"无处不在与更早用法：运作人出现在任何机构里，而旧读法仍尊重治国之学的研习者。"},{"senses":"08","en":"EXCHANGE: strip the state away and what remains is influence turned into authority.","cn":"交换：把国家抽走，剩下的就是影响力被换成权威。"}]},"affixes":{"intro":{"en":"Politician is a Greek-derived stem plus a Latin-derived person suffix, and both halves are shared with a large English family.","cn":"politician 是希腊来源的词干加拉丁来源的表人后缀，两半都与一个庞大的英语词族共享。"},"latinIntro":{"en":"Latin politicus stands behind the stem, and the person suffix reached English through French forms ending in -ien.","cn":"拉丁 politicus 是这一词干的来源，表人后缀则经法语中同类的表人形式进入英语。"},"items":[{"word":"polis","structure":"polis (Greek noun, 'city-state')","meaning":"city-state","meaningCN":"城邦","example":"The root names the community whose affairs the person handles.","exampleCN":"这个词根指出此人处理的共同体事务。"},{"word":"politikos","structure":"polites + -ikos","meaning":"civic, of citizens","meaningCN":"公民的；城邦的","example":"The adjective supplies the field of work.","exampleCN":"这个形容词提供工作的领域。"},{"word":"politicus","structure":"politicus (Latin adjective)","meaning":"civil, of the state","meaningCN":"民政的；国家的","example":"Latin carried the stem into learned use.","exampleCN":"拉丁语把这一词干带入学术用法。"},{"word":"-ian","structure":"-ian (person suffix, through French)","meaning":"one who practices","meaningCN":"从事……的人","example":"The suffix marks the practitioner rather than the theorist.","exampleCN":"这个后缀标记从业者，而非理论者。"},{"word":"political","structure":"politic + -al","meaning":"relating to government","meaningCN":"与政府相关的","example":"The adjective describes the field.","exampleCN":"这个形容词描述这一领域。"},{"word":"politics","structure":"politic + -ics","meaning":"the activity","meaningCN":"这一活动","example":"Politics is the practice, not the person.","exampleCN":"政治是实践，不是人。"},{"word":"politicize","structure":"political + -ize","meaning":"to make political","meaningCN":"使政治化","example":"The dispute was politicized within a week.","exampleCN":"这场争端一周之内就被政治化了。"},{"word":"polity","structure":"Latin politia + -y","meaning":"an organised community","meaningCN":"有组织的政治共同体","example":"A polity outlasts any single officeholder.","exampleCN":"政体比任何一位任职者都活得久。"}],"latinEntries":[{"word":"politicus","structure":"politicus, politica, politicum (adjective, borrowed from Greek)","meaning":"civic, of the state","meaningCN":"城邦的；国家的"},{"word":"politica","structure":"politica, politicae (f., first declension)","meaning":"the study of the state","meaningCN":"对国家的研究"},{"word":"politia","structure":"politia, politiae (f., first declension)","meaning":"the constitution of a state","meaningCN":"国家的政制"}]}},{"word":"political science","ipa_uk":"/pəˈlɪtɪkəl ˈsaɪəns/","ipa_us":"/pəˈlɪtɪkəl ˈsaɪəns/","definition_zh":"政治学；以政府、权力与政治行为为对象的系统研究及其学科建制","definition_en":"the systematic study of government, power and political behaviour, and the academic field that carries it","core_image":"图书馆长桌上摊开比较政体的表格，学生用铅笔在边栏记下各国选举制度的差别","scene":"图书馆里，学生摊开一张比较政体的表格，用铅笔在边栏记下各国选举制度的差别。She chose political science because she wanted to measure how coalitions form.","sceneCN":"这里指「以政府与权力为对象的系统研究」，对应第 1 个义项：把政治现象当作可研究对象的学科；句意为她选择政治学，是因为她想测量联合政府是如何形成的。画面要点：长桌、比较表、铅笔标注。","pos":[{"tag":"n.","zh":"政治学（学科名；作主语时视为单数）"}],"collocations":[{"phrase":"a degree in political science","zh":"政治学学位"},{"phrase":"the department of political science","zh":"政治学系"},{"phrase":"comparative political science","zh":"比较政治学"},{"phrase":"political science research","zh":"政治学研究"},{"phrase":"a professor of political science","zh":"政治学教授"},{"phrase":"empirical political science","zh":"实证政治学"}],"forms":[{"label":"名词短语（本词）","form":"political science"},{"label":"复数（少见，指多个学科传统）","form":"political sciences"},{"label":"形容词（政治的）","form":"political"},{"label":"名词（政治）","form":"politics"},{"label":"名词（科学）","form":"science"},{"label":"名词（科学家）","form":"scientist"}],"derivatives":[{"word":"political scientist","pos":"n.","zh":"政治学家"},{"word":"political","pos":"adj.","zh":"政治的"},{"word":"scientific","pos":"adj.","zh":"科学的；按科学方法的"},{"word":"scientifically","pos":"adv.","zh":"以科学方法"},{"word":"scientist","pos":"n.","zh":"科学家"}],"senses":[{"no":"01","title":"The systematic study of power and government","titleCN":"对权力与政府的系统研究","definition":"the academic study of how authority is won, used and limited, and how people behave politically","definitionCN":"研究权威如何被赢得、使用与限制，以及人们如何从事政治行为的学问","example":"Political science asks why some coalitions last and others collapse.","exampleCN":"政治学追问为什么有些联盟持久、有些却瓦解。","why":"the phrase pairs a civic adjective with the Latin word for knowledge, claiming for politics the method of an organised science.","whyCN":"这个短语把表示城邦的形容词与拉丁语中「知识」一词配在一起，等于为政治主张一种有组织科学的方法。"},{"no":"02","title":"A department or degree programme","titleCN":"一个系或一个学位项目","definition":"the institutional unit in a university that teaches and certifies the subject","definitionCN":"大学里教授并认证这一学科的组织单位","example":"The department of political science hired two game theorists.","exampleCN":"政治学系聘用了两位博弈论学者。","why":"a discipline becomes a place once it has staff, students and a budget, and the phrase names that unit.","whyCN":"一门学科一旦有了人员、学生与预算，就变成一个地方，这个短语便用来指那个单位。"},{"no":"03","title":"A course or lecture series","titleCN":"一门课程或一组讲座","definition":"a teaching sequence introducing students to the subject, often taken as a requirement","definitionCN":"向学生介绍这一学科的教学序列，常作为必修课","example":"Political science was the only course he ever failed.","exampleCN":"政治学是他唯一挂过的一门课。","why":"the same name covers the whole field and the small slice of it taught in one term.","whyCN":"同一个名称既指整个领域，也指一个学期里教的那一小块。"},{"no":"04","title":"The empirical, data-driven tradition","titleCN":"以数据和实证为方法的那一支","definition":"the branch that treats political behaviour as measurable and tests claims against evidence","definitionCN":"把政治行为当作可测量对象、并用证据检验论断的那一支","example":"Modern political science counts votes rather than praising constitutions.","exampleCN":"现代政治学数票，而不是赞颂宪法。","why":"the word science inside the phrase is a promise about method, and this sense holds the field to that promise.","whyCN":"短语中的「科学」二字是对方法的承诺，这一义项正是要求该领域兑现这一承诺。"},{"no":"05","title":"The published literature of the field","titleCN":"这一领域的文献总体","definition":"the accumulated books and articles that a researcher must know and cite","definitionCN":"研究者必须了解并引用的一批累积起来的专著与论文","example":"The finding had been in political science for twenty years.","exampleCN":"这个发现在政治学文献里已经存在二十年了。","why":"a discipline is also a body of text, so the phrase can stand for everything written within it.","whyCN":"一门学科同时是一堆文本，因此这个短语也能指在其中写下的全部内容。"},{"no":"06","title":"The professional community","titleCN":"由从业者组成的学术共同体","definition":"the associations, journals and conferences through which the field governs itself","definitionCN":"这一领域用以自我管理的学会、期刊与会议","example":"Political science met in the same hotel every autumn.","exampleCN":"政治学界每年秋天都在同一家旅馆聚会。","why":"a field with its own journals and prizes behaves like a guild, and the phrase can name the guild.","whyCN":"一个拥有自己的期刊与奖项的领域，行为像一个行会，这个短语就能指那个行会。"},{"no":"07","title":"Study contrasted with practice","titleCN":"与实务相对的研究","definition":"the theoretical side of politics, set against the work of campaigning and governing","definitionCN":"政治的理论一面，与竞选和治理的实际工作相对","example":"He knew political science but could not win a ward.","exampleCN":"他懂政治学，却赢不下一个选区。","why":"the phrase marks knowledge about politics, and that marking sharpens whenever it is compared with doing politics.","whyCN":"这个短语标记的是关于政治的知识，一旦与做政治相比较，这一标记就格外分明。"},{"no":"08","title":"Abstract: the study of collective decision-making","titleCN":"抽象义：对集体决策的研究","definition":"in general use, any systematic inquiry into how groups make binding choices","definitionCN":"泛指对群体如何作出有约束力的选择所作的任何系统探究","example":"Committees can be studied with the tools of political science.","exampleCN":"委员会可以用政治学的工具来研究。","why":"the abstract sense moves the object from the state to any group that must decide together.","whyCN":"抽象义把研究对象从国家移到任何必须共同作出决定的群体。"}],"etymology":{"intro":{"en":"Political science joins a Greek-derived adjective for civic affairs with a Latin-derived noun for knowledge, a pairing made in the nineteenth century. Dates are approximate.","cn":"political science 把希腊来源、表示城邦事务的形容词与拉丁来源、表示知识的名词配在一起，这一搭配成形于十九世纪。年代均为约数。"},"items":[{"era":"GREEK POLIS","en":"Polis meant a city-state and its citizen body; its deeper origin is not settled, and a pre-Greek source is only a hypothesis.","cn":"polis 指城邦及其公民总体；其更深来源未有定论，前希腊语来源只是假说。"},{"era":"LATIN SCIENTIA","en":"Scientia meant 'knowledge, understanding', from sciens, the participle of scire 'to know'; the deeper origin of scire is uncertain, and a link with scindere 'to split' is a hypothesis, not a demonstrated derivation.","cn":"scientia 意为「知识、理解」，出自 scire「知道」的分词形式；scire 更深的来源不确定，把它与 scindere「切开」相联系只是假说，并非已证实的派生。"},{"era":"MIDDLE ENGLISH SCIENCE","en":"English took science in the fourteenth century as a general word for knowledge or a skill, and only in the nineteenth century did it narrow to the natural sciences.","cn":"英语在十四世纪借入 science，泛指知识或一门技艺，直到十九世纪才收窄为自然科学。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"The phrase appeared in the early nineteenth century as a name for the systematic study of states, and university chairs and departments followed later in the century.","cn":"这一短语在十九世纪初出现，用来指对国家的系统研究，大学教席与系所则在该世纪稍晚建立。"},{"era":"TWENTIETH-CENTURY METHOD","en":"Statistics, survey research and formal models reshaped the field after 1945, and the phrase came to stand for an empirical discipline rather than for learned commentary on constitutions.","cn":"1945 年之后，统计学、调查方法与形式模型重塑了这一领域，这个短语遂指一门实证学科，而非对宪法的学识性评论。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use): the earliest appearance of the exact phrase is dated only approximately, and the deeper origin of scire has no agreed answer.","cn":"来源不确定（最早用例）：这一确切短语的最早出现只能给出约略年代，scire 的更早来源也没有公认答案。"}]},"similar":{"note":{"en":"Group one holds names built on the same two words that are easily confused with the discipline; group two holds fields that study neighbouring subjects.","cn":"第一组是用同样两个词构成、容易与这门学科混淆的名称；第二组是研究邻近对象的领域。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"politics","ipa":"/ˈpɒlətɪks/","tag":"British subject name","definition":"In British universities the subject is often simply called politics; the phrase is more common in American usage.","definitionCN":"在英国大学里，这门学科常直接称为 politics；本短语在美式用法中更常见。"},{"word":"political scientist","ipa":"/pəˈlɪtɪkəl ˈsaɪəntɪst/","tag":"the person","definition":"One who practices the discipline; the field is the subject, the person is its practitioner.","definitionCN":"从事这门学科的人；本词指学科，那一词指从业者。"},{"word":"political theory","ipa":"/pəˈlɪtɪkəl ˈθɪəri/","tag":"one branch","definition":"The branch that studies ideas about the state rather than observable behaviour; it is a part of the larger field.","definitionCN":"研究关于国家的观念、而非可观察行为的那个分支；它是更大领域的一部分。"},{"word":"political economy","ipa":"/pəˈlɪtɪkəl ɪˈkɒnəmi/","tag":"markets and power","definition":"The study of how politics and economic life shape each other, a neighbouring field with its own history.","definitionCN":"研究政治与经济生活如何互相塑造的学问，是一个有自身历史的邻近领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"public administration","ipa":"/ˌpʌblɪk ˌædmɪnɪˈstreɪʃən/","tag":"implementation","definition":"The study of how policies are carried out by agencies; it focuses on execution rather than on contest for power.","definitionCN":"研究政策如何由机构执行；关注执行，而非权力争夺。"},{"word":"government","ipa":"/ˈɡʌvənmənt/","tag":"an Oxbridge degree name","definition":"At some British universities the subject is called government; the word also names the institution being studied.","definitionCN":"在英国某些大学，这门学科名为 government；该词同时也指被研究的机构。"},{"word":"civics","ipa":"/ˈsɪvɪks/","tag":"school subject","definition":"The school subject teaching citizens how their institutions work; it is practical instruction, not research.","definitionCN":"教公民了解其制度如何运转的学校课程；属实务教育，而非研究。"},{"word":"sociology","ipa":"/ˌsəʊsiˈɒlədʒi/","tag":"society, not authority","definition":"The study of society and social relations; it overlaps with political science but does not take power as its centre.","definitionCN":"研究社会与社会关系；与政治学有重叠，但不以权力为中心。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The first word means civic, and the second came to mean organised knowledge, so the phrase claims method for the study of the state.","cn":"前一个词意为「城邦的」，后一个词后来指有组织的知识，因此这个短语是在为研究国家主张一种方法。"},{"en":"The family runs political, politics, political scientist, science, scientific and scientist.","cn":"同族词包括政治的、政治、政治学家、科学、科学的与科学家。"},{"en":"Fixed phrases show the institutional sense: a degree in political science, the department of political science.","cn":"固定搭配显示机构义：政治学学位、政治学系。"},{"en":"The phrase was coined in the nineteenth century, so it is younger than the politics it studies.","cn":"这个短语造于十九世纪，比它所研究的政治本身要年轻。"},{"en":"Its core tools are statistics, case comparison and formal models, not moral praise of constitutions.","cn":"它的核心工具是统计、案例比较与形式模型，而不是对宪法的道德赞颂。"}],"abstract":[{"en":"Picture a table of electoral systems laid side by side with a ruler across them.","cn":"想象一张把各国选举制度并排铺开的表，上面横着一把尺子。"},{"en":"Picture a meeting room where the same chart is redrawn every year with new numbers.","cn":"想象一间会议室，同一张图每年都被换上新的数字重画。"},{"en":"Picture a library shelf where every spine asks one question: who gets to decide.","cn":"想象一排书架，每本书的书脊都在问同一个问题：谁有权决定。"}]},"examples":[{"en":"Political science has grown more quantitative since the nineteen sixties.","cn":"二十世纪六十年代以来，政治学变得更为定量化。"},{"en":"She combined political science with economics to study trade voting.","cn":"她把政治学与经济学结合起来研究贸易投票。"},{"en":"The model came from political science, not from journalism.","cn":"这个模型来自政治学，而不是新闻业。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「城邦的 + 知识」——把谁说了算这件事当成一门有方法的学问 → 政治学","word":"political science"},"root":"political 出自希腊 politikos「公民的、城邦的」，源头 polis「城邦」；science 出自拉丁 scientia「知识」，源头 scire「知道」，更深来源不确定。短语成形于十九世纪。","sensesIntro":{"en":"Eight senses spread from one claim: politics can be studied like a science, and from that claim come the field, the department, the course, the method, the literature, the guild, the contrast with practice and finally the study of any group that must decide.","cn":"八个义项由同一个主张展开：政治可以像科学一样被研究；由此生出学科、系所、课程、方法、文献、学术共同体、与实务的对照，最后是对任何必须作决定的群体的研究。"},"semanticMap":{"core":{"en":"CORE IMAGE: a comparison table of electoral systems with a ruler laid across it.","cn":"核心意象：一张各国选举制度的比较表，上面横着一把尺子。"},"chain":["A CLAIM TO METHOD","THE FIELD","THE DEPARTMENT","THE DATA","THE LITERATURE","THE GUILD"],"branches":[{"senses":"01","en":"THE CLAIM: power and government are treated as objects that can be studied systematically.","cn":"主张：权力与政府被当作可以被系统研究的对象。"},{"senses":"02 · 03","en":"INSTITUTION AND LESSON: the claim takes physical form as a department and as a course in a timetable.","cn":"建制与课程：这一主张落在实体上，就成了一个系和课表上的一门课。"},{"senses":"04","en":"METHOD: the science in the name is honoured when votes are counted and claims are tested.","cn":"方法：当票被数、论断被检验时，名称里那个「科学」才被兑现。"},{"senses":"05 · 06","en":"TEXT AND GUILD: the field is also a shelf of journals and a hall of conferences.","cn":"文本与行会：这一领域同时是一排期刊，也是一座开会的会场。"},{"senses":"07 · 08","en":"KNOWING VERSUS DOING, THEN ANY GROUP: study is set against practice, and the object then widens to any deciding body.","cn":"知与行，再到任何群体：研究被放到实践对面，对象随后扩到任何作决定的群体。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek civic stem to a Latin knowledge noun, and each half has its own derivational machinery in English.","cn":"这个短语把希腊的城邦词干与拉丁的知识名词接在一起，两半在英语里各有自己的派生系统。"},"latinIntro":{"en":"Latin scientia and scire supply science, scientific, scientist and conscious; politicus supplies the civic half.","cn":"拉丁 scientia 与 scire 衍生出科学、科学的、科学家与意识到的；politicus 则提供城邦那一半。"},"items":[{"word":"polis","structure":"polis (Greek noun, 'city-state')","meaning":"city-state","meaningCN":"城邦","example":"The civic half of the phrase starts here.","exampleCN":"短语中城邦的那一半从这里开始。"},{"word":"politikos","structure":"polites + -ikos","meaning":"civic","meaningCN":"城邦的；公民的","example":"The adjective supplies the object of study.","exampleCN":"这个形容词提供研究对象。"},{"word":"scire","structure":"scire (Latin verb, 'to know')","meaning":"to know","meaningCN":"知道","example":"The root supplies the claim to knowledge.","exampleCN":"这个词根提供对知识的主张。"},{"word":"scientia","structure":"sciens + -ia (state noun)","meaning":"knowledge","meaningCN":"知识","example":"The noun first meant any settled knowledge.","exampleCN":"这个名词最初泛指任何稳定的知识。"},{"word":"science","structure":"scientia through Old French science","meaning":"organised knowledge","meaningCN":"有组织的知识","example":"The word narrowed to natural science only in the nineteenth century.","exampleCN":"这个词直到十九世纪才收窄为自然科学。"},{"word":"scientific","structure":"science + -ific (making)","meaning":"according to method","meaningCN":"符合方法的","example":"A scientific claim must survive testing.","exampleCN":"科学的论断必须经得起检验。"},{"word":"-ist","structure":"-ist (person suffix)","meaning":"one who practices","meaningCN":"从事者","example":"The suffix yields the practitioner of the field.","exampleCN":"这个后缀造出这一领域的从业者。"},{"word":"conscious","structure":"com- + scire","meaning":"knowing with oneself","meaningCN":"自知；有意识的","example":"The same root appears in words about knowing.","exampleCN":"同一词根也出现在表示「知晓」的词里。"}],"latinEntries":[{"word":"scientia","structure":"scientia, scientiae (f., first declension)","meaning":"knowledge, understanding","meaningCN":"知识；理解"},{"word":"scire","structure":"scire, scivi, scitum (verb, fourth conjugation)","meaning":"to know","meaningCN":"知道"},{"word":"politicus","structure":"politicus, politica, politicum (adjective, borrowed from Greek)","meaning":"civic, of the state","meaningCN":"城邦的；国家的"}]}},{"word":"political scientist","ipa_uk":"/pəˈlɪtɪkəl ˈsaɪəntɪst/","ipa_us":"/pəˈlɪtɪkəl ˈsaɪəntɪst/","definition_zh":"政治学家；以政治学为专业的研究者、教师或分析者","definition_en":"a person who studies government and political behaviour professionally, whether as a researcher, teacher, author or analyst","core_image":"选举夜的研究室里，几个人盯着屏幕上的选区数据，把出口民调逐项填进模型","scene":"选举夜的研究室里，几个人盯着屏幕上的选区数据，把出口民调逐项填进模型。The political scientist warned that the model missed turnout in rural districts.","sceneCN":"这里指「以数据模型研究选举的政治学者」，对应第 6 个义项：用统计手段预测选举结果的研究者；句意为这位政治学家警告说，模型漏掉了乡村选区的投票率。画面要点：夜间研究室、选区数据屏、手写记录。","pos":[{"tag":"n.","zh":"政治学家；政治学研究者（可指学者、教师、撰稿人或分析者）"}],"collocations":[{"phrase":"a leading political scientist","zh":"一流政治学家"},{"phrase":"political scientists disagree","zh":"政治学家意见不一"},{"phrase":"a political scientist by training","zh":"出身政治学专业的人"},{"phrase":"an academic political scientist","zh":"学院里的政治学家"},{"phrase":"political scientists studying turnout","zh":"研究投票率问题的政治学家"}],"forms":[{"label":"复数","form":"political scientists"},{"label":"名词（学科）","form":"political science"},{"label":"形容词（政治的）","form":"political"},{"label":"名词（科学）","form":"science"},{"label":"形容词（科学的）","form":"scientific"},{"label":"名词（科学家）","form":"scientist"}],"derivatives":[{"word":"political science","pos":"n.","zh":"政治学（这一学科）"},{"word":"scientific","pos":"adj.","zh":"科学的；按科学方法的"},{"word":"scientifically","pos":"adv.","zh":"以科学方法"},{"word":"scientist","pos":"n.","zh":"科学家"},{"word":"scientism","pos":"n.","zh":"唯科学主义（把科学方法滥用到一切领域的倾向）"}],"senses":[{"no":"01","title":"A professional researcher of politics","titleCN":"以研究政治为专业的人","definition":"a person whose job is to study how authority is won, used and limited, and to publish the results","definitionCN":"以研究权威如何被赢得、使用与限制并发表成果为职业的人","example":"The political scientist spent four years counting committee votes.","exampleCN":"这位政治学家花了四年时间清点委员会表决。","why":"the compound simply puts the practitioner suffix on the name of the field, so the person is defined by what he studies.","whyCN":"这个复合词只是把表人后缀加在学科名上，因此此人是按他研究什么来定义的。"},{"no":"02","title":"A university teacher of the subject","titleCN":"在大学讲授这一学科的人","definition":"a lecturer or professor whose working life is divided between teaching and research","definitionCN":"工作分为教学与研究两部分的讲师或教授","example":"A political scientist taught the introductory course to two hundred students.","exampleCN":"一位政治学家给两百名学生上入门课。","why":"the same title covers research and teaching because universities joined the two in one post.","whyCN":"同一个称谓同时涵盖研究与教学，因为大学把这两件事并入了同一个职位。"},{"no":"03","title":"The author of studies and textbooks","titleCN":"撰写论著与教科书的人","definition":"a person known through written work rather than through a post, cited by others in the field","definitionCN":"以著作而非职位为人所知、并被同行引用的人","example":"The textbook was written by a political scientist who had never held office.","exampleCN":"这本教科书出自一位从未担任公职的政治学家之手。","why":"a discipline circulates through text, so authorship becomes a way of being a political scientist.","whyCN":"学科靠文本流通，因此写作本身也成了一种做政治学家的方式。"},{"no":"04","title":"An analyst who comments on current events","titleCN":"就时局发表评论的分析者","definition":"a person with academic training who explains elections, coups or coalitions to a general audience","definitionCN":"受过学术训练、向普通受众解释选举、政变或联合政府的人","example":"The paper hired a political scientist to explain the coalition talks.","exampleCN":"这家报纸请了一位政治学家来解释联合组阁谈判。","why":"expertise becomes public when the press needs a quick explanation, and the academic title travels with it.","whyCN":"当媒体需要快速解释时，专业知识就进入公共视野，学术头衔也随之而来。"},{"no":"05","title":"A specialist in one country or one institution","titleCN":"某一国家或某一机构的研究专家","definition":"a researcher whose authority rests on deep knowledge of a particular political system","definitionCN":"权威建立在对某一具体政治制度的深入了解之上的研究者","example":"A political scientist of the region predicted the split years early.","exampleCN":"一位研究该地区的政治学家多年前就预言了那次分裂。","why":"the field divides by area, so the title is often completed by the name of a country or a chamber.","whyCN":"这一领域按地区分工，因此这个称谓后面常接上一个国家或一个议院的名字。"},{"no":"06","title":"A modeler or forecaster of elections","titleCN":"用模型预测选举的人","definition":"a person who builds statistical models of voting and publishes probability estimates","definitionCN":"构建投票统计模型并发布概率估计的人","example":"The political scientist warned that the model missed rural turnout.","exampleCN":"这位政治学家警告说，模型漏掉了乡村投票率。","why":"the empirical promise inside the field's name is most visible when its results are numbers that can be checked.","whyCN":"当研究结果是可核对的数字时，学科名称里那项实证承诺最为明显。"},{"no":"07","title":"An adviser to governments or parties","titleCN":"为政府或政党提供建议的人","definition":"a researcher who applies findings inside an administration, campaign or international body","definitionCN":"把研究成果用在政府、竞选团队或国际机构内部的研究者","example":"The political scientist briefed the cabinet on referendum risks.","exampleCN":"这位政治学家就公投风险向内阁作了简报。","why":"knowledge about power can be sold to those who hold it, so the title also appears inside the state.","whyCN":"关于权力的知识可以卖给掌握权力的人，因此这个称谓也会出现在国家机构内部。"},{"no":"08","title":"Abstract: one who makes power legible","titleCN":"抽象义：让权力变得可读的人","definition":"in general use, anyone who renders the workings of authority visible and comparable","definitionCN":"泛指把权威的运作方式变得可见、可比较的人","example":"In a faction fight, the political scientist is the one drawing the map.","exampleCN":"在派系争斗中，政治学家就是那个画地图的人。","why":"the abstract sense keeps only the task of description, and the university setting falls away.","whyCN":"抽象义只保留描述这项任务，大学场景则被去掉。"}],"etymology":{"intro":{"en":"Political scientist is an English compound of the field's name, itself a nineteenth-century pairing of a Greek civic adjective with a Latin noun for knowledge. Dates are approximate.","cn":"political scientist 是由学科名构成的英语复合词，而学科名本身是十九世纪把希腊的城邦形容词与拉丁的知识名词配成的。年代均为约数。"},"items":[{"era":"GREEK POLIS","en":"Polis meant a city-state and its citizen body; its deeper origin is not established, and the pre-Greek suggestion remains a hypothesis.","cn":"polis 指城邦及其公民总体；它更深的来源未得到证明，前希腊语来源的说法仍属假说。"},{"era":"LATIN SCIENTIA","en":"Scientia meant 'knowledge', from scire 'to know'; the further origin of scire is uncertain and the link sometimes drawn to scindere 'to split' is not a demonstrated derivation.","cn":"scientia 意为「知识」，出自 scire「知道」；scire 的更早来源不确定，有人把它与 scindere「切开」相联系，但并非已证实的派生。"},{"era":"ENGLISH SCIENCE","en":"Science entered English in the fourteenth century meaning knowledge or skill in general, and only in the nineteenth century did it come to mean the natural sciences in particular.","cn":"science 在十四世纪进入英语，泛指知识或技艺，直到十九世纪才专指自然科学。"},{"era":"SCIENTIST","en":"The word scientist is generally attributed to William Whewell, who proposed it in 1834 to match artist; before that, those who studied nature were called natural philosophers.","cn":"scientist 一词一般认为是威廉·休厄尔在 1834 年为与 artist 对应而提出的；在此之前，研究自然的人被称为自然哲学家。"},{"era":"COMPOUND TITLE","en":"Political scientist appeared as the discipline acquired chairs and journals in the late nineteenth and early twentieth centuries, modelled on the older titles of natural science.","cn":"随着这门学科在十九世纪末、二十世纪初设立教席与期刊，political scientist 这一称谓按自然科学既有的头衔模式出现。"}]},"similar":{"note":{"en":"Group one holds words built from the same parts that are easily confused with the person; group two holds neighbouring professions that also explain politics.","cn":"第一组是用同样构件构成、容易与这个表人名词混淆的词；第二组是同样解释政治现象的邻近职业。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"political science","ipa":"/pəˈlɪtɪkəl ˈsaɪəns/","tag":"the field","definition":"The discipline itself; the person holds a post or a degree in it, but the two are not interchangeable.","definitionCN":"指学科本身；此人可能在其中任职或取得学位，但两者不能互换。"},{"word":"scientist","ipa":"/ˈsaɪəntɪst/","tag":"without the qualifier","definition":"By itself the word usually means a natural scientist; the qualifier is what points to the social field.","definitionCN":"单独使用时通常指自然科学家；正是前面的限定语才把它指向社会领域。"},{"word":"politician","ipa":"/ˌpɒləˈtɪʃən/","tag":"practice, not study","definition":"A person who holds or seeks office; a political scientist studies such people and may never run for anything.","definitionCN":"担任或谋求公职的人；政治学家研究这类人，自己可能从不参选。"},{"word":"scientific","ipa":"/ˌsaɪənˈtɪfɪk/","tag":"the adjective","definition":"An adjective describing method; it can modify political science but does not name a person.","definitionCN":"描述方法的形容词；可修饰政治学，但不能指人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"psephologist","ipa":"/sɪˈfɒlədʒɪst/","tag":"elections only","definition":"A specialist in the study of voting and election statistics; the focus is narrower than the whole discipline.","definitionCN":"专门研究投票与选举统计的人；范围比整个学科窄。"},{"word":"pollster","ipa":"/ˈpɒlstə/","tag":"survey work","definition":"A person who conducts opinion surveys, often commercially; a political scientist may use polls without being one.","definitionCN":"从事民意调查的人，常为商业机构工作；政治学家可能使用民调，但本身未必是民调从业者。"},{"word":"policy analyst","ipa":"/ˈpɒləsi əˈnælɪst/","tag":"recommendations","definition":"A person who evaluates specific programmes and advises on choices; the work is applied rather than academic.","definitionCN":"评估具体方案并就选择提出建议的人；工作偏应用而非学术。"},{"word":"commentator","ipa":"/kəˈmentətə/","tag":"public voice","definition":"A person who explains events to an audience; training may be in journalism or law rather than in political science.","definitionCN":"向受众解释时事的人；其训练可能来自新闻或法律，而非政治学。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The field name plus the practitioner suffix: a person defined by the subject studied.","cn":"学科名加表人后缀：按所研究的学科来定义的人。"},{"en":"The first half is a Greek civic adjective, the second half rests on a Latin verb meaning to know.","cn":"前半是希腊的城邦形容词，后半立在拉丁语中表示「知道」的动词上。"},{"en":"Fixed phrases show the roles: a leading political scientist, a political scientist by training.","cn":"固定搭配显示各种角色：一流政治学家、出身政治学专业的人。"},{"en":"The near pair to keep apart is politician, who practices, and political scientist, who studies.","cn":"要分清的一对近邻是实践政治的从政者与研究政治的政治学家。"},{"en":"Many political scientists never hold office, and many officeholders never study the subject.","cn":"许多政治学家从不担任公职，许多公职人员也从不研究这门学科。"}],"abstract":[{"en":"Picture a person drawing a map of a building they have never entered.","cn":"想象一个人画着一栋自己从未进去过的建筑的地图。"},{"en":"Picture a night desk where numbers from distant districts arrive one by one.","cn":"想象一张夜班桌，远处各区的数字一个接一个送来。"},{"en":"Picture a hand pointing at a chart and saying: this is how the decision was actually made.","cn":"想象一只手点着图表说：决定实际上是这样作出的。"}]},"examples":[{"en":"Political scientists have argued for decades about turnout.","cn":"政治学家就投票率问题争论了几十年。"},{"en":"A political scientist by training, she now runs an election unit.","cn":"她出身政治学专业，现在主持一个选举研究部门。"},{"en":"The commission included two political scientists and one judge.","cn":"该委员会包括两位政治学家和一位法官。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「政治学 + 人」——把谁说了算当成专业来研究的人 → 政治学家","word":"political scientist"},"root":"political 出自希腊 politikos「公民的、城邦的」，源头 polis「城邦」；scientist 由拉丁 scientia「知识」加表人后缀构成，该词一般认为是 1834 年由休厄尔提出。","sensesIntro":{"en":"Eight senses follow one qualification: a person certified to study power can be a researcher, a teacher, an author, a commentator, an area specialist, a forecaster, an adviser, and finally anyone who makes authority visible.","cn":"八个义项沿同一种资格展开：被认定有资格研究权力的人，可以是研究者、教师、著者、评论者、地区专家、预测者、顾问，最后是任何让权威变得可见的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a night desk where district numbers are entered into a model.","cn":"核心意象：一张夜班桌，各区的数字被逐项输进模型。"},"chain":["STUDY POWER","PUBLISH FINDINGS","TEACH THE SUBJECT","EXPLAIN IN PUBLIC","ADVISE THE STATE","MAKE POWER LEGIBLE"],"branches":[{"senses":"01","en":"RESEARCH: the base sense, a person whose trade is producing knowledge about authority.","cn":"研究：基础义，即以生产关于权威的知识为业的人。"},{"senses":"02 · 03","en":"TEACH AND WRITE: the same knowledge is handed on in a lecture hall or fixed on a page.","cn":"教与写：同一套知识，或在讲堂里传给他人，或在纸页上固定下来。"},{"senses":"04 · 05","en":"PUBLIC AND DEEP: the general explainer and the country specialist are two ways of being useful.","cn":"通俗与专深：面向大众的解释者与钻研一国的专家，是两种有用的方式。"},{"senses":"06 · 07","en":"PREDICT AND ADVISE: numbers are produced ahead of events and then handed to those who decide.","cn":"预测与建议：数字在事件之前造出，随后交到作决定的人手里。"},{"senses":"08","en":"LEGIBILITY: strip the institution away and the task is to make power readable.","cn":"可读性：把机构抽走，剩下的任务就是让权力变得可读。"}]},"affixes":{"intro":{"en":"The compound stacks two learned words, each with its own suffix, so the title can be read from the end backwards.","cn":"这个复合词把两个学术词叠在一起，各带自己的后缀，因此这个称谓可以从末尾往前读。"},"latinIntro":{"en":"Latin scientia and scire supply science, scientific and scientist; politicus supplies the civic qualifier.","cn":"拉丁 scientia 与 scire 提供科学、科学的与科学家；politicus 提供城邦这一限定语。"},"items":[{"word":"polis","structure":"polis (Greek noun, 'city-state')","meaning":"city-state","meaningCN":"城邦","example":"The qualifier starts from the city.","exampleCN":"这个限定语从城邦开始。"},{"word":"politikos","structure":"polites + -ikos","meaning":"civic","meaningCN":"城邦的","example":"The adjective names the object of study.","exampleCN":"这个形容词指出研究对象。"},{"word":"scire","structure":"scire (Latin verb, 'to know')","meaning":"to know","meaningCN":"知道","example":"The base verb carries the claim to knowledge.","exampleCN":"这个词根承载对知识的主张。"},{"word":"scientia","structure":"sciens + -ia","meaning":"knowledge","meaningCN":"知识","example":"The noun names what the person is supposed to produce.","exampleCN":"这个名词指出此人应当生产的东西。"},{"word":"-ist","structure":"-ist (person suffix)","meaning":"one who practices","meaningCN":"从事者","example":"The suffix marks the practitioner.","exampleCN":"这个后缀标记从业者。"},{"word":"scientist","structure":"science + -ist","meaning":"one who studies nature","meaningCN":"研究自然的人","example":"The word was proposed in the eighteen thirties.","exampleCN":"这个词是在十九世纪三十年代提出的。"},{"word":"political science","structure":"political + science","meaning":"the study of the state","meaningCN":"对国家与政治的研究","example":"The field gave the title its first half.","exampleCN":"这一学科给这个称谓提供了前半部分。"},{"word":"scientific","structure":"science + -ific","meaning":"methodical","meaningCN":"有方法的","example":"A scientific claim can be tested.","exampleCN":"科学的论断可以被检验。"},{"word":"scientism","structure":"science + -ism","meaning":"overreach of method","meaningCN":"方法的越界使用","example":"Scientism applies the method where it does not fit.","exampleCN":"唯科学主义把方法用在并不适合的地方。"}],"latinEntries":[{"word":"scientia","structure":"scientia, scientiae (f., first declension)","meaning":"knowledge","meaningCN":"知识"},{"word":"scire","structure":"scire, scivi, scitum (verb, fourth conjugation)","meaning":"to know","meaningCN":"知道"},{"word":"politicus","structure":"politicus, politica, politicum (adjective, borrowed from Greek)","meaning":"civic, of the state","meaningCN":"城邦的；国家的"}]}},{"word":"governmental","ipa_uk":"/ˌɡʌvənˈmentəl/","ipa_us":"/ˌɡʌvərnˈmentəl/","definition_zh":"政府的；政府性质的；由政府作出的；与政府层级或政府行为方式有关的","definition_en":"relating to a government as an institution, or characteristic of the way governments act","core_image":"办事大厅里，窗口前的人递上表格，工作人员逐份盖章，墙上贴着刚换的新规","scene":"办事大厅里，窗口前的人递上表格，工作人员逐份盖章，墙上贴着刚换的新规。The new rule came from a governmental body, not from the court.","sceneCN":"这里指「由政府机构作出的」，对应第 2 个义项：属于政府机关这一类的；句意为这条新规出自一个政府机构，而不是法院。画面要点：办事窗口、成叠表格、墙上的规章。","pos":[{"tag":"adj.","zh":"政府的；与政府机构有关的"},{"tag":"adj.","zh":"政府式的；带有官僚作风的（含贬义时）"}],"collocations":[{"phrase":"governmental authority","zh":"政府权力机关"},{"phrase":"governmental body","zh":"政府机构"},{"phrase":"governmental policy","zh":"政府政策"},{"phrase":"governmental regulation","zh":"政府规章"},{"phrase":"governmental funding","zh":"政府拨款"},{"phrase":"at the governmental level","zh":"在政府层面"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more governmental"},{"label":"最高级（更多用 most 构成）","form":"most governmental"},{"label":"名词（政府）","form":"government"},{"label":"动词（治理）","form":"govern"},{"label":"名词（治理者；州长）","form":"governor"},{"label":"名词（治理方式）","form":"governance"}],"derivatives":[{"word":"government","pos":"n.","zh":"政府；治理"},{"word":"govern","pos":"v.","zh":"治理；支配"},{"word":"governor","pos":"n.","zh":"州长；总督；理事"},{"word":"governance","pos":"n.","zh":"治理方式；治理结构"},{"word":"gubernatorial","pos":"adj.","zh":"州长的；与州长职位有关的"}],"senses":[{"no":"01","title":"Relating to government as an institution","titleCN":"与作为机构的政府有关","definition":"concerned with the bodies that hold public authority in a state","definitionCN":"涉及在一国中掌握公共权威的那些机构","example":"The report described the governmental structure of the new federation.","exampleCN":"这份报告描述了新联邦的政府结构。","why":"the adjective is simply the noun for government plus the usual relational ending, so it marks belonging to the institution.","whyCN":"这个形容词只是「政府」这一名词加常见的关联词尾，因此它标记的是归属于该机构。"},{"no":"02","title":"Describing an official body or agency","titleCN":"形容属于政府机关这一类","definition":"used of an organisation that acts under state authority rather than as a private party","definitionCN":"用于按国家权威、而非以私人身份行事的组织","example":"The new rule came from a governmental body, not from the court.","exampleCN":"这条新规出自一个政府机构，而不是法院。","why":"organisations need to be sorted by whose authority they act under, and the adjective marks the public side of that line.","whyCN":"组织需要按「依谁的权威行事」来分类，这个形容词标记的就是这条界线的公家一侧。"},{"no":"03","title":"Issued as policy or regulation","titleCN":"由政府作为政策或规章发布","definition":"describing rules, standards or programmes that carry the force of state decision","definitionCN":"形容具有国家决定效力的规则、标准或计划","example":"Governmental regulation of the port slowed every shipment.","exampleCN":"政府对港口的规章让每一批货都慢了下来。","why":"an institution acts through documents, so the adjective attaches to the instruments it issues.","whyCN":"机构是通过文件行动的，因此这个形容词也附着在它所发布的文书上。"},{"no":"04","title":"Funded or owned by the state","titleCN":"由国家出资或所有的","definition":"describing money, property or staff supplied from public funds","definitionCN":"形容由公共资金提供的款项、财产或人员","example":"The clinic survived on governmental funding for a decade.","exampleCN":"这家诊所靠政府拨款撑了十年。","why":"once government is an institution, its purse becomes a source, and the adjective names that source.","whyCN":"政府一旦是机构，其钱袋就成了一个来源，这个形容词便用来指那个来源。"},{"no":"05","title":"Belonging to a level of government","titleCN":"属于某一级政府","definition":"used to place a decision at the local, regional or national rung of the system","definitionCN":"用于把某项决定放在地方、区域或国家某一级上","example":"The dispute had to be settled at the governmental level, not in a workshop.","exampleCN":"这场争端必须在政府层面解决，而不能在车间里解决。","why":"states are layered, so the adjective works with level words to say which layer is speaking.","whyCN":"国家是分层的，因此这个形容词与「层级」一类词连用，说明是哪一层在说话。"},{"no":"06","title":"Behaving in a bureaucratic way","titleCN":"带有官僚作风的","definition":"describing slow, form-bound behaviour that resembles the worst habits of public offices","definitionCN":"形容缓慢、拘于表格、类似公署最坏习气的行为","example":"The approval process was painfully governmental.","exampleCN":"这套审批流程慢得像政府办事一样。","why":"a word for belonging to an institution can also criticise the manner of that institution, and the tone turns negative.","whyCN":"一个表示归属机构的词，也能用来批评该机构的行事方式，此时语气转为贬义。"},{"no":"07","title":"Derived from state authority","titleCN":"权力来自政府的","definition":"describing a power, right or appointment whose force comes from the state rather than from contract","definitionCN":"形容某项权力、权利或任命的力量来自国家，而非来自合同","example":"A governmental power of entry does not need the owner's consent.","exampleCN":"政府的进入权不需要业主同意。","why":"authority has sources, and this adjective marks the one that traces back to the state rather than to agreement.","whyCN":"权威有其来源，这个形容词标记的是可追溯到国家、而非追溯到约定的那一种。"},{"no":"08","title":"Abstract: pertaining to steering a community","titleCN":"抽象义：关乎如何驾驭一个共同体","definition":"in general use, concerning the direction of any collective body, not only a state","definitionCN":"泛指关乎任何集体如何被引导，而不限于国家","example":"A university has its own governmental problems.","exampleCN":"一所大学也有它自己的治理难题。","why":"the base verb means to steer, so the adjective can be read as 'having to do with steering', at any scale.","whyCN":"基础动词意为「掌舵」，因此这个形容词可读作「与掌舵有关的」，在任何规模上都成立。"}],"etymology":{"intro":{"en":"Governmental is government plus a relational adjective ending, and government goes back through French to a Latin verb borrowed from Greek for steering a ship. Dates are approximate.","cn":"governmental 是 government 加关系形容词词尾构成，而 government 经法语上溯到一个借自希腊语、本义为「掌舵」的拉丁动词。年代均为约数。"},"items":[{"era":"GREEK KYBERNAN","en":"Kybernan meant 'to steer, pilot a ship', and kybernetes meant the steersman; the deeper origin of the Greek verb is not established, so any older root offered for it is a reconstruction.","cn":"kybernan 意为「掌舵、驾驶船只」，kybernetes 指舵手；这个希腊动词更深的来源未得到证明，凡为其提出的更早词根均属重构形式。"},{"era":"LATIN GUBERNARE","en":"Latin borrowed the Greek verb as gubernare 'to steer, pilot, direct', and from it came gubernator 'steersman' and gubernaculum 'rudder'.","cn":"拉丁语把这个希腊动词借作 gubernare「掌舵、驾驶、指引」，由它产生 gubernator「舵手」与 gubernaculum「船舵」。"},{"era":"OLD FRENCH GOVERNER","en":"Old French governer carried the verb into English in the fourteenth century, where govern first meant to steer or guide and soon also to rule.","cn":"古法语 governer 在十四世纪把这个动词带入英语，govern 最初指掌舵、引导，随后也指统治。"},{"era":"GOVERNMENT","en":"Government was formed in the fourteenth century from govern plus the noun ending -ment; it first named the act of governing and later the body that governs.","cn":"government 于十四世纪由 govern 加构成名词的词尾构成；最初指治理这一行为，后来指治理的机构。"},{"era":"GOVERNMENTAL","en":"The adjective governmental, formed with the relational ending -al, spread in the nineteenth century as administrative writing needed a word for what belongs to government rather than to the governed.","cn":"形容词 governmental 由表示「与……相关」的关系词尾构成，在十九世纪随行政文书的增长而普及，因为那时需要一个词来指属于政府、而非属于被治理者的事物。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Greek root of kybernan is disputed, and the earliest use of the English adjective is dated only approximately.","cn":"来源不确定（更深词源）：kybernan 在希腊语之前的词根存在争议，这个英语形容词的最早用例只能给出约略年代。"}]},"similar":{"note":{"en":"Group one holds forms from the same steering stem that are easily confused with this adjective; group two holds adjectives that also describe public authority.","cn":"第一组是同出「掌舵」词干、容易与本词混淆的形式；第二组是同样描述公共权威的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"government","ipa":"/ˈɡʌvənmənt/","tag":"the noun","definition":"The institution or the act of governing; the adjective describes what belongs to it.","definitionCN":"指机构或治理行为；本词形容词描述属于它的事物。"},{"word":"governance","ipa":"/ˈɡʌvənəns/","tag":"the manner","definition":"The way decisions are made and supervised, often in firms and agencies; it names a process, not a belonging.","definitionCN":"指决定如何作出与监督的方式，常用于企业与机构；它指过程，而非归属。"},{"word":"gubernatorial","ipa":"/ˌɡuːbənəˈtɔːriəl/","tag":"of a governor","definition":"Relating to the office of a state governor; the stem is the same but the reference is to one post, not to government as a whole.","definitionCN":"与州长职位有关；词干相同，但所指是一个职位，而非整个政府。"},{"word":"governing","ipa":"/ˈɡʌvənɪŋ/","tag":"currently ruling","definition":"Describing the body or party that is in power now, as a governing party; it marks present activity, not institutional type.","definitionCN":"形容目前执政的机构或政党，如执政党；它标记当下的活动，而非机构类型。"}]},{"heading":"NEAR MEANING","entries":[{"word":"official","ipa":"/əˈfɪʃəl/","tag":"authorised, not necessarily state","definition":"Approved by a body with authority, which may be a club or a federation; governmental always points to the state.","definitionCN":"经有权威的机构认可，该机构可能是社团或联合会；而 governmental 总是指向国家。"},{"word":"state-run","ipa":"/ˈsteɪt rʌn/","tag":"operated directly","definition":"Operated by the state itself, as a state-run railway; governmental can describe policy without direct operation.","definitionCN":"由国家直接运营，如国营铁路；governmental 可仅描述政策，不涉及直接运营。"},{"word":"public-sector","ipa":"/ˌpʌblɪk ˈsektə/","tag":"the whole economy of the state","definition":"Relating to the part of the economy owned or paid for by the state; it is an economic category rather than a legal one.","definitionCN":"与由国家所有或支付的那部分经济有关；属经济范畴，而非法律范畴。"},{"word":"administrative","ipa":"/ədˈmɪnɪstrətɪv/","tag":"management, not authority","definition":"Relating to the running of an organisation; an administrative decision may be internal and carry no public authority.","definitionCN":"与机构的日常管理有关；行政决定可能是内部的，不具公共权威。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base verb meant to steer a ship, so governing is steering and the adjective marks what belongs to the steersman.","cn":"基础动词意为掌舵，所以治理就是掌舵，而这个形容词标记属于舵手的事物。"},{"en":"The family runs govern, government, governor, governance and gubernatorial.","cn":"同族词包括治理、政府、州长、治理方式与州长的。"},{"en":"Fixed phrases show the main uses: governmental body, governmental policy, governmental funding.","cn":"固定搭配显示主要用法：政府机构、政府政策、政府拨款。"},{"en":"The word entered English through French, and its relative gubernatorial came more directly from Latin.","cn":"这个词经法语进入英语，而同族的「州长的」则更直接地来自拉丁语。"},{"en":"Its opposite side is the governed, those on whom authority is exercised.","cn":"它的对面是被治理者，即权威施于其上的那些人。"}],"abstract":[{"en":"Picture a hand on a rudder while a whole crew waits for the course to be set.","cn":"想象一只手扶着舵，整船人等着航线被定下。"},{"en":"Picture a counter with a rubber stamp, and a queue that moves one form at a time.","cn":"想象一个放着印章的柜台，队伍一次只前进一份表格。"},{"en":"Picture a building with many floors, each claiming the right to decide the same question.","cn":"想象一栋很多层的楼，每层都声称有权决定同一个问题。"}]},"examples":[{"en":"The agency was created by governmental decision, not by treaty.","cn":"这个机构是依政府的决定设立的，而不是依条约。"},{"en":"Governmental support kept the archive open through the winter.","cn":"政府的支持让档案馆熬过了整个冬天。"},{"en":"The review found the response slow and overly governmental.","cn":"评估认为这次应对迟缓，官僚气过重。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「掌舵 + 名词 + 形容词」——凡属于掌舵那一套机构的事 → 政府的","word":"governmental"},"root":"governmental 由 government 加关系形容词词尾构成；government 出自 govern 加名词词尾，govern 经古法语出自拉丁 gubernare「掌舵、指引」，而该拉丁动词借自希腊 kybernan「掌舵」，更深来源不确定。","sensesIntro":{"en":"Eight senses spread from one institution: what belongs to government, what counts as a public body, what it issues, what it funds, which layer acts, how it behaves, where its authority comes from, and finally any steering of a group.","cn":"八个义项由一个机构向外铺开：属于政府的事物、算作公共机构的组织、它发布的文书、它出的钱、由哪一层出面、它的行事作风、它权威的来源，最后是任何对群体的驾驭。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stamp coming down on a form at a public counter.","cn":"核心意象：公章在办事窗口的一份表格上落下去。"},"chain":["THE STEERSMAN","THE INSTITUTION","THE PUBLIC BODY","THE INSTRUMENTS","THE PURSE","STEERING A GROUP"],"branches":[{"senses":"01","en":"INSTITUTION: the adjective first marks what belongs to the body that holds public authority.","cn":"机构：这个形容词首先标记属于掌握公共权威的那个机构的事物。"},{"senses":"02 · 03","en":"BODY AND INSTRUMENT: an agency is sorted as public, and the rules it issues carry that same mark.","cn":"机关与文书：一个机构被划为公家，它发布的规则也带着同一个印记。"},{"senses":"04 · 05","en":"MONEY AND LAYER: the state pays for things and also speaks at a particular rung of the system.","cn":"钱与层级：国家既出钱办事，也在体系的某一级上说话。"},{"senses":"06 · 07","en":"MANNER AND SOURCE: the same adjective can mock bureaucratic slowness or trace a power back to the state.","cn":"作风与来源：同一个形容词既能嘲讽官僚式的迟缓，也能把某项权力追溯至国家。"},{"senses":"08","en":"STEERING: the ship image returns, and the adjective applies to any group being guided.","cn":"掌舵：船的画面回来了，这个形容词可用于任何被引导的群体。"}]},"affixes":{"intro":{"en":"Governmental is a noun of action plus a relational ending, and the noun rests on a verb that came into Latin from Greek seamanship.","cn":"governmental 是行为名词加关系词尾，而这个名词立在一个由希腊航海用语进入拉丁语的动词上。"},"latinIntro":{"en":"Latin gubernare and gubernator supply govern, governor, government and gubernatorial, all through the image of a rudder.","cn":"拉丁 gubernare 与 gubernator 衍生出治理、州长、政府与州长的，全都围绕船舵这一意象。"},"items":[{"word":"kybernan","structure":"kybernan (Greek verb, 'to steer')","meaning":"to steer a ship","meaningCN":"驾驶船只","example":"The Greek verb supplies the image of a hand on the rudder.","exampleCN":"这个希腊动词提供「手握船舵」的意象。"},{"word":"gubernare","structure":"gubernare (Latin verb, first conjugation, from Greek)","meaning":"to steer, direct, govern","meaningCN":"掌舵；指引；治理","example":"The Latin verb widened from ships to states.","exampleCN":"这个拉丁动词从船只扩用到国家。"},{"word":"gubernator","structure":"gubernare + -tor (agent noun)","meaning":"steersman","meaningCN":"舵手","example":"The agent noun later named a provincial ruler.","exampleCN":"这个表人名词后来指一方长官。"},{"word":"govern","structure":"Old French governer, from Latin gubernare","meaning":"to rule, guide","meaningCN":"统治；引导","example":"To govern is first to set a course.","exampleCN":"治理首先是定下航线。"},{"word":"-ment","structure":"-ment (noun suffix of action or result)","meaning":"the act or result of","meaningCN":"行为或其结果","example":"The ending first named the act of steering.","exampleCN":"这个词尾最初指掌舵这一行为。"},{"word":"government","structure":"govern + -ment","meaning":"the act, then the body","meaningCN":"治理行为，后指机构","example":"The noun moved from action to institution.","exampleCN":"这个名词从行为转指机构。"},{"word":"-al","structure":"-al (relational adjective suffix)","meaning":"belonging to","meaningCN":"属于……的","example":"The ending marks what belongs to the institution.","exampleCN":"这个词尾标记属于该机构的事物。"},{"word":"governor","structure":"govern + -or (agent noun)","meaning":"one who governs a unit","meaningCN":"治理某一单位的人","example":"The governor of a province answers to the centre.","exampleCN":"一省的长官向中央负责。"},{"word":"governance","structure":"govern + -ance (state or process)","meaning":"the manner of governing","meaningCN":"治理的方式","example":"Good governance is measured by how decisions are reviewed.","exampleCN":"良好治理要看决定如何被复核。"}],"latinEntries":[{"word":"gubernare","structure":"gubernare, gubernavi, gubernatum (verb, first conjugation; from Greek)","meaning":"to steer, direct","meaningCN":"掌舵；指引"},{"word":"gubernator","structure":"gubernator, gubernatoris (m., third declension)","meaning":"steersman, governor","meaningCN":"舵手；长官"},{"word":"gubernaculum","structure":"gubernaculum, gubernaculi (n., second declension)","meaning":"rudder","meaningCN":"船舵"},{"word":"gubernatio","structure":"gubernatio, gubernationis (f., third declension)","meaning":"a steering, direction","meaningCN":"掌舵；指引"}]}},{"word":"governor","ipa_uk":"/ˈɡʌvənə/","ipa_us":"/ˈɡʌvərnər/","definition_zh":"州长；总督；理事；董事；（中央银行的）行长；（英）监狱长；调速器","definition_en":"the chief executive of a state or province, a member of a governing board, the head of a central bank or prison, or a device that regulates speed","core_image":"州议会大厅的台阶上，新任者手按文件宣誓，身后站着一排幕僚","scene":"州议会大厅的台阶上，新任者手按文件宣誓，身后站着一排幕僚。The governor signed the budget an hour after the assembly passed it.","sceneCN":"这里指「美国的州长」，对应第 1 个义项：一州最高行政长官；句意为议会在通过预算一小时后，州长就签署了它。画面要点：议会台阶、宣誓文件、幕僚队列。","pos":[{"tag":"n.","zh":"州长；省长；（殖民地或属地的）总督"},{"tag":"n.","zh":"理事；董事（董事会、理事会成员）"},{"tag":"n.","zh":"行长；监狱长；（机械）调速器"}],"collocations":[{"phrase":"state governor","zh":"州长"},{"phrase":"governor-general","zh":"总督"},{"phrase":"the governor of the central bank","zh":"中央银行行长"},{"phrase":"board of governors","zh":"理事会；董事会"},{"phrase":"prison governor","zh":"监狱长（英式）"},{"phrase":"deputy governor","zh":"副州长；副行长"}],"forms":[{"label":"复数","form":"governors"},{"label":"动词（治理）","form":"govern"},{"label":"名词（政府）","form":"government"},{"label":"名词（治理方式）","form":"governance"},{"label":"名词（州长职位或任期）","form":"governorship"},{"label":"形容词（州长的）","form":"gubernatorial"}],"derivatives":[{"word":"governorship","pos":"n.","zh":"州长（或总督、理事）的职位与任期"},{"word":"gubernatorial","pos":"adj.","zh":"州长的；与州长职位有关的"},{"word":"government","pos":"n.","zh":"政府；治理"},{"word":"governance","pos":"n.","zh":"治理方式；治理结构"},{"word":"govern","pos":"v.","zh":"治理；支配"}],"senses":[{"no":"01","title":"The chief executive of a state","titleCN":"一州的最高行政长官","definition":"the elected head of a state or province, with authority over its budget and administration","definitionCN":"经选举产生的一州或一省首长，掌管其预算与行政","example":"The governor signed the budget an hour after the assembly passed it.","exampleCN":"议会在通过预算一小时后，州长就签署了它。","why":"the Latin base means steersman, and the head of a state is pictured as the one holding the rudder.","whyCN":"拉丁词根本义是舵手，一州之首被想成握着舵的那个人。"},{"no":"02","title":"A colonial or viceregal head","titleCN":"殖民地或属地的总督","definition":"the officer appointed to represent the crown or the central state in a dependency","definitionCN":"被任命在属地代表王室或中央国家的官员","example":"The governor-general read the proclamation from the steps.","exampleCN":"总督在台阶上宣读了公告。","why":"when authority is held at a distance, the steersman is sent out from the centre, and the title follows the post.","whyCN":"当权威在远方行使时，舵手由中央派出去，这个称谓便跟着职位走。"},{"no":"03","title":"A member of a governing board","titleCN":"理事会或董事会的成员","definition":"one of the people who oversee an institution such as a school, hospital or foundation","definitionCN":"监督学校、医院或基金会等机构运转的人之一","example":"The school governors met to review the budget.","exampleCN":"校董会开会审议预算。","why":"oversight is steering without daily handling, so the same title serves the board that sets a course.","whyCN":"监督是不亲自日常操作的掌舵，因此同一个称谓也用于定航线的理事会。"},{"no":"04","title":"The head of a central bank","titleCN":"中央银行行长","definition":"the officer responsible for monetary policy and the standing of a currency","definitionCN":"负责货币政策与货币地位的官员","example":"The governor raised rates without calling a vote.","exampleCN":"这位行长没有提请表决就提高了利率。","why":"money is steered by one hand in most systems, so the old steering title was kept for the bank's chief.","whyCN":"在多数制度里，货币由一只手来掌舵，于是这个古老的掌舵称谓被留给央行首长。"},{"no":"05","title":"The head of a prison","titleCN":"监狱长（英式用法）","definition":"the officer in charge of a prison establishment in British usage","definitionCN":"英式用法中主管一所监狱的官员","example":"The prison governor ordered a review of the wing.","exampleCN":"监狱长下令对那栋监区进行复查。","why":"an institution with walls is also steered by one responsible head, and the title came along with the post.","whyCN":"有围墙的机构同样由一位负责人掌舵，这个称谓也随职位而来。"},{"no":"06","title":"A device that regulates speed","titleCN":"调速器（机械装置）","definition":"a mechanism that keeps an engine or machine at a steady rate by opening and closing a valve","definitionCN":"通过开闭阀门使发动机或机器保持稳定转速的装置","example":"The engine governor failed and the mill raced.","exampleCN":"发动机调速器失灵，磨坊的转速失控。","why":"the metaphor became metal: what holds a machine to one pace does the work of a steersman.","whyCN":"比喻变成了实物：让机器保持一种节奏的东西，做的正是舵手的工作。"},{"no":"07","title":"A commander of a fortress","titleCN":"历史义：要塞或卫戍部队的指挥官","definition":"in older usage, the officer holding a castle, garrison or town for a sovereign","definitionCN":"较早用法中代表君主据守城堡、卫戍部队或城镇的军官","example":"The governor of the castle refused to surrender the keys.","exampleCN":"要塞指挥官拒绝交出钥匙。","why":"a garrison is a small state under one hand, and the title covered military command before it covered civil office.","whyCN":"卫戍区是一人之下的小型国家，这个称谓先涵盖军事指挥，后才涵盖民政。"},{"no":"08","title":"Abstract: one who steers a body","titleCN":"抽象义：为一个集体掌舵的人","definition":"in general use, whoever sets the course for an organisation, whether elected or appointed","definitionCN":"泛指为任何组织定下方向的人，无论经选举还是受任命","example":"Every committee needs a governor, even if the title is unofficial.","exampleCN":"每个委员会都需要一个掌舵者，哪怕这个称谓并不正式。","why":"the abstract sense keeps only the rudder and drops the state, the board and the machine.","whyCN":"抽象义只留下船舵，国家、理事会与机器都被去掉。"}],"etymology":{"intro":{"en":"Governor goes back through Old French to a Latin agent noun built on a verb borrowed from Greek for steering a ship. Dates are approximate.","cn":"governor 经古法语上溯到一个拉丁表人名词，该名词立在一个借自希腊语、本义为「掌舵」的动词上。年代均为约数。"},"items":[{"era":"GREEK KYBERNAN","en":"Kybernan meant 'to steer, pilot', and kybernetes meant steersman; the deeper origin of the Greek verb is not established, so any older root proposed for it is a reconstruction.","cn":"kybernan 意为「掌舵、驾驶」，kybernetes 指舵手；这个希腊动词更深的来源未得到证明，凡为其提出的更早词根均属重构形式。"},{"era":"LATIN GUBERNARE","en":"Latin borrowed it as gubernare 'to steer, direct', and the agent noun gubernator named the man at the rudder.","cn":"拉丁语把它借作 gubernare「掌舵、指引」，表人名词 gubernator 指站在舵前的人。"},{"era":"ROMAN OFFICE","en":"Gubernator was also used for a provincial administrator, so the shift from ship to province happened inside Latin itself.","cn":"gubernator 也用于指行省管理者，可见从船到行省的转移在拉丁语内部就已发生。"},{"era":"OLD FRENCH GOVERNEOR","en":"Old French governeor carried the title into English in the fourteenth century, first for a military commander and soon for a civil ruler.","cn":"古法语 governeor 在十四世纪把这个称谓带入英语，先指军事指挥官，不久也指民政统治者。"},{"era":"MODERN OFFICES","en":"As states, banks, schools and prisons each acquired a responsible head, the one title spread across all of them, and the mechanical sense followed in the eighteenth century.","cn":"随着州、银行、学校与监狱各自有了负责的首长，这同一个称谓扩及全部，机械义则在十八世纪出现。"}]},"similar":{"note":{"en":"Group one holds words from the same steering family that are easily confused with the officeholder; group two holds titles for heads of other bodies.","cn":"第一组是同出「掌舵」词族、容易与这个职位混淆的词；第二组是其他机构首长的称谓。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"government","ipa":"/ˈɡʌvənmənt/","tag":"the institution","definition":"The body that governs a state; a governor is one office inside it, not the whole of it.","definitionCN":"治理国家的机构；州长只是其中一个职位，并非机构整体。"},{"word":"governance","ipa":"/ˈɡʌvənəns/","tag":"the manner","definition":"The processes by which decisions are taken and reviewed; it names a practice, not a person.","definitionCN":"决定如何作出与复核的流程；指做法，不指人。"},{"word":"gubernatorial","ipa":"/ˌɡuːbənəˈtɔːriəl/","tag":"the adjective","definition":"Relating to a governor's office, as a gubernatorial race; it describes the post rather than the holder.","definitionCN":"与州长职位有关，如州长选举；它描述职位，而非任职者。"},{"word":"governess","ipa":"/ˈɡʌvənəs/","tag":"a private teacher","definition":"A woman employed to teach children in a household; the form looks feminine but the meaning is domestic education, not rule.","definitionCN":"受雇在家庭中教孩子的女性；形式似为阴性，但含义是家庭教育，而非治理。"}]},{"heading":"NEAR MEANING","entries":[{"word":"premier","ipa":"/ˈpremiə/","tag":"head of a cabinet","definition":"The head of a national or provincial cabinet; a governor may hold a largely ceremonial or a directly executive post.","definitionCN":"国家或省级内阁的首脑；州长的职位可能是礼仪性的，也可能握有直接行政权。"},{"word":"mayor","ipa":"/ˈmeɪə/","tag":"city scale","definition":"The elected head of a city; the unit governed is smaller and the title differs by charter.","definitionCN":"经选举产生的市长；所治理的单位更小，称谓依章程而定。"},{"word":"administrator","ipa":"/əˈdɪnɪstreɪtə/","tag":"appointed manager","definition":"A person appointed to run an institution or territory; the emphasis is on management rather than on political leadership.","definitionCN":"受命管理某机构或某地区的人；强调管理，而非政治领导。"},{"word":"superintendent","ipa":"/ˌsuːpərɪnˈtendənt/","tag":"oversight of a service","definition":"The head of a service or establishment, such as schools or a building; the word stresses supervision.","definitionCN":"某一服务或机构的首长，如督学或楼宇主管；此词强调监督。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin base means steersman, so every governor is pictured with a hand on the rudder.","cn":"拉丁词根意为舵手，所以每一位州长都被想成手握船舵的人。"},{"en":"The family runs govern, government, governance, governorship and gubernatorial.","cn":"同族词包括治理、政府、治理方式、州长职位与州长的。"},{"en":"Fixed phrases sort the offices: state governor, governor-general, bank governor, prison governor.","cn":"固定搭配把各种职位分开：州长、总督、央行行长、监狱长。"},{"en":"The same word names a metal device that keeps an engine at one speed.","cn":"同一个词还指一种让发动机保持单一转速的金属装置。"},{"en":"The adjective for the office is gubernatorial, which comes more directly from Latin.","cn":"表示该职位的形容词是 gubernatorial，它更直接地来自拉丁语。"}],"abstract":[{"en":"Picture a hand on a rudder while everyone else rows.","cn":"想象一只手扶着舵，其余的人都在划桨。"},{"en":"Picture a boardroom where one chair is set slightly higher than the others.","cn":"想象一间董事会会议室，其中一把椅子比其余略高。"},{"en":"Picture a brass device opening and closing as a wheel spins faster.","cn":"想象一个铜制装置随着轮子转快而开合。"}]},"examples":[{"en":"The governor vetoed the tax bill on the last day.","cn":"州长在最后一天否决了这项税收法案。"},{"en":"Central bank governors met to discuss the currency.","cn":"各国央行行长开会讨论货币问题。"},{"en":"The prison governor resigned after the report.","cn":"报告公布后，监狱长辞职了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「掌舵的人」——为一州或一家机构掌舵的那位 → 州长、行长","word":"governor"},"root":"governor 经古法语出自拉丁 gubernator「舵手、行省长官」，源头 gubernare「掌舵、指引」，该动词借自希腊 kybernan「掌舵」，更深来源不确定。","sensesIntro":{"en":"Eight senses follow one rudder: the state's chief, the colonial deputy, the board member, the bank head, the prison head, the machine part, the fortress commander, and finally anyone who sets a course.","cn":"八个义项围绕同一只船舵展开：一州之首、殖民地代表、理事、央行首长、监狱主管、机械部件、要塞指挥官，最后是任何定下方向的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand on a rudder, with a whole vessel depending on the course.","cn":"核心意象：一只手扶着舵，整条船都取决于这条航线。"},"chain":["THE STEERSMAN","THE STATE HEAD","THE SENT DEPUTY","THE BOARD MEMBER","THE DEVICE","ANY COURSE-SETTER"],"branches":[{"senses":"01","en":"STATE HEAD: the elected chief of a state, the most familiar modern reading.","cn":"州之首：经选举产生的一州首长，这是最熟悉的现代读法。"},{"senses":"02 · 07","en":"SENT AND HOLDING: a governor may be posted to a dependency or left holding a fortress for a sovereign.","cn":"派出与据守：总督可被派往属地，也可替君主据守一座要塞。"},{"senses":"03","en":"BOARD: oversight without daily handling, steering an institution rather than a state.","cn":"理事会：不亲自日常操作的监督，为机构而非国家掌舵。"},{"senses":"04 · 05","en":"BANK AND PRISON: money and inmates are each kept on course by one responsible head.","cn":"银行与监狱：货币与在押者各由一位负责人保持在航线上。"},{"senses":"06 · 08","en":"METAL AND GENERAL: the metaphor becomes a brass part, then returns to any person who sets a course.","cn":"金属与一般：比喻先变成一件铜制零件，再回到任何定下方向的人。"}]},"affixes":{"intro":{"en":"Governor is a Latin agent noun behind an English title, built on a verb that came from Greek seamanship.","cn":"governor 是立在一个拉丁表人名词上的英语称谓，那个名词又立在一个来自希腊航海用语的动词上。"},"latinIntro":{"en":"Gubernare and gubernator supply govern, governor, government and gubernatorial, all from the image of the rudder.","cn":"gubernare 与 gubernator 衍生出治理、州长、政府与州长的，全部来自船舵这一意象。"},"items":[{"word":"kybernan","structure":"kybernan (Greek verb, 'to steer')","meaning":"to steer","meaningCN":"掌舵","example":"The Greek verb names the act of holding a course.","exampleCN":"这个希腊动词指保持航向这一动作。"},{"word":"gubernare","structure":"gubernare (Latin verb, from Greek)","meaning":"to steer, direct","meaningCN":"掌舵；指引","example":"The verb widened from ships to provinces.","exampleCN":"这个动词从船只扩用到行省。"},{"word":"-tor","structure":"-tor (Latin agent-noun suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix marks the person at the rudder.","exampleCN":"这个后缀标记站在舵前的人。"},{"word":"gubernator","structure":"gubernare + -tor","meaning":"steersman; provincial head","meaningCN":"舵手；行省长官","example":"The noun already covered both ship and province.","exampleCN":"这个名词已经同时涵盖船与行省。"},{"word":"govern","structure":"Old French governer","meaning":"to rule, guide","meaningCN":"统治；引导","example":"The verb entered English in the fourteenth century.","exampleCN":"这个动词在十四世纪进入英语。"},{"word":"-or","structure":"-or (English agent-noun suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The ending carries the Latin agent sense into English.","exampleCN":"这个词尾把拉丁的表人含义带入英语。"},{"word":"government","structure":"govern + -ment","meaning":"the act, then the body","meaningCN":"治理行为，后指机构","example":"The noun first named steering.","exampleCN":"这个名词最初指掌舵。"},{"word":"governorship","structure":"governor + -ship (office or state)","meaning":"the post of a governor","meaningCN":"州长职位","example":"The governorship changed hands twice.","exampleCN":"州长职位两次易手。"},{"word":"gubernatorial","structure":"gubernator + -ial (adjective)","meaning":"of a governor","meaningCN":"州长的","example":"The gubernatorial race drew national money.","exampleCN":"这场州长选举吸引了全国资金。"}],"latinEntries":[{"word":"gubernare","structure":"gubernare, gubernavi, gubernatum (verb, first conjugation; from Greek)","meaning":"to steer, direct","meaningCN":"掌舵；指引"},{"word":"gubernator","structure":"gubernator, gubernatoris (m., third declension)","meaning":"steersman; governor","meaningCN":"舵手；长官"},{"word":"gubernaculum","structure":"gubernaculum, gubernaculi (n., second declension)","meaning":"rudder","meaningCN":"船舵"}]}},{"word":"governing","ipa_uk":"/ˈɡʌvənɪŋ/","ipa_us":"/ˈɡʌvərnɪŋ/","definition_zh":"执政的；主管的；起支配作用的；治理（动名词）；（文件）适用的","definition_en":"currently holding authority, controlling an institution, or setting the rules that others must follow; also the act of governing","core_image":"会议室里，理事会成员围着长桌表决一项规程，主席敲下小槌","scene":"会议室里，理事会成员围着长桌表决一项规程，主席敲下小槌。The governing board met behind closed doors for six hours.","sceneCN":"这里指「行使管理权的」，对应第 2 个义项：负责主持机构事务的理事会；句意为这个理事会闭门开了六个小时。画面要点：长条会议桌、成叠规程、木槌。","pos":[{"tag":"adj.","zh":"执政的；掌权的；主管的"},{"tag":"adj.","zh":"起支配作用的；具有指导效力的"},{"tag":"n.","zh":"治理；统治（作动名词用）"}],"collocations":[{"phrase":"governing party","zh":"执政党"},{"phrase":"governing board","zh":"理事会；董事会"},{"phrase":"governing principles","zh":"指导原则"},{"phrase":"governing law","zh":"适用法律（合同条款用语）"},{"phrase":"governing class","zh":"统治阶级"},{"phrase":"the governing of a city","zh":"对一座城市的治理"}],"forms":[{"label":"现在分词（本词）","form":"governing"},{"label":"动词（治理）","form":"govern"},{"label":"过去式","form":"governed"},{"label":"过去分词","form":"governed"},{"label":"名词（政府）","form":"government"},{"label":"名词（治理者）","form":"governor"},{"label":"名词（治理方式）","form":"governance"}],"derivatives":[{"word":"government","pos":"n.","zh":"政府；治理"},{"word":"governance","pos":"n.","zh":"治理方式；治理结构"},{"word":"governor","pos":"n.","zh":"州长；理事"},{"word":"govern","pos":"v.","zh":"治理；支配"},{"word":"ungovernable","pos":"adj.","zh":"无法治理的；难以控制的"}],"senses":[{"no":"01","title":"Currently in power","titleCN":"目前执政的","definition":"describing the party or coalition that holds office at the present time","definitionCN":"形容目前掌握政权的政党或联盟","example":"The governing party lost four ministers in a week.","exampleCN":"执政党一周之内失去了四位部长。","why":"the present participle marks action happening now, so governing means holding the reins at this moment.","whyCN":"现在分词标记正在进行的动作，因此 governing 指此刻正握着缰绳。"},{"no":"02","title":"Running an institution","titleCN":"主管机构事务的","definition":"describing the board or council with legal responsibility for an organisation","definitionCN":"形容对某组织负有法定责任的理事会或委员会","example":"The governing board met behind closed doors.","exampleCN":"理事会闭门开了会。","why":"a board that 'governs' sets the course without doing the daily work, and the participle marks that supervising role.","whyCN":"一个「治理」的理事会只定方向而不做日常事务，这个分词标记的正是这种监督角色。"},{"no":"03","title":"Setting the ruling principle","titleCN":"起支配作用的原则","definition":"describing the idea or rule that decides how other things are done","definitionCN":"形容决定其他事情如何做的观念或规则","example":"Fairness was the governing principle of the settlement.","exampleCN":"公平是这套解决方案的指导原则。","why":"what governs need not be a person: any rule that steers a process governs it in the same sense.","whyCN":"起治理作用的不必是人：任何引导过程的规则，都在同样的意义上「治理」它。"},{"no":"04","title":"The law that applies to a contract","titleCN":"合同中适用的法律","definition":"in legal drafting, the body of law chosen to interpret an agreement","definitionCN":"在法律起草中，被选定用来解释一份协议的那套法律","example":"The contract names the governing law in clause twelve.","exampleCN":"合同在第十二条写明了适用法律。","why":"a document is steered by the law named inside it, so drafting calls that law the governing one.","whyCN":"文件由其中指定的法律来引导，因此起草时把那套法律称为「适用的」。"},{"no":"05","title":"The class that holds power","titleCN":"掌握权力的那一层人","definition":"describing the small group that occupies the decisive posts in a society","definitionCN":"形容在社会中占据决定性职位的那一小群人","example":"The governing class changed its accent but not its habits.","exampleCN":"统治阶级换了口音，却没换习气。","why":"power is held by people, so the participle attaches to a social group as readily as to a party.","whyCN":"权力由人掌握，因此这个分词既能修饰政党，也能修饰一个社会群体。"},{"no":"06","title":"The act itself as a noun","titleCN":"作名词：治理这件事","definition":"the activity of directing a state or body, used where the process rather than the institution is meant","definitionCN":"指引导国家或机构的活动，用于强调过程而非机构","example":"Governing is harder than campaigning.","exampleCN":"治理比竞选更难。","why":"English participles become nouns without changing form, so the word can name the activity it describes.","whyCN":"英语分词不加变化就能作名词，因此这个词可以指它所描述的活动。"},{"no":"07","title":"The equation that determines a system","titleCN":"决定系统行为的方程","definition":"in science and engineering, the relation that fixes how a system changes over time","definitionCN":"在科学与工程中，决定系统如何随时间变化的关系式","example":"The governing equation sets the pressure at every point.","exampleCN":"这个主控方程定出每一点的压力。","why":"if a rule steers a process, then the rule that steers a physical process can be called governing too.","whyCN":"若规则能引导过程，那么引导物理过程的那条规则也可以称为「主控的」。"},{"no":"08","title":"Abstract: whatever sets the course","titleCN":"抽象义：任何决定走向的东西","definition":"in general use, the element that determines the direction of an outcome, whether person, rule or force","definitionCN":"泛指决定某个结果走向的要素，无论是人、规则还是力量","example":"Fear, not policy, was the governing force in that decision.","exampleCN":"左右那个决定的不是政策，而是恐惧。","why":"the abstract sense keeps only the setting of a course and lets the office, the board and the equation fall away.","whyCN":"抽象义只留下「定下方向」，职位、理事会与方程都被去掉。"}],"etymology":{"intro":{"en":"Governing is the present participle of govern, a verb that came through Old French from Latin and ultimately from Greek seamanship. Dates are approximate.","cn":"governing 是 govern 的现在分词，这个动词经古法语上溯到拉丁语，最终源自希腊航海用语。年代均为约数。"},"items":[{"era":"GREEK KYBERNAN","en":"Kybernan meant 'to steer, pilot'; its deeper origin is not established, so any older root proposed for it is a reconstruction.","cn":"kybernan 意为「掌舵、驾驶」；它更深的来源未得到证明，凡为其提出的更早词根均属重构形式。"},{"era":"LATIN GUBERNARE","en":"Latin gubernare 'to steer, direct' came from the Greek verb and widened from ships to the direction of people and provinces.","cn":"拉丁 gubernare「掌舵、指引」来自那个希腊动词，并从船只扩用到对人的引导与对行省的管理。"},{"era":"OLD FRENCH GOVERNER","en":"Old French governer brought the verb into English in the fourteenth century, and the present participle governing was formed on the English stem.","cn":"古法语 governer 在十四世纪把这个动词带入英语，现在分词 governing 则是在英语词干上构成的。"},{"era":"POLITICAL PARTICIPLE","en":"From the seventeenth century the participle was used attributively, as in governing party, to name the body currently holding authority.","cn":"从十七世纪起，这个分词开始作定语使用，如「执政党」，用来指目前掌握权力的机构。"},{"era":"TECHNICAL SENSE","en":"In modern engineering the same participle describes the equation or condition that determines a system's behaviour, an extension of the idea of a rule that steers.","cn":"在现代工程中，同一个分词用来描述决定系统行为的方程或条件，这是「引导性规则」这一想法的延伸。"}]},"similar":{"note":{"en":"Group one holds forms from the same stem that are easily substituted for this participle; group two holds adjectives for authority with a different scope.","cn":"第一组是同词干、容易被拿来替换这个分词的词；第二组是权威范围不同的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"governed","ipa":"/ˈɡʌvənd/","tag":"the other side","definition":"The past participle describing those who are ruled, as a governed territory; it reverses who holds the rudder.","definitionCN":"过去分词，描述被治理的一方，如被治理的地区；它把掌舵者与被掌舵者颠倒过来。"},{"word":"governmental","ipa":"/ˌɡʌvənˈmentəl/","tag":"belonging to the state","definition":"An adjective of belonging to government as an institution; governing marks present activity instead of ownership.","definitionCN":"表示归属于作为机构的政府；而 governing 标记当下的活动，而非归属。"},{"word":"government","ipa":"/ˈɡʌvənmənt/","tag":"the noun","definition":"The institution or the act; the participle is what that institution is doing now.","definitionCN":"指机构或行为；而这个分词指该机构此刻正在做的事。"},{"word":"governance","ipa":"/ˈɡʌvənəns/","tag":"the manner","definition":"The system of rules and review by which decisions are made; it is a design, while governing is the practice.","definitionCN":"指作出决定所依的规则与复核体系；它是设计，而治理是实践。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ruling","ipa":"/ˈruːlɪŋ/","tag":"holding power","definition":"Describing the group that holds power, as a ruling party; it is close to governing but can also mean a court's decision as a noun.","definitionCN":"形容掌握权力的集团，如执政集团；与 governing 相近，但作名词时也可指法院的裁定。"},{"word":"controlling","ipa":"/kənˈtrəʊlɪŋ/","tag":"holding a share","definition":"Describing the party with enough shares or votes to decide, as a controlling stake; it is financial or numerical rather than political.","definitionCN":"形容拥有足够股份或票数来作决定的一方，如控股；偏财务或数量意义，而非政治意义。"},{"word":"dominant","ipa":"/ˈdɒmɪnənt/","tag":"the strongest element","definition":"Describing the element that outweighs the others, as a dominant theme; it need not carry any authority to rule.","definitionCN":"形容压过其他要素的那一个，如主导主题；它未必具备统治的权威。"},{"word":"directive","ipa":"/daɪˈrektɪv/","tag":"an instruction","definition":"A noun or adjective for an instruction that must be followed; a governing principle guides, while a directive orders.","definitionCN":"指必须遵守的指示，可作名词或形容词；指导原则是引导，而 directive 是命令。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The ending marks an action in progress, so governing is the hand currently on the rudder.","cn":"词尾标记正在进行的动作，所以 governing 指此刻扶在舵上的那只手。"},{"en":"The family runs govern, government, governor, governance and ungovernable.","cn":"同族词包括治理、政府、州长、治理方式与无法治理的。"},{"en":"Fixed phrases sort the uses: governing party, governing board, governing principles, governing law.","cn":"固定搭配给用法分类：执政党、理事会、指导原则、适用法律。"},{"en":"The same word appears in engineering as governing equation, where a rule steers a physical system.","cn":"同一个词在工程里作「主控方程」，那里是规则在引导一个物理系统。"},{"en":"Its passive partner is governed, which names the side that is steered.","cn":"它的被动伙伴是 governed，指被引导的那一方。"}],"abstract":[{"en":"Picture a hand on a rudder while the crew waits for the order.","cn":"想象一只手扶着舵，船员等着命令。"},{"en":"Picture a single rule written at the top of a page that every later line must follow.","cn":"想象一条写在纸页最上方的规则，后面每一行都必须遵守它。"},{"en":"Picture one weight on a scale deciding which side goes down.","cn":"想象秤上的一块砝码决定哪一边下沉。"}]},"examples":[{"en":"The governing board approved the new charter.","cn":"理事会批准了新章程。"},{"en":"Cost was the governing consideration in the design.","cn":"成本是设计中的决定性考量。"},{"en":"Governing requires patience that campaigns do not.","cn":"治理需要竞选所不需要的耐心。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「掌舵 + 正在进行」——此刻正握着舵、定着方向的那一方 → 执政的、主管的","word":"governing"},"root":"governing 是 govern 的现在分词；govern 经古法语出自拉丁 gubernare「掌舵、指引」，源头为希腊 kybernan「掌舵」，更深来源不确定。","sensesIntro":{"en":"Eight senses hang on one participle: whoever or whatever holds the rudder now, whether a party, a board, a principle, a contract clause, a class, the activity itself, an equation, or any decisive force.","cn":"八个义项挂在同一个分词上：此刻握着舵的人或物，或政党、或理事会、或原则、或合同条款、或一个阶层、或活动本身、或一条方程，或任何决定性的力量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a board around a long table, a gavel coming down on a rule.","cn":"核心意象：长桌旁的理事会，木槌落在一条规程上。"},"chain":["HOLDING THE REINS","RUNNING A BODY","SETTING THE RULE","APPLYING THE LAW","THE RULING LAYER","WHATEVER DECIDES"],"branches":[{"senses":"01","en":"IN OFFICE: the participle marks the party that holds power at this moment.","cn":"在位：这个分词标记此刻掌握政权的政党。"},{"senses":"02 · 05","en":"BODY AND CLASS: a board runs an institution, and a social layer holds the decisive posts.","cn":"机构与阶层：理事会管理一个机构，而一个社会阶层占据决定性职位。"},{"senses":"03","en":"PRINCIPLE: what steers need not be a person, since a rule can govern a process.","cn":"原则：起引导作用的不必是人，因为规则也能治理一个过程。"},{"senses":"04 · 07","en":"DOCUMENT AND EQUATION: a contract names the law that governs it, and a system obeys the equation that governs it.","cn":"文件与方程：合同写明管辖它的法律，系统服从管辖它的方程。"},{"senses":"06 · 08","en":"ACT AND ABSTRACTION: the activity itself takes the same form, and finally any decisive force qualifies.","cn":"行为与抽象：活动本身用同一形式，最后任何决定性力量都算得上。"}]},"affixes":{"intro":{"en":"Governing is a verb stem plus the participial ending, and the stem came into English through French from Latin and Greek.","cn":"governing 是动词词干加分词词尾，而词干经法语从拉丁语与希腊语进入英语。"},"latinIntro":{"en":"Latin gubernare stands behind govern and its whole family, from government to gubernatorial.","cn":"拉丁 gubernare 是治理及其整族词的来源，从政府到州长的都是。"},"items":[{"word":"kybernan","structure":"kybernan (Greek verb, 'to steer')","meaning":"to steer","meaningCN":"掌舵","example":"The Greek verb supplies the maritime image.","exampleCN":"这个希腊动词提供航海意象。"},{"word":"gubernare","structure":"gubernare (Latin verb, from Greek)","meaning":"to steer, rule","meaningCN":"掌舵；统治","example":"The Latin verb widened to civil rule.","exampleCN":"这个拉丁动词扩及民政统治。"},{"word":"govern","structure":"Old French governer, from Latin gubernare","meaning":"to rule, guide","meaningCN":"治理；引导","example":"The English verb arrived in the fourteenth century.","exampleCN":"这个英语动词在十四世纪到来。"},{"word":"-ing","structure":"-ing (English participial and gerund ending)","meaning":"action in progress, or the action as a noun","meaningCN":"正在进行的动作，或作名词的动作","example":"The ending lets one form serve as adjective and noun.","exampleCN":"这个词尾让同一形式兼作形容词与名词。"},{"word":"-ment","structure":"-ment (noun suffix of action or result)","meaning":"the act or its result","meaningCN":"行为或其结果","example":"The suffix built the noun for the institution.","exampleCN":"这个词尾造出指机构的名词。"},{"word":"government","structure":"govern + -ment","meaning":"the act, then the body","meaningCN":"治理行为，后指机构","example":"Government began as a name for steering.","exampleCN":"政府一词最初是掌舵的名称。"},{"word":"governor","structure":"govern + -or","meaning":"one who governs","meaningCN":"治理者","example":"The governor held the province.","exampleCN":"总督据守着那个行省。"},{"word":"governance","structure":"govern + -ance","meaning":"the manner of governing","meaningCN":"治理的方式","example":"Governance concerns how decisions are reviewed.","exampleCN":"治理方式关乎决定如何被复核。"},{"word":"ungovernable","structure":"un- (not) + govern + -able","meaning":"impossible to rule","meaningCN":"无法治理的","example":"The province had become ungovernable.","exampleCN":"这个省已经变得无法治理。"}],"latinEntries":[{"word":"gubernare","structure":"gubernare, gubernavi, gubernatum (verb, first conjugation; from Greek)","meaning":"to steer, direct","meaningCN":"掌舵；指引"},{"word":"gubernatio","structure":"gubernatio, gubernationis (f., third declension)","meaning":"a steering, direction","meaningCN":"掌舵；指引"},{"word":"gubernator","structure":"gubernator, gubernatoris (m., third declension)","meaning":"steersman, governor","meaningCN":"舵手；长官"}]}},{"word":"authoritative","ipa_uk":"/ɔːˈθɒrɪtətɪv/","ipa_us":"/ɔːˈθɔːrəteɪtɪv/","definition_zh":"有权威的；可靠的；官方认定的；带命令口吻的；权威性的（定本、裁定）","definition_en":"carrying weight because of recognised expertise or official standing, and sometimes describing a commanding manner","core_image":"档案馆阅览室里，编者把初版校样与手稿逐行对照，在页边写下勘定","scene":"档案馆阅览室里，一位编者把初版校样与手稿逐行对照，在页边写下勘定。The authoritative edition corrected errors that had stood for a century.","sceneCN":"这里指「权威性的定本」，对应第 4 个义项：经严格考订、被公认为标准版本的著作；句意为这个权威定本改正了沿用百年的错误。画面要点：阅览室长桌、校样、页边批注。","pos":[{"tag":"adj.","zh":"有权威的；可信的（因专业或地位而具分量）"},{"tag":"adj.","zh":"官方的；经正式认定的"},{"tag":"adj.","zh":"带命令口吻的；不容置疑的"}],"collocations":[{"phrase":"an authoritative source","zh":"权威来源"},{"phrase":"an authoritative account","zh":"权威记述"},{"phrase":"an authoritative voice","zh":"权威声音"},{"phrase":"the authoritative work on the subject","zh":"该领域的权威著作"},{"phrase":"an authoritative ruling","zh":"权威裁定"},{"phrase":"in an authoritative tone","zh":"以命令式口吻"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more authoritative"},{"label":"最高级（更多用 most 构成）","form":"most authoritative"},{"label":"名词（权威；权限）","form":"authority"},{"label":"名词（作者）","form":"author"},{"label":"动词（授权）","form":"authorize"},{"label":"名词（授权）","form":"authorization"}],"derivatives":[{"word":"authority","pos":"n.","zh":"权威；权限；主管机构"},{"word":"author","pos":"n.","zh":"作者；创始人"},{"word":"authorize","pos":"v.","zh":"授权；批准"},{"word":"authorization","pos":"n.","zh":"授权；批准文件"},{"word":"authoritatively","pos":"adv.","zh":"以权威方式；带权威口吻地"}],"senses":[{"no":"01","title":"Reliable because of expertise","titleCN":"因专业而可靠","definition":"describing information or a person whose judgement carries weight because of deep knowledge","definitionCN":"形容因知识深厚而具有分量的信息或人物","example":"She is authoritative on the history of the region.","exampleCN":"她在这个地区的历史研究上很有权威。","why":"the Latin noun behind the word meant influence or prestige, so authority first means standing, and authoritative means having that standing.","whyCN":"这个词背后的拉丁名词意为影响力与声望，所以 authority 首先指分量，而 authoritative 指具有这种分量的。"},{"no":"02","title":"Officially recognised","titleCN":"经官方认定的","definition":"describing a text, list or statement issued by a body with the right to settle the matter","definitionCN":"形容由有权定夺此事的机构发布的文本、名册或声明","example":"The registry is the authoritative list of licensed doctors.","exampleCN":"这份登记册是持证医师的权威名册。","why":"recognition can come from office as well as from knowledge, and the word covers both sources of weight.","whyCN":"分量既可来自学问，也可来自职位，这个词同时涵盖这两种来源。"},{"no":"03","title":"A commanding manner","titleCN":"带命令意味的态度","definition":"describing a tone or gesture that expects to be obeyed rather than discussed","definitionCN":"形容期待被服从、而非被讨论的语气或姿态","example":"He answered in the authoritative tone of a headmaster.","exampleCN":"他用校长那种不容置疑的口气回答。","why":"a person with weight can speak as if the question were closed, and the adjective then describes the manner rather than the knowledge.","whyCN":"有分量的人说话时可以像是问题已经定了，此时这个形容词描述的是态度，而非学识。"},{"no":"04","title":"The standard edition or reference work","titleCN":"标准定本或权威工具书","definition":"describing a book that others cite because it has settled the text or the facts","definitionCN":"形容因已厘定文本或事实而被他人引用的著作","example":"The authoritative edition corrected errors that had stood for a century.","exampleCN":"这个权威定本改正了沿用百年的错误。","why":"a work becomes a standard when the field stops checking it and starts citing it, and the adjective marks that point.","whyCN":"当同行不再核查、转而引用一部著作时，它就成了标准，这个形容词标记的正是那一刻。"},{"no":"05","title":"A binding ruling","titleCN":"具有约束力的裁定","definition":"describing a decision by a court or regulator that others must follow","definitionCN":"形容法院或监管机构作出、他人必须遵从的决定","example":"Only an authoritative ruling can settle the dispute.","exampleCN":"只有权威裁定才能了结这场争端。","why":"when a body can compel, its word has weight in the strongest sense, and the adjective attaches to the decision.","whyCN":"当某机构能强制执行时，它的话就有最强意义上的分量，这个形容词便附着在决定上。"},{"no":"06","title":"The definitive account","titleCN":"被公认为定论的叙述","definition":"describing a study or report that others treat as the fullest and best-supported version","definitionCN":"形容被同行视为最完整、证据最充分的著作或报告","example":"Her book remains the authoritative account of the negotiations.","exampleCN":"她那本书仍是关于这些谈判的权威叙述。","why":"an account that ends argument is authoritative in the same way a standard edition is, by consent of the field.","whyCN":"一部结束争论的叙述，与标准定本一样是靠同行的认可而具权威的。"},{"no":"07","title":"A recognised figure in a field","titleCN":"某一领域公认的代表人物","definition":"describing a scholar or official whom others defer to on a particular question","definitionCN":"形容在某一问题上被他人请教的学者或官员","example":"He became the authoritative voice on water law.","exampleCN":"他成了水法问题上的权威声音。","why":"weight attaches to persons as well as to texts, and one sentence can mark both the expertise and the deference.","whyCN":"分量既附在文本上，也附在人身上，一句话就能同时标出专业与被请教这两件事。"},{"no":"08","title":"Abstract: weight that needs no argument","titleCN":"抽象义：不必论证即有分量","definition":"in general use, describing something accepted without challenge because of who produced it","definitionCN":"泛指因出自某人之手而被直接接受、不再追问的东西","example":"The memo carried an authoritative silence on the cost.","exampleCN":"这份备忘录对成本问题保持一种权威式的沉默。","why":"the abstract sense keeps only the effect, namely that the question is treated as closed.","whyCN":"抽象义只留下效果，即那个问题被当作已经定了。"}],"etymology":{"intro":{"en":"Authoritative rests on the Latin noun for authority, which grew from a verb meaning to increase, and on an English adjective ending. Dates are approximate.","cn":"authoritative 立在一个意为「权威」的拉丁名词与一个英语形容词词尾上，而那个拉丁名词又出自一个意为「增加」的动词。年代均为约数。"},"items":[{"era":"LATIN AUGERE","en":"Augere meant 'to increase, make grow'; the Indo-European root behind it is reconstructed rather than attested, so any earlier form cited is a reconstruction.","cn":"augere 意为「增加、使生长」；它背后的印欧语词根属重构而非有书证的形式，因此凡为其引出的更早形式都是重构形式。"},{"era":"LATIN AUCTOR","en":"Auctor named the one who causes something to grow or begin: an originator, a promoter, later a seller and a writer.","cn":"auctor 指使事物生长或开始的那一位：创始者、推动者，后来也指卖方与作者。"},{"era":"LATIN AUCTORITAS","en":"Auctoritas meant influence, prestige and the weight of a judgement, and it belonged to the senate as much as to a single writer.","cn":"auctoritas 意为影响力、声望与判断的分量，它既属于元老院，也属于单个作者。"},{"era":"FRENCH AUTHORITE","en":"Old French autorite carried the noun into English in the fourteenth century as authority, first as a personal quality and later as an office or a body.","cn":"古法语 autorite 在十四世纪把这个名词以 authority 的形式带入英语，最初指个人品质，后指职位或机构。"},{"era":"SEVENTEENTH-CENTURY ADJECTIVE","en":"Authoritative was formed on authority with the ending -ative and first meant 'having power to command belief', before it also came to describe a commanding manner.","cn":"authoritative 由 authority 加表示「具有……性质」的形容词词尾构成，最初意为「具有令人信服之力」，后来也用来形容命令式的态度。"}]},"similar":{"note":{"en":"Group one holds words from the authority family that are easily confused with this adjective; group two holds adjectives of reliability and command.","cn":"第一组是同出 authority 词族、容易与本词混淆的词；第二组是表示可靠或命令意味的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"authoritarian","ipa":"/ˌɔːθɒrɪˈteəriən/","tag":"a political system","definition":"Describing a system that demands obedience and limits opposition; it is a charge against a regime, not a compliment about a source.","definitionCN":"形容要求服从、限制反对的政治体制；它是对政权的指控，而非对信息来源的褒扬。"},{"word":"authorized","ipa":"/ˈɔːθəraɪzd/","tag":"permitted","definition":"Describing someone or something given formal permission; a work can be authorised without being authoritative.","definitionCN":"形容获得正式许可的人或物；一部作品可以是获准发行的，却未必具有权威性。"},{"word":"author","ipa":"/ˈɔːθə/","tag":"the writer","definition":"The person who wrote a work; authorship is a fact, while authoritative describes the standing the work has gained.","definitionCN":"指作品的写作者；作者身份是事实，而 authoritative 描述作品获得的地位。"},{"word":"authentic","ipa":"/ɔːˈθentɪk/","tag":"genuine","definition":"Meaning real or not counterfeit, as an authentic signature; a document can be authentic and still be wrong.","definitionCN":"意为真实的、非伪造的，如真实签名；文件可以是真的，内容却可能是错的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"definitive","ipa":"/dɪˈfɪnətɪv/","tag":"settling the question","definition":"Describing the version that ends dispute, as a definitive study; authoritative adds who is recognised as having the right to settle it.","definitionCN":"形容终结争论的版本，如定论性研究；authoritative 另添「谁被认可有权定夺」这层意思。"},{"word":"reliable","ipa":"/rɪˈlaɪəbl/","tag":"can be trusted","definition":"Describing something that can be depended on to be accurate; reliability is about error rates, not about prestige.","definitionCN":"形容可以依赖其准确性的事物；可靠性关乎出错率，而非声望。"},{"word":"official","ipa":"/əˈfɪʃəl/","tag":"from an office","definition":"Describing what comes from a body with formal standing; an official statement may still be wrong or disputed.","definitionCN":"形容来自具有正式地位之机构的事物；官方声明也可能是错的或有争议的。"},{"word":"commanding","ipa":"/kəˈmɑːndɪŋ/","tag":"the tone only","definition":"Describing a manner or presence that expects obedience; it covers the third sense alone and says nothing about knowledge.","definitionCN":"形容期待被服从的态度或气场；它只涵盖第三义项，与学识无关。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base verb meant to make grow, so an author is one who makes something come into being, and authority is the weight that follows.","cn":"基础动词意为「使生长」，所以作者是使某物出现的人，而权威是随之而来的分量。"},{"en":"The family runs authority, author, authorize, authorization and authoritatively.","cn":"同族词包括权威、作者、授权、授权文件与以权威方式。"},{"en":"Fixed phrases mark the uses: an authoritative source, an authoritative account, an authoritative ruling.","cn":"固定搭配标出用法：权威来源、权威记述、权威裁定。"},{"en":"The word can praise a source and also describe a bossy tone, so context decides the colour.","cn":"这个词既能称赞信息来源，也能形容专断口气，语气由语境决定。"},{"en":"The trap to avoid is authoritarian, which describes a regime rather than a reference book.","cn":"要避开的陷阱是 authoritarian，那词描述政权，而非参考书。"}],"abstract":[{"en":"Picture a book so heavily cited that nobody bothers to check it again.","cn":"想象一本书被引用得太多，以至于没人再去核对它。"},{"en":"Picture a raised hand that ends a discussion without a vote.","cn":"想象一只举起的手，不用表决就结束了讨论。"},{"en":"Picture a stamp on a page that makes every later objection look unnecessary.","cn":"想象纸页上的一枚印章，让之后所有异议都显得多余。"}]},"examples":[{"en":"The committee waited for an authoritative ruling on the boundary.","cn":"委员会等待关于边界的权威裁定。"},{"en":"His account of the war is still treated as authoritative.","cn":"他对那场战争的叙述仍被视为权威。"},{"en":"She spoke in a tone that was almost too authoritative.","cn":"她说话的口吻几乎过于命令式了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「权威 + 形容词」——一开口就让人不必再追问的那份分量 → 有权威的","word":"authoritative"},"root":"authoritative 由 authority 加形容词词尾构成；authority 经古法语出自拉丁 auctoritas「影响力、声望」，源头 auctor「创始者、作者」，再上溯到 augere「使生长」。印欧语词根属重构形式。","sensesIntro":{"en":"Eight senses follow one weight: knowledge earns it, office confirms it, a manner displays it, a standard edition embodies it, a ruling enforces it, a definitive account earns it by consent, a person carries it, and finally anything accepted without argument has it.","cn":"八个义项围绕同一份分量展开：学问赢得它，职位确认它，态度展示它，标准定本体现它，裁定强制执行它，定论性叙述靠同行认可得到它，个人承载它，最后任何被直接接受、不再追问的东西都具有它。"},"semanticMap":{"core":{"en":"CORE IMAGE: a collated proof with marginal corrections, cited by everyone afterwards.","cn":"核心意象：一份逐行校勘、写满页边批注的校样，此后被所有人引用。"},"chain":["STANDING","EXPERT WEIGHT","OFFICIAL WEIGHT","COMMANDING TONE","STANDARD TEXT","NO MORE QUESTIONS"],"branches":[{"senses":"01","en":"EXPERTISE: deep knowledge is the first source of the weight the word describes.","cn":"专业：深厚的知识是这个词所描述之分量的第一个来源。"},{"senses":"02 · 05","en":"OFFICE: a body with the right to settle a matter gives the same weight through a list or a ruling.","cn":"职位：有权定夺某事的机构，通过一份名册或一项裁定给出同样的分量。"},{"senses":"03","en":"MANNER: weight can be heard in a tone that treats the question as closed.","cn":"态度：分量可以从语气里听出来，那种语气把问题当作已经定了。"},{"senses":"04 · 06","en":"CANON: a standard edition and a definitive account are both settled by the consent of the field.","cn":"定本：标准版本与定论性叙述，都是靠同行的认可而定下来的。"},{"senses":"07 · 08","en":"PERSON AND EFFECT: one figure can carry the weight, and in the end the only test is that nobody asks again.","cn":"人与效果：一个人可以承载这份分量，而最终的检验就是没人再追问。"}]},"affixes":{"intro":{"en":"Authoritative is a noun of standing plus an adjective ending, and the noun in turn rests on a Latin verb of growth.","cn":"authoritative 是一个表示分量的名词加形容词词尾，而那个名词又立在一个意为「生长」的拉丁动词上。"},"latinIntro":{"en":"Latin auctor and auctoritas supply author, authority and authorize, all from the idea of causing something to begin or grow.","cn":"拉丁 auctor 与 auctoritas 衍生出作者、权威与授权，全都出自「使某物开始或生长」这一想法。"},"items":[{"word":"augere","structure":"augere (Latin verb, 'to increase')","meaning":"to make grow","meaningCN":"使生长；增加","example":"The verb supplies the idea of causing growth.","exampleCN":"这个动词提供「促成生长」的意思。"},{"word":"auctor","structure":"augere + -tor (agent noun)","meaning":"originator, promoter","meaningCN":"创始者；推动者","example":"The originator is the one who makes a thing begin.","exampleCN":"创始者就是使一件事开始的人。"},{"word":"auctoritas","structure":"auctor + -itas (state noun)","meaning":"influence, prestige","meaningCN":"影响力；声望","example":"The noun named weight rather than legal power.","exampleCN":"这个名词指分量，而非法律权力。"},{"word":"authority","structure":"Old French autorite, from Latin auctoritas","meaning":"standing; a body with power","meaningCN":"分量；有权机构","example":"The word moved from prestige to office.","exampleCN":"这个词从声望转指职位。"},{"word":"-ative","structure":"-ative (adjective ending, 'having the quality of')","meaning":"having the nature of","meaningCN":"具有……性质的","example":"The ending turns the noun of standing into an adjective.","exampleCN":"这个词尾把表示分量的名词变成形容词。"},{"word":"author","structure":"auctor through Old French autor","meaning":"writer, originator","meaningCN":"作者；创始者","example":"The writer is literally the one who causes the work.","exampleCN":"作者字面上就是使作品出现的人。"},{"word":"authorize","structure":"author + -ize","meaning":"to give power to","meaningCN":"授予权力","example":"The council authorized the expenditure.","exampleCN":"议会批准了这笔开支。"},{"word":"authorization","structure":"authorize + -ation","meaning":"formal permission","meaningCN":"正式许可","example":"Work began without written authorization.","exampleCN":"工作在未获书面许可的情况下开始了。"},{"word":"authoritarian","structure":"authority + -arian","meaning":"demanding obedience","meaningCN":"要求服从的","example":"The label criticises a regime, not a reference book.","exampleCN":"这个标签批评的是政权，而非参考书。"}],"latinEntries":[{"word":"augere","structure":"augere, auxi, auctum (verb, third conjugation)","meaning":"to increase, make grow","meaningCN":"增加；使生长"},{"word":"auctor","structure":"auctor, auctoris (m., third declension)","meaning":"originator, author","meaningCN":"创始者；作者"},{"word":"auctoritas","structure":"auctoritas, auctoritatis (f., third declension)","meaning":"influence, prestige, authority","meaningCN":"影响力；声望；权威"}]}},{"word":"political power","ipa_uk":"/pəˈlɪtɪkəl ˈpaʊə/","ipa_us":"/pəˈlɪtɪkəl ˈpaʊər/","definition_zh":"政治权力；左右公共决定与资源分配的能力，或制度化的统治权威","definition_en":"the capacity to shape public decisions and the distribution of resources, whether held informally or through office","core_image":"议事厅里，一份议案在表决前被两个阵营反复交换条件，三张摇摆票握在中间那排人手里","scene":"议事厅里，一份议案在表决前被两个阵营反复交换条件，而三张摇摆票握在中间那排人手里。Political power in the chamber rested on three swing votes.","sceneCN":"这里指「左右公共决定的能力」，对应第 1 个义项：通过票数与交换条件影响结果的力量；句意为这个议事厅里的政治权力握在三张摇摆票上。画面要点：议事厅座位、议案文本、中间一排人。","pos":[{"tag":"n.","zh":"政治权力（不可数；指能力、权威或影响力的总体）"}],"collocations":[{"phrase":"seize political power","zh":"夺取政治权力"},{"phrase":"hold political power","zh":"掌握政治权力"},{"phrase":"the balance of political power","zh":"政治权力的平衡"},{"phrase":"the struggle for political power","zh":"争夺政治权力"},{"phrase":"concentration of political power","zh":"政治权力的集中"},{"phrase":"a shift in political power","zh":"政治权力的转移"}],"forms":[{"label":"名词短语（本词）","form":"political power"},{"label":"复数（指多个权力中心）","form":"political powers"},{"label":"形容词（政治的）","form":"political"},{"label":"名词（政治）","form":"politics"},{"label":"名词（权力）","form":"power"},{"label":"形容词（有权势的）","form":"powerful"},{"label":"形容词（无力的）","form":"powerless"}],"derivatives":[{"word":"powerful","pos":"adj.","zh":"有权势的；效力强的"},{"word":"powerless","pos":"adj.","zh":"无力的；无权势的"},{"word":"power","pos":"n./v.","zh":"权力；动力 / 供电"},{"word":"political","pos":"adj.","zh":"政治的"},{"word":"politically","pos":"adv.","zh":"在政治上；从政治角度"}],"senses":[{"no":"01","title":"Capacity to shape public decisions","titleCN":"左右公共决定的能力","definition":"the ability of a person or group to affect what a government or assembly decides","definitionCN":"个人或群体影响政府或议会作出何种决定的能力","example":"Political power in the chamber rested on three swing votes.","exampleCN":"这个议事厅里的政治权力握在三张摇摆票上。","why":"power in Latin means being able to do something, so political power is the ability to act on the political field.","whyCN":"power 在拉丁语中意为「能够做到」，因此政治权力就是在政治场域中行动的能力。"},{"no":"02","title":"The authority of an office","titleCN":"职位带来的正式权威","definition":"the legal capacity attached to a post, such as a premiership or a ministry","definitionCN":"附着于某一职位的法定权限，如首相或部长之职","example":"The office gave him political power but not popular support.","exampleCN":"这个职位给了他政治权力，却没给他民意支持。","why":"power can be conferred as well as won, and a post converts permission into the right to decide.","whyCN":"权力既可赢得，也可授予；职位把许可转变成决定权。"},{"no":"03","title":"Control of force and coercion","titleCN":"对武力与强制手段的控制","definition":"command over the army, police or courts, which lets a holder enforce decisions","definitionCN":"对军队、警察或法院的指挥权，使持有者能强制执行决定","example":"Whoever holds the police holds real political power.","exampleCN":"谁掌握警察，谁就握有真正的政治权力。","why":"the state is defined by its monopoly on force, so control of that apparatus is power in its hardest form.","whyCN":"国家以对暴力的垄断为特征，因此掌握那套机器就是最硬的一种权力。"},{"no":"04","title":"Persuasion and attraction","titleCN":"说服与吸引之力","definition":"influence won by ideas, culture, money or reputation rather than by command","definitionCN":"靠观念、文化、金钱或声誉、而非命令赢得的影响力","example":"Aid and broadcasting gave the country political power without a single soldier.","exampleCN":"援助与广播让这个国家不出一兵就获得政治权力。","why":"if power is the ability to get an outcome, then making others want what you want counts as power too.","whyCN":"若权力是得到结果的能力，那么让别人想要你所想要的，同样算作权力。"},{"no":"05","title":"The analytical concept","titleCN":"政治学中的分析概念","definition":"the term used in research for who gets what, when and how, and by what means","definitionCN":"研究中用来追问「谁在何时以何种方式得到什么」的术语","example":"Political power is the central variable in the study.","exampleCN":"政治权力是这项研究的核心变量。","why":"a word that names a capacity becomes a measurable variable once researchers decide how to observe it.","whyCN":"一个表示能力的词，一旦研究者确定了观察方式，就成了可测量的变量。"},{"no":"06","title":"The balance between states","titleCN":"国家之间的力量对比","definition":"the distribution of capability among states, which shapes alliances and wars","definitionCN":"国家之间实力的分布，它塑造结盟与战争","example":"The treaty recorded a new balance of political power in the region.","exampleCN":"这项条约记录了该地区政治权力的一次新平衡。","why":"the same word scales from a chamber to a continent, because both are fields where capabilities are compared.","whyCN":"同一个词能从议事厅扩到一整个大陆，因为两者都是比较实力的场域。"},{"no":"07","title":"Power to set the agenda","titleCN":"设定议程的权力","definition":"the ability to decide which questions are worth deciding, so that some options never come up","definitionCN":"决定哪些问题值得被决定的能力，使某些选项根本不进入讨论","example":"Setting the agenda is the quietest form of political power.","exampleCN":"设定议程是最安静的一种政治权力。","why":"if power is the capacity to produce outcomes, then preventing a vote is as effective as winning one.","whyCN":"若权力是产生结果的能力，那么阻止一场表决与赢得一场表决同样有效。"},{"no":"08","title":"Abstract: making a collective choice binding","titleCN":"抽象义：使集体选择具有约束力","definition":"in general use, the ability to turn a group's preference into a decision that all must follow","definitionCN":"泛指把一群人的偏好变成所有人都必须遵从的决定的能力","example":"Any committee has its own political power, small as it is.","exampleCN":"任何委员会都有自己的政治权力，哪怕很小。","why":"the abstract sense keeps only the binding of a group, and the state, the army and the ballot fall away.","whyCN":"抽象义只留下「把群体约束起来」这一层，国家、军队与选票都被去掉。"}],"etymology":{"intro":{"en":"Political power pairs a Greek-derived adjective for civic affairs with a noun that came through French from a Latin verb meaning to be able. Dates are approximate.","cn":"political power 把希腊来源、表示城邦事务的形容词，与一个经法语来自拉丁语「能够」这一动词的名词配在一起。年代均为约数。"},"items":[{"era":"GREEK POLIS","en":"Polis meant a city-state and its citizen body; its deeper origin is not established, and the pre-Greek suggestion is a hypothesis rather than a demonstrated derivation.","cn":"polis 指城邦及其公民总体；它更深的来源未得到证明，前希腊语来源的说法只是假说，并非已证实的派生。"},{"era":"LATIN POTIS","en":"Potis was an adjective meaning 'able, capable', used of persons and things; its further origin is uncertain, so any older form given for it is a reconstruction.","cn":"potis 是一个意为「有能力的、能够的」形容词，可用于人也可用于物；它更早的来源不确定，凡为其给出的更早形式均属重构形式。"},{"era":"LATIN POSSE","en":"Potis plus esse 'to be' gave posse 'to be able', and from this verb came the whole family of English power words.","cn":"potis 加 esse「是」构成 posse「能够」，英语中一整族表示权力的词都出自这个动词。"},{"era":"LATIN POTESTAS AND POTENTIA","en":"Potestas named power as lawful authority or capacity, while potentia named power as force or influence; English blurs the two.","cn":"potestas 指作为合法权限或能力的权力，potentia 指作为力量或影响力的权力；英语把两者混在一起。"},{"era":"ENGLISH POWER","en":"Power entered English in the thirteenth century through Old French, first as ability and then as authority, force and influence.","cn":"power 在十三世纪经古法语进入英语，先指能力，后指权威、力量与影响力。"},{"era":"COMPOUND PHRASE","en":"The phrase political power settled in the sixteenth and seventeenth centuries, when writers needed to separate power rooted in office from power rooted in arms or wealth.","cn":"political power 这一短语在十六、十七世纪固定下来，当时作者需要把源于职位的权力，与源于武力或财富的权力分开。"}]},"similar":{"note":{"en":"Group one holds words built from the same two elements that are easily mistaken for the phrase; group two holds terms for power with a narrower or different basis.","cn":"第一组是用同样两个要素构成、容易与本短语混淆的词；第二组是基础更窄或不同的权力术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"power","ipa":"/ˈpaʊə/","tag":"the bare noun","definition":"The unqualified noun, which can mean electricity or mechanical force; the political qualifier is what restricts it to public authority.","definitionCN":"无限定的名词，也可指电力或机械力；正是「政治的」这一限定才把它收窄到公共权威。"},{"word":"political","ipa":"/pəˈlɪtɪkəl/","tag":"the adjective alone","definition":"The adjective by itself describes what relates to government; it needs the noun to name a quantity or a capacity.","definitionCN":"这个形容词单独使用只描述与政府有关；需配上名词才表示一种数量或能力。"},{"word":"powerful","ipa":"/ˈpaʊəfəl/","tag":"having much power","definition":"An adjective for a person or body that holds a lot of power; it grades the amount rather than naming the kind.","definitionCN":"形容掌握大量权力的人或机构；它标出程度，而非种类。"},{"word":"polity","ipa":"/ˈpɒləti/","tag":"the community","definition":"The organised political community itself; it is the body in which power is held, not the power held.","definitionCN":"指有组织的政治共同体本身；它是权力所在的载体，而非权力。"}]},{"heading":"NEAR MEANING","entries":[{"word":"authority","ipa":"/ɔːˈθɒrəti/","tag":"legitimate right","definition":"The recognised right to give orders; authority is power that is accepted as legitimate, while power can rest on force alone.","definitionCN":"被认可的发号施令之权；权威是被视为正当的权力，而权力可以只靠武力。"},{"word":"influence","ipa":"/ˈɪnfluəns/","tag":"no office needed","definition":"The capacity to affect decisions without formal right; it is the softest form of political power and needs no post.","definitionCN":"无需正式权利即可影响决定的能力；它是政治权力最软的一种，不必有职位。"},{"word":"sovereignty","ipa":"/ˈsɒvrənti/","tag":"legal supremacy","definition":"Supreme legal authority within a territory; it is a legal status, while political power is a working capacity.","definitionCN":"在一领土内的最高法律权威；它属法律地位，而政治权力是实际运作的能力。"},{"word":"control","ipa":"/kənˈtrəʊl/","tag":"holding the levers","definition":"Direct command over an apparatus or process; control is narrower because it names the levers rather than the capacity to win.","definitionCN":"对某套机器或流程的直接指挥；范围更窄，因为它指具体的杆杠，而非取胜的能力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The second word goes back to a Latin verb meaning to be able, so power is first an ability rather than a thing.","cn":"第二个词上溯到拉丁语中表示「能够」的动词，所以权力首先是一种能力，而非一件东西。"},{"en":"The first word is the Greek civic adjective, so the phrase limits ability to the public field.","cn":"第一个词是希腊的城邦形容词，因此这个短语把能力限定在公共场域。"},{"en":"Fixed phrases mark the uses: seize, hold, balance, struggle for, concentration of.","cn":"固定搭配标出用法：夺取、掌握、平衡、争夺、集中。"},{"en":"Latin had two words for power, one for lawful authority and one for raw force, and English keeps both meanings in one.","cn":"拉丁语有两个表示权力的词，一个指合法权限，一个指原始力量，英语把两种含义都收进了一个词。"},{"en":"The phrase scales from a committee to a continent without changing shape.","cn":"这个短语从委员会扩到整个大陆，形式都不变。"}],"abstract":[{"en":"Picture three people in the middle row whose nods decide the vote.","cn":"想象中间一排三个人，他们点头就决定了表决结果。"},{"en":"Picture a hand on a switch that can stop a whole meeting.","cn":"想象一只手放在开关上，可以叫停整场会议。"},{"en":"Picture a list of questions from which one item has been quietly removed.","cn":"想象一张问题清单，其中一项被悄悄划掉了。"}]},"examples":[{"en":"Landowners held political power long after the votes were widened.","cn":"在选举权扩大很久之后，地主仍掌握着政治权力。"},{"en":"The army's political power grew with every crisis.","cn":"军队的政治权力随每一次危机而增长。"},{"en":"Broadcasting gave the small state political power beyond its size.","cn":"广播让这个小国获得了超出其规模的政治权力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「城邦的 + 能够」——能让众人之事按自己的意思定下来 → 政治权力","word":"political power"},"root":"political 出自希腊 politikos「公民的、城邦的」，源头 polis「城邦」；power 经古法语出自拉丁 posse「能够」，由 potis「有能力的」与 esse「是」构成。potis 更深来源不确定。","sensesIntro":{"en":"Eight senses measure one capacity: to sway decisions, to hold an office, to command force, to attract, to be counted as a variable, to weigh against other states, to set the agenda, and finally to bind a group.","cn":"八个义项衡量同一种能力：左右决定、占据职位、指挥武力、吸引他人、被当作变量计数、与他国较量、设定议程，最后是把一个群体约束起来。"},"semanticMap":{"core":{"en":"CORE IMAGE: three swing votes in the middle row deciding a bill.","cn":"核心意象：中间一排的三张摇摆票决定了一项议案。"},"chain":["BEING ABLE","SWAYING DECISIONS","HOLDING OFFICE","COMMANDING FORCE","ATTRACTING OTHERS","BINDING A GROUP"],"branches":[{"senses":"01","en":"ABILITY: the base sense is simply being able to change what is decided.","cn":"能力：基础义就是能够改变被决定之事。"},{"senses":"02 · 03","en":"INSTITUTIONAL FORMS: ability is converted into lawful office, and office is backed by force.","cn":"制度形态：能力被转换为合法职位，而职位又以武力为后盾。"},{"senses":"04","en":"SOFT FORM: attraction and persuasion achieve the same result without a single order.","cn":"柔性形态：吸引与说服不下一道命令也能得到同样结果。"},{"senses":"05 · 06","en":"COUNTED AND COMPARED: the concept becomes a variable in research and a balance between states.","cn":"计数与比较：这个概念在研究中成为变量，在国家之间成为均势。"},{"senses":"07 · 08","en":"AGENDA AND BINDING: keeping a question off the table is power, and the final test is a decision all must follow.","cn":"议程与约束：把一个问题挡在桌外也是权力，而最终的检验是所有人都必须遵从的决定。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek civic adjective to a Latin verb of ability, and both halves have produced large English families.","cn":"这个短语把希腊的城邦形容词与拉丁语中表示能力的动词接在一起，两半都衍生出庞大的英语词族。"},"latinIntro":{"en":"Latin posse, potestas and potentia supply power, powerful, potent and potential; politicus supplies the civic half.","cn":"拉丁 posse、potestas 与 potentia 衍生出权力、有权势的、有力的与潜在的；politicus 提供城邦那一半。"},"items":[{"word":"polis","structure":"polis (Greek noun, 'city-state')","meaning":"city-state","meaningCN":"城邦","example":"The qualifier limits the noun to public affairs.","exampleCN":"这个限定语把名词收窄到公共事务。"},{"word":"potis","structure":"potis (Latin adjective, 'able')","meaning":"capable","meaningCN":"有能力的","example":"The adjective supplies the idea of capability.","exampleCN":"这个形容词提供「有能力」的意思。"},{"word":"posse","structure":"potis + esse (irregular verb)","meaning":"to be able","meaningCN":"能够","example":"The verb is the source of the whole power family.","exampleCN":"这个动词是整族权力词的源头。"},{"word":"potestas","structure":"posse + -tas (abstract noun)","meaning":"lawful power, authority","meaningCN":"合法权力；权限","example":"The noun named power that is permitted.","exampleCN":"这个名词指被允许的权力。"},{"word":"potentia","structure":"potens + -ia (abstract noun)","meaning":"force, influence","meaningCN":"力量；影响力","example":"The noun named power as raw force.","exampleCN":"这个名词指作为原始力量的权力。"},{"word":"power","structure":"Old French poeir, from Latin posse","meaning":"ability; authority","meaningCN":"能力；权威","example":"Power entered English in the thirteenth century.","exampleCN":"power 在十三世纪进入英语。"},{"word":"powerful","structure":"power + -ful (full of)","meaning":"having much power","meaningCN":"拥有大量权力的","example":"A powerful ministry can ignore a weak one.","exampleCN":"强势的部可以无视弱势的部。"},{"word":"powerless","structure":"power + -less (without)","meaning":"having no power","meaningCN":"没有权力的","example":"Voters felt powerless between elections.","exampleCN":"选民在两次选举之间感到无力。"},{"word":"potential","structure":"potentia + -al","meaning":"possible, not yet actual","meaningCN":"潜在的；尚未实现的","example":"The same root yields the word for what could be.","exampleCN":"同一词根还造出表示「可能如此」的词。"}],"latinEntries":[{"word":"posse","structure":"posse, potui (irregular verb)","meaning":"to be able","meaningCN":"能够"},{"word":"potestas","structure":"potestas, potestatis (f., third declension)","meaning":"power, authority","meaningCN":"权力；权限"},{"word":"potentia","structure":"potentia, potentiae (f., first declension)","meaning":"force, influence","meaningCN":"力量；影响力"},{"word":"potis","structure":"potis, pote (adjective, third declension)","meaning":"able, capable","meaningCN":"有能力的"}]}},{"word":"state","ipa_uk":"/steɪt/","ipa_us":"/steɪt/","definition_zh":"状态；状况；国家；州；政府（尤指作为政治实体）；陈述、声明（动词）；物质状态；（系统）状态","definition_en":"the condition something is in, a politically organised country or one of its units, the government itself, or the act of expressing something in words","core_image":"实验室里，样品放上冷台，读数一路下降，液体凝成固体","scene":"实验室里，技术员把样品放上冷台，温度读数一路下降，样品由液态凝成固态。At that temperature the substance passes into a solid state.","sceneCN":"这里指「物质的状态」，对应第 6 个义项：物质在某一温度下呈现的形态；句意为在那个温度下，这种物质转入固态。画面要点：冷台、温度读数、凝成固体的样品。","pos":[{"tag":"n.","zh":"状态；状况；情形"},{"tag":"n.","zh":"国家；州；政府（常与定冠词连用）"},{"tag":"v.","zh":"陈述；声明；说明"}],"collocations":[{"phrase":"state of emergency","zh":"紧急状态"},{"phrase":"state of matter","zh":"物质状态（固、液、气等）"},{"phrase":"member state","zh":"成员国"},{"phrase":"head of state","zh":"国家元首"},{"phrase":"state-owned","zh":"国有的"},{"phrase":"in a poor state","zh":"状况不佳"},{"phrase":"the state and civil society","zh":"国家与公民社会"}],"forms":[{"label":"三单（he/she/it）","form":"states"},{"label":"过去式","form":"stated"},{"label":"过去分词","form":"stated"},{"label":"现在分词","form":"stating"},{"label":"复数（作名词）","form":"states"},{"label":"名词（陈述；声明）","form":"statement"},{"label":"形容词（国有的；由国家提供的）","form":"state-owned"}],"derivatives":[{"word":"statement","pos":"n.","zh":"陈述；声明；报表"},{"word":"stately","pos":"adj.","zh":"庄重的；堂皇的"},{"word":"stateless","pos":"adj.","zh":"无国籍的；无国家归属的"},{"word":"statehood","pos":"n.","zh":"国家地位；州的地位"},{"word":"statesman","pos":"n.","zh":"政治家；国务家"}],"senses":[{"no":"01","title":"The condition something is in","titleCN":"某物所处的状态或状况","definition":"the particular condition of a person, object or system at a given time","definitionCN":"人、物体或系统在某一时刻所处的具体状况","example":"The house was in a poor state after the winter.","exampleCN":"过冬之后，这栋房子状况很差。","why":"the Latin noun behind it named a standing position, so the word begins as where something stands, not what it is.","whyCN":"它背后的拉丁名词指「站立的姿势、所处的位置」，因此这个词最初说的是某物站在何处，而不是它是什么。"},{"no":"02","title":"A politically organised country","titleCN":"有政治组织的国家","definition":"a sovereign community with a territory, a population and a government","definitionCN":"拥有领土、人口与政府的自主政治共同体","example":"The treaty created two new states from one empire.","exampleCN":"这项条约从一个帝国里造出两个新国家。","why":"a community that stands firm is pictured as a body that holds its ground, and the political sense grows from that standing.","whyCN":"一个稳固站立的共同体被想成一个守得住地盘的身体，政治义正是从这种「站立」生长出来的。"},{"no":"03","title":"A unit inside a federation","titleCN":"联邦体制内的一个州","definition":"one of the constituent territories of a federal country, with its own government","definitionCN":"联邦国家中的一个组成地区，拥有自己的政府","example":"Water law differs from state to state.","exampleCN":"水法各州不同。","why":"when a union is built from standing parts, each part keeps the name of a state in its own right.","whyCN":"当一个联合体由各自站立的部件组成时，每个部件本身就保留了「国家」这个名称。"},{"no":"04","title":"The government as an apparatus","titleCN":"作为一套机器的政府","definition":"the institutions of public authority, often set against the market or civil society","definitionCN":"公共权威的机构总体，常被放在市场或公民社会的对面","example":"The state, not the market, set the price of bread.","exampleCN":"定面包价格的是国家，不是市场。","why":"the abstract community becomes concrete when its offices, courts and police are meant, and the article the marks that shift.","whyCN":"当所指是它的机关、法院与警察时，抽象共同体就变得具体，前面的定冠词标记的正是这一转变。"},{"no":"05","title":"To say something formally","titleCN":"正式地陈述或声明","definition":"to express a fact, position or requirement in words, especially in writing","definitionCN":"用文字表达事实、立场或要求，尤指书面形式","example":"The rules state that every complaint must be dated.","exampleCN":"规则写明，每份投诉都必须注明日期。","why":"to set a matter out is to give it a standing form, and the verb keeps that image of placing something firmly.","whyCN":"把一件事摆出来，就是给它一个固定的形态，这个动词保留了「把某物稳稳放下」的意象。"},{"no":"06","title":"A physical phase of matter","titleCN":"物质的物理形态","definition":"one of the forms a substance takes, such as solid, liquid or gas","definitionCN":"物质呈现的形态之一，如固态、液态或气态","example":"At that temperature the substance passes into a solid state.","exampleCN":"在那个温度下，这种物质转入固态。","why":"physics borrowed the general word for condition because a phase is exactly a condition that a substance is in.","whyCN":"物理学借用了这个表示状况的通用词，因为相正是物质所处的一种状况。"},{"no":"07","title":"Ceremonial dignity","titleCN":"仪式上的排场与尊严","definition":"in older usage, the pomp of an office, as in a body lying in state before burial","definitionCN":"较早用法中指职位的排场，如遗体在安葬前供公众瞻仰","example":"The hall was prepared for the coffin to lie in state.","exampleCN":"大厅已布置好，供灵柩停放瞻仰。","why":"standing on display is the literal core of the word, and ceremony is standing made visible.","whyCN":"「陈列地站立」正是这个词的字面核心，而仪式就是把这种站立变得可见。"},{"no":"08","title":"A configuration in a system","titleCN":"系统在某一刻的配置","definition":"in computing and engineering, the stored condition of a system at one moment, from which its next step follows","definitionCN":"在计算与工程中，系统在某一刻被记录的配置，下一步行为由它决定","example":"The machine restores its previous state after a crash.","exampleCN":"机器在崩溃后会恢复到先前的状态。","why":"the technical sense is the old sense of condition made countable, so that a program can hold it, copy it and return to it.","whyCN":"技术义是把旧的「状况」义变得可计数，好让程序能够保存、复制并回到它。"}],"etymology":{"intro":{"en":"State came through Old French from a Latin noun of standing, built on the verb to stand, and English has kept both the idea of a condition and the idea of a body politic. Dates are approximate.","cn":"state 经古法语出自一个表示「站立」的拉丁名词，该名词立在「站立」这一动词上；英语同时保留了「状况」与「政治共同体」两种意思。年代均为约数。"},"items":[{"era":"LATIN STARE","en":"Stare meant 'to stand, stand firm, remain'; the Indo-European root behind it is reconstructed, so any earlier form cited is a reconstruction rather than an attested word.","cn":"stare 意为「站立、站稳、停留」；它背后的印欧语词根属重构，因此凡为其引出的更早形式都是重构形式，而非有书证的词。"},{"era":"LATIN STATUS","en":"Status, a noun of standing, meant 'position, condition, rank', and it is the direct source of the English word.","cn":"status 这个表示「站立」的名词意为「位置、状况、等级」，它正是英语这个词的直接来源。"},{"era":"LATIN STATUERE","en":"Statuere 'to set up, establish' was formed from the same stem and gave English statute and statue, so setting something upright and declaring a rule are related images.","cn":"statuere「设立、确立」由同一词干构成，并衍生出英语中的法规与雕像，因此「把某物立起来」与「宣告一条规则」本是相通的意象。"},{"era":"OLD FRENCH ESTAT","en":"Old French estat meant condition, position and also the order of society, and it entered English in the fourteenth century as state.","cn":"古法语 estat 指状况、位置，也指社会的等级秩序，它在十四世纪以 state 的形式进入英语。"},{"era":"POLITICAL BODY","en":"By the sixteenth century the state named the body politic and its government, and writers on sovereignty made it the central object of politics.","cn":"到十六世纪，state 已指政治共同体及其政府，讨论主权的作者把它确立为政治的核心对象。"},{"era":"VERB AND TECHNICAL SENSES","en":"The verb 'to state' is recorded from the sixteenth century, and the scientific sense of a phase of matter settled in the seventeenth, followed much later by the computing sense of a stored configuration.","cn":"动词「陈述」自十六世纪有书证，物质形态这一科学义在十七世纪确定，而「被记录的配置」这一计算义则晚得多才出现。"}]},"similar":{"note":{"en":"Group one holds words that look like state but come from a different formation or meaning; group two holds words for a country or a condition with a narrower scope.","cn":"第一组是形似 state、但构词或含义不同的词；第二组是范围更窄、表示国家或状况的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"status","ipa":"/ˈsteɪtəs/","tag":"rank, not condition","definition":"The Latin form kept in English for rank, legal standing or current progress, as marital status or status update.","definitionCN":"英语保留的拉丁原形，指等级、法律地位或当前进展，如婚姻状况或状态更新。"},{"word":"estate","ipa":"/ɪˈsteɪt/","tag":"property","definition":"Land and property, or the whole of a person's assets; it comes from the same Old French word but specialised in ownership.","definitionCN":"指土地财产，或一个人的全部资产；出自同一个古法语词，但专指所有权。"},{"word":"stately","ipa":"/ˈsteɪtli/","tag":"dignified","definition":"An adjective for a dignified, imposing manner or building; it keeps the ceremonial sense rather than the political one.","definitionCN":"形容庄重、有气派的举止或建筑；保留的是仪式义，而非政治义。"},{"word":"statement","ipa":"/ˈsteɪtmənt/","tag":"the noun of saying","definition":"Something said or written formally; it is the product of the verb, not the country.","definitionCN":"正式说出或写下的内容；它是动词的产物，不是国家。"}]},{"heading":"NEAR MEANING","entries":[{"word":"condition","ipa":"/kənˈdɪʃən/","tag":"state as circumstance","definition":"The circumstances something is in, especially when they can be good or bad; it is the closest synonym of the first sense.","definitionCN":"某物所处的境况，尤指可好可坏的情形；是第一个义项最接近的同义词。"},{"word":"nation","ipa":"/ˈneɪʃən/","tag":"people, not institutions","definition":"A people sharing a identity and usually a territory; a state is the political and legal structure, which may contain several nations.","definitionCN":"共享认同、通常也共享领土的人民；国家是政治与法律结构，可能包含多个民族。"},{"word":"government","ipa":"/ˈɡʌvənmənt/","tag":"the current rulers","definition":"The body that governs at a particular time; the state is the enduring structure, while a government can change at an election.","definitionCN":"在某一时期治理的机构；国家是长久的结构，而政府可在选举中更换。"},{"word":"commonwealth","ipa":"/ˈkɒmənwelθ/","tag":"shared welfare","definition":"A political community founded for common good, and a name used by some states; it stresses shared benefit rather than authority.","definitionCN":"为共同利益建立的政治共同体，也是某些国家的正式名称；强调共同受益，而非权威。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin base means to stand, so a state is where something stands, and a nation is a community that stands firm.","cn":"拉丁词根意为站立，所以 state 指某物站立之处，而国家是一个站稳的共同体。"},{"en":"The family runs statement, stately, stateless, statehood and statesman.","cn":"同族词包括声明、庄重的、无国籍的、国家地位与国务家。"},{"en":"Fixed phrases sort the uses: state of emergency, state of matter, member state, head of state.","cn":"固定搭配给用法分类：紧急状态、物质状态、成员国、国家元首。"},{"en":"The same word is a noun for a condition and a verb for saying something formally.","cn":"同一个词既是表示状况的名词，也是表示正式陈述的动词。"},{"en":"The pair to keep apart is state as structure and government as the current set of rulers.","cn":"要分清的一对是作为结构的国家与作为当下执政者的政府。"}],"abstract":[{"en":"Picture a stone standing upright in a field to mark where a boundary runs.","cn":"想象田野里立着一块石头，标出边界经过之处。"},{"en":"Picture a sealed jar with a label describing exactly what is inside it today.","cn":"想象一只密封罐，标签上写明今天里面装的究竟是什么。"},{"en":"Picture a saved position on a board game, so play can resume from it.","cn":"想象棋盘上被记下的一个局面，好让对局能从那里接着下。"}]},"examples":[{"en":"The states agreed to a common standard for the grid.","cn":"各州同意为电网采用统一标准。"},{"en":"The report stated the cost without estimating the benefit.","cn":"报告写明了成本，却没有估算收益。"},{"en":"Water can exist in all three states within one valley.","cn":"在同一条山谷里，水能以三种状态存在。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「站立」——站成什么样子就是什么状态；站稳成一体就是国家 → 状态、国家","word":"state"},"root":"state 经古法语 estat 出自拉丁 status「位置、状况、等级」，而 status 是 stare「站立」的名词形式；stare 背后的印欧语词根属重构形式。","sensesIntro":{"en":"Eight senses stand on one verb: where something stands gives its condition, a community that stands firm is a country, its parts are states, its offices are the state, setting a matter out is to state it, a phase is a condition, display is standing made visible, and a stored position is a state again.","cn":"八个义项都立在同一个「站立」动词上：某物站在何处就是它的状况，站稳的共同体是国家，它的组成部分是州，它的机关就是国家，把事摆出来就是陈述，一个相就是一种状况，陈列是把站立变得可见，而被记下的位置又回到「状态」。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stone standing upright in a field, marking where a line runs.","cn":"核心意象：田野里立着的一块石头，标出界线经过之处。"},"chain":["STANDING","WHERE IT STANDS","A STANDING COMMUNITY","ITS PARTS AND OFFICES","SETTING OUT IN WORDS","A SAVED POSITION"],"branches":[{"senses":"01 · 06","en":"CONDITION: whether of a house or of a substance, the word names where a thing stands now.","cn":"状况：无论指房屋还是物质，这个词都指某物此刻所处的位置。"},{"senses":"02 · 03","en":"COMMUNITY AND PART: a community that holds its ground is a country, and each standing part of a union keeps the name.","cn":"共同体与部分：守得住地盘的共同体是国家，而联合体中每个独立的部分也保留这个名称。"},{"senses":"04","en":"APPARATUS: the offices, courts and police turn the abstract community into a visible machine.","cn":"机器：机关、法院与警察把抽象的共同体变成一台可见的机器。"},{"senses":"05","en":"DECLARING: to set a matter out in words is to give it a fixed standing form.","cn":"陈述：用文字把一件事摆出来，就是给它一个固定的形态。"},{"senses":"07 · 08","en":"DISPLAY AND STORAGE: ceremony makes standing visible, and a machine saves a position so play can resume.","cn":"陈列与存储：仪式让站立变得可见，而机器保存一个位置，好让进程能接着走。"}]},"affixes":{"intro":{"en":"State is a Latin noun of standing that English took through French, and the same stem builds statute, statue and stable.","cn":"state 是一个表示「站立」的拉丁名词，英语经法语借入；同一词干还造出法规、雕像与稳定的。"},"latinIntro":{"en":"Latin stare, status and statuere stand behind state, status, statute, statue and stability.","cn":"拉丁 stare、status 与 statuere 是 state、status、法规、雕像与稳定性的来源。"},"items":[{"word":"stare","structure":"stare (Latin verb, 'to stand')","meaning":"to stand, remain","meaningCN":"站立；停留","example":"The verb supplies the image of standing firm.","exampleCN":"这个动词提供「稳立不动」的意象。"},{"word":"status","structure":"stare + -tus (verbal noun)","meaning":"position, condition","meaningCN":"位置；状况","example":"The noun names where a thing stands.","exampleCN":"这个名词指出某物所处的位置。"},{"word":"statuere","structure":"stare + causative ending","meaning":"to set up, establish","meaningCN":"设立；确立","example":"The verb gives the idea of setting something upright.","exampleCN":"这个动词带来「把某物立起来」的意思。"},{"word":"-ment","structure":"-ment (noun suffix of result)","meaning":"the result of an act","meaningCN":"行为的结果","example":"The ending turns the verb of saying into a thing said.","exampleCN":"这个词尾把「说」的动词变成说出的内容。"},{"word":"statement","structure":"state + -ment","meaning":"something stated","meaningCN":"所陈述的内容","example":"The statement was issued at noon.","exampleCN":"声明在正午发布。"},{"word":"stately","structure":"state + -ly (adjective ending)","meaning":"dignified","meaningCN":"庄重的","example":"A stately hall was built for the ceremony.","exampleCN":"为这场仪式建了一座气派的大厅。"},{"word":"stateless","structure":"state + -less (without)","meaning":"without a nationality","meaningCN":"无国籍的","example":"The war left thousands stateless.","exampleCN":"战争让成千上万人失去国籍。"},{"word":"statehood","structure":"state + -hood (condition)","meaning":"the condition of being a state","meaningCN":"国家地位","example":"Statehood was recognised after the vote.","exampleCN":"表决之后，国家地位获得承认。"},{"word":"statute","structure":"statuere + -tum (thing set up)","meaning":"a written law","meaningCN":"成文法规","example":"A statute fixed the term of the office.","exampleCN":"一条法规确定了该职位的任期。"}],"latinEntries":[{"word":"stare","structure":"stare, steti, statum (verb, first conjugation)","meaning":"to stand, remain","meaningCN":"站立；停留"},{"word":"status","structure":"status, status (m., fourth declension)","meaning":"position, condition, rank","meaningCN":"位置；状况；等级"},{"word":"statuere","structure":"statuere, statui, statutum (verb, third conjugation)","meaning":"to set up, establish","meaningCN":"设立；确立"}]}}]);
